INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('7bd8951e-8693-423f-ae6f-f56713813262'::uuid, 'card_description', 'The Roman settlement was granted the rank of municipium around AD 50, meaning its citizens had what were known as "Latin Rights", a lesser citizenship status than a colonia possessed.', 'Before Verulamium, Tasciovanus minted coins at a Catuvellauni tribal centre in the area. Watling Street ran through the Roman town, which became a municipium around AD 50.', 'teaser-card-s019:7bd8951e-8693-423f-ae6f-f56713813262:card_description', 'teaser-card-s019 (teaser-card): teaser card, 171 characters, checked PASS, web-verified VERIFIED', '0de19b932bcd1f7df84ce32ff8d752e6e98d3175d4b9c309e35a274d3242333e|5f70efbdb4fe489528762d29d4aa1da8c1fac55884a2997ed30e5138209f8bb8|5f70efbdb4fe489528762d29d4aa1da8c1fac55884a2997ed30e5138209f8bb8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Before Verulamium, Tasciovanus minted coins at a Catuvellauni tribal centre in the area. Watling Street ran through the Roman town, which became a municipium around AD 50."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "before the Roman town there was a tribal centre in the area [S4]; the tribal centre belonged to the Catuvellauni [S4]; Tasciovanus minted coins at that settlement [S5, S6]; Watling Street ran through the Roman town [S3]; the Roman town became a municipium around AD 50 [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Verulamium was a town in Roman Britain, southwest of the modern city of St Albans in Hertfordshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Verulamium]; Before the Roman town there was already a tribal centre in the area that belonged to the Catuvellauni [SUPPORTED: https://en.wikipedia.org/wiki/Verulamium]; Tasciovanus minted coins at that pre-Roman settlement [SUPPORTED: https://en.wikipedia.org/wiki/Verulamium]; Watling Street ran through the Roman town [SUPPORTED: https://en.wikipedia.org/wiki/Verulamium]; The Roman town became a municipium around AD 50 [SUPPORTED: https://en.wikipedia.org/wiki/Verulamium]"}]'::jsonb),
    ('7c94cfe0-8dc8-4286-acf4-dc994bd79853'::uuid, 'card_description', 'The monument includes a slight univallate hillfort situated on a prominent hill overlooking the valleys of two separate tributaries to the River Lowman.', 'On a prominent hill above two tributaries of the River Lowman, the Iron Age hillfort of Huntsham Castle rings an area approximately 150m in diameter with a rampart up to 2.9m high outside.', 'teaser-card-s019:7c94cfe0-8dc8-4286-acf4-dc994bd79853:card_description', 'teaser-card-s019 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '2ebc06949fb262480f66a4f8717b553b627c3894c451270468e7367ffb0c1233|59626b2f2740c8e7d5c8a88fac85c176c1ea3a128301b73256f4d442ca7ac8c1|59626b2f2740c8e7d5c8a88fac85c176c1ea3a128301b73256f4d442ca7ac8c1', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a prominent hill above two tributaries of the River Lowman, the Iron Age hillfort of Huntsham Castle rings an area approximately 150m in diameter with a rampart up to 2.9m high outside."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Huntsham Castle stands on a prominent hill [S2]; the hill overlooks two tributaries of the River Lowman [S2]; Huntsham Castle is an Iron Age hillfort [S1, S2]; the enclosure measures approximately 150m in diameter [S3]; the enclosure is bounded by a rampart [S4]; the rampart is up to 2.9m high externally [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Huntsham Castle is a hillfort enclosure near the village of Huntsham, Devon, England [SUPPORTED: https://en.wikipedia.org/wiki/Huntsham_Castle]; The hillfort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Huntsham_Castle]; The hillfort stands on a prominent hill [SUPPORTED: https://en.wikipedia.org/wiki/Huntsham_Castle]; The hill overlooks the valleys of two tributaries of the River Lowman [SUPPORTED: https://en.wikipedia.org/wiki/Huntsham_Castle]; The enclosure measures approximately 150m in diameter [SUPPORTED: https://en.wikipedia.org/wiki/Huntsham_Castle]; The rampart is up to 2.9m high outside [SUPPORTED: https://en.wikipedia.org/wiki/Huntsham_Castle]"}]'::jsonb),
    ('7cd35ee0-c6fb-4215-a37f-ee5de2255a8f'::uuid, 'card_description', 'Capital of the Carnutes on the Loire, stormed by Julius Caesar in 52 BC during the Gallic Wars. Locals who resisted Roman law faced massacres — the town was nearly wiped from the map.', 'On the Loire, Cenabum was the capital of the Carnutes, a thriving oppidum that controlled a bridge built before the Roman conquest. In 52 BC, Julius Caesar took the town.', 'teaser-card-s019:7cd35ee0-c6fb-4215-a37f-ee5de2255a8f:card_description', 'teaser-card-s019 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', '92b9928cf13ca44052d52c11bd3ad3b7e8925ccb45afc8b54c7efe96c8d2efe9|84e20c6cd8bdfaaea92fd15443a8878c4e976aaed8105a21cef4b1c9fa8d24da|84e20c6cd8bdfaaea92fd15443a8878c4e976aaed8105a21cef4b1c9fa8d24da', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the Loire, Cenabum was the capital of the Carnutes, a thriving oppidum that controlled a bridge built before the Roman conquest. In 52 BC, Julius Caesar took the town."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cenabum lay on the Loire [S2]; Cenabum was the capital of the Carnutes [S1]; Cenabum was a thriving oppidum [S2]; it controlled a bridge over the Loire [S6]; the bridge was built before the Roman conquest [S6]; in 52 BC Julius Caesar took the town [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cenabum was the capital of the Carnutes, near present-day Orleans [SUPPORTED: https://en.wikipedia.org/wiki/Cenabum]; Cenabum lay on the Loire [SUPPORTED: https://en.wikipedia.org/wiki/Cenabum]; Cenabum was an oppidum [SUPPORTED: https://en.wikipedia.org/wiki/Cenabum]; Cenabum was a thriving town [SUPPORTED: https://en.wikipedia.org/wiki/Cenabum]; Cenabum controlled a bridge over the Loire [SUPPORTED: https://en.wikipedia.org/wiki/Cenabum]; The bridge was built before the Roman conquest [SUPPORTED: https://en.wikipedia.org/wiki/Cenabum]; In 52 BC Julius Caesar took the town [SUPPORTED: https://en.wikipedia.org/wiki/Cenabum]"}]'::jsonb),
    ('7cf17ac2-f8e5-43a4-a31d-3c89370c7cea'::uuid, 'card_description', 'The hill overlooks the Winterbourne Valley to the north and the Piddle Valley to the south; immediately to the west is Bere Stream.', 'Woodbury Hill, Dorset, overlooks the Winterbourne Valley to the north and the Piddle Valley to the south. An annual fair was held here from medieval times until the mid 20th century.', 'teaser-card-s019:7cf17ac2-f8e5-43a4-a31d-3c89370c7cea:card_description', 'teaser-card-s019 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '828ac3f64e9a492ca94d5b54be417f21a8fd47b185748525d102986729d7ba9a|b031f3625342d0c4aa536bcc31f14503aa66ec44fa310841d6842450fec87464|b031f3625342d0c4aa536bcc31f14503aa66ec44fa310841d6842450fec87464', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Woodbury Hill, Dorset, overlooks the Winterbourne Valley to the north and the Piddle Valley to the south. An annual fair was held here from medieval times until the mid 20th century."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Woodbury Hill overlooks the Winterbourne Valley to the north [S3]; it overlooks the Piddle Valley to the south [S3]; an annual fair was held on the hill [S2]; the fair ran from medieval times [S2]; the fair ran until the mid 20th century [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Woodbury Hill is a hill in Dorset, England, near Bere Regis [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Hill,_Dorset]; Woodbury Hill is the site of an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Hill,_Dorset]; The hill overlooks the Winterbourne Valley to the north [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Hill,_Dorset]; The hill overlooks the Piddle Valley to the south [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Hill,_Dorset]; An annual fair was held at Woodbury Hill [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Hill,_Dorset]; The fair was held from medieval times [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Hill,_Dorset]; The fair was held until the mid 20th century [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Hill,_Dorset]"}]'::jsonb),
    ('7cfc73a7-180b-4378-a14a-785e9cab28a4'::uuid, 'card_description', 'Siponto was an ancient port town and bishopric of Magna Graecia in Apulia. In 189 BC it became a Roman colony with the name Sipontum.', NULL, 'teaser-card-s019:7cfc73a7-180b-4378-a14a-785e9cab28a4:card_description', 'teaser-card-s019 (card-clear-contradicted-after-verify): card cleared (contradicted-after-verify)', '||9c30943decd70affc214cb4eae0f359003b8300933a8e98167fc3c0aed69caf7', '[{"source": "lane WB run wb-ws-2026-09-27-06: contradicted-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The web check contradicts: Siponto became a Roman colony in 189 BC (https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.04.0006%3Aentry%3Dsipontum: \"The Romans subjugated the town and made it a colony in 194 B.C. (Livy 34.45).\"); The web check contradicts: In 663 AD Siponto was taken and destroyed by the Slavs (https://www.treccani.it/enciclopedia/siponto_%28Enciclopedia-Italiana%29/: \"Fu poi depredata da Slavoni (642), da Longobardi, da Saraceni.\"); The web check contradicts: The Slavs'' attack on Siponto was in 642 (the article dates the Slavs'' capture of Siponto to 663, not 642) (https://en.wikipedia.org/wiki/Siponto: \"In 663 AD it was taken and destroyed by the Slavs.\")"}]'::jsonb),
    ('7d356160-ee86-4110-974a-2c77e02eb710'::uuid, 'card_description', 'The earliest traces of human activity at the site date to the Final Neolithic period, and consist of two stone celts and several fragments of pottery.', 'Overlooking the Gulf of Mirabello at 427 m, Kavousi Vronda holds a Dark Age settlement and an Early Iron Age cemetery, and its earliest traces include two Final Neolithic stone celts.', 'teaser-card-s019:7d356160-ee86-4110-974a-2c77e02eb710:card_description', 'teaser-card-s019 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '2330a6bbcf42c0e28fb6d5541d85307865733b3fafba90fdf3ef1ea59da947d0|9124e0888ace1423c3c1b758d2620d78bb087f1dad73e5e3cf3124b83d33878a|9124e0888ace1423c3c1b758d2620d78bb087f1dad73e5e3cf3124b83d33878a', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Overlooking the Gulf of Mirabello at 427 m, Kavousi Vronda holds a Dark Age settlement and an Early Iron Age cemetery, and its earliest traces include two Final Neolithic stone celts."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site overlooks the Gulf of Mirabello [S2]; the site lies at an elevation of 427 m [S2]; most of the visible remains are a Dark Age settlement [S3]; the site has an Early Iron Age cemetery [S3]; the earliest traces of human activity date to the Final Neolithic [S4, S5]; the earliest traces include two stone celts [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Kavousi Vronda is an archaeological site (a Dark Age settlement with a later cemetery) in eastern Crete, Greece, in the northern foothills of the Thripti Mountains overlooking the Gulf of Mirabello [SUPPORTED: https://en.wikipedia.org/wiki/Kavousi_Vronda]; The site overlooks the Gulf of Mirabello [SUPPORTED: https://en.wikipedia.org/wiki/Kavousi_Vronda]; The site lies at an elevation of 427 m [SUPPORTED: https://en.wikipedia.org/wiki/Kavousi_Vronda]; The site holds a Dark Age settlement [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Kavousi_Vronda]; The site holds an Early Iron Age cemetery [SUPPORTED: https://en.wikipedia.org/wiki/Kavousi_Vronda]; The earliest traces of human activity at the site are Final Neolithic and include two stone celts [SUPPORTED: https://en.wikipedia.org/wiki/Kavousi_Vronda]"}]'::jsonb),
    ('7d453e37-a8d8-4124-a619-e7cdc54f8223'::uuid, 'card_description', 'A large sarsen stone that once stood upright as part of a 4000 BC long barrow. Now it lies flat — the tomb it marked has been completely destroyed.', 'The Coffin Stone, a sarsen slab 4.42 metres long, lies near Aylesford. Farmers reportedly found human bones by it in the 1830s, yet it was placed here only in the 15th or 16th centuries.', 'teaser-card-s019:7d453e37-a8d8-4124-a619-e7cdc54f8223:card_description', 'teaser-card-s019 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '0e0f2d3f3fb457f317279d6a226d2c6640b768206e820114a3b4950d23f8f0cd|2399133ec0c5270aaa2e42cd9546055ce3bc86242ee5ac9f60d70b9398a56848|2399133ec0c5270aaa2e42cd9546055ce3bc86242ee5ac9f60d70b9398a56848', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Coffin Stone, a sarsen slab 4.42 metres long, lies near Aylesford. Farmers reportedly found human bones by it in the 1830s, yet it was placed here only in the 15th or 16th centuries."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Coffin Stone is a sarsen stone slab [S1, S2]; the slab is 4.42 metres long [S2]; it lies near Aylesford [S1]; in the 1830s it was reported that farmers found human bones near the stone [S4]; the stone was placed in its present location only in the 15th or 16th centuries [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Coffin Stone is a large stone (megalith) lying near Aylesford in Kent, England [SUPPORTED: https://en.wikipedia.org/wiki/Coffin_Stone]; The Coffin Stone is made of sarsen [SUPPORTED: https://en.wikipedia.org/wiki/Coffin_Stone]; The Coffin Stone is a slab [SUPPORTED: https://en.wikipedia.org/wiki/Coffin_Stone]; The slab is 4.42 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Coffin_Stone]; Local farmers reportedly found human bones near the stone [SUPPORTED: https://en.wikipedia.org/wiki/Coffin_Stone]; The bones were reported in the 1830s [SUPPORTED: https://en.wikipedia.org/wiki/Coffin_Stone]; The stone was placed in its present location only in the 15th or 16th centuries [SUPPORTED: https://en.wikipedia.org/wiki/Coffin_Stone]"}]'::jsonb),
    ('7df3ac64-8a51-4a51-aeb0-7b99c1e9c196'::uuid, 'card_description', 'The park contains more than 15 sites and nine architectural elements that are ethnologically interesting.', 'On a hill whose name means Moorish Peak, the Puig de sa Morisca Archaeological Park holds more than 15 sites, among them the Son Ferrer tomb, excavated from 2000 through 2009.', 'teaser-card-s019:7df3ac64-8a51-4a51-aeb0-7b99c1e9c196:card_description', 'teaser-card-s019 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '523b5275373fb7f6b64c4eb134a46deec31b291ee61b49788b838e9dc35d1f4e|d6b9c456bbc68ba4b9256a30651e467e32f8b67cd1347c217239a54824497f4c|d6b9c456bbc68ba4b9256a30651e467e32f8b67cd1347c217239a54824497f4c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a hill whose name means Moorish Peak, the Puig de sa Morisca Archaeological Park holds more than 15 sites, among them the Son Ferrer tomb, excavated from 2000 through 2009."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the park stands on a hill whose name means Moorish Peak [S2]; the park holds more than 15 sites [S3]; the Son Ferrer tomb is one of the park''s sites [S4]; the Son Ferrer tomb was excavated from 2000 through 2009 [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Puig de sa Morisca Archaeological Park is an archaeological park (on a hill) at Santa Ponsa, Calvia, Majorca, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Puig_de_sa_Morisca_Archaeological_Park]; The name Puig de sa Morisca means Moorish Peak and it is a hill [SUPPORTED: https://en.wikipedia.org/wiki/Puig_de_sa_Morisca_Archaeological_Park]; The park holds more than 15 sites [SUPPORTED: https://en.wikipedia.org/wiki/Puig_de_sa_Morisca_Archaeological_Park]; The Son Ferrer tomb is one of the sites in the park [SUPPORTED: https://en.wikipedia.org/wiki/Puig_de_sa_Morisca_Archaeological_Park]; The Son Ferrer tomb was excavated from 2000 through 2009 [SUPPORTED: https://en.wikipedia.org/wiki/Puig_de_sa_Morisca_Archaeological_Park]"}]'::jsonb),
    ('7eac65e7-44b9-4af0-b658-ca0c035b0e19'::uuid, 'card_description', 'Sunken boats at the bottom of a small lake, dating to the 1st–2nd century BC. Archaeologists identified them as Illyrian ships — a rare find of ancient watercraft.', 'In 2007, many sunken boats were uncovered in a small lake at Desilo, believed to be Illyrian ships of the first and second centuries B.C. and covered with fragments of amphorae.', 'teaser-card-s019:7eac65e7-44b9-4af0-b658-ca0c035b0e19:card_description', 'teaser-card-s019 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '28f35caef1c81c64af41569fc490b38b88ab05cdeb086a4007c5c23c80f7b945|242e0cd336e3e33b86e27780ab8f19da3afccc37001656ef8976ad01e4fc31be|242e0cd336e3e33b86e27780ab8f19da3afccc37001656ef8976ad01e4fc31be', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In 2007, many sunken boats were uncovered in a small lake at Desilo, believed to be Illyrian ships of the first and second centuries B.C. and covered with fragments of amphorae."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "in 2007 many sunken boats were uncovered [S2]; the boats lay in a small lake at Desilo [S2]; archaeologists believe the boats to be Illyrian ships [S3]; the ships are believed to date to the first and second centuries B.C. [S3]; the ships were covered with fragments of amphorae [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Desilo is an underwater archaeological site in Bosnia and Herzegovina [SUPPORTED: https://en.wikipedia.org/wiki/Desilo]; The boats lay in a small lake at Desilo [SUPPORTED: https://en.wikipedia.org/wiki/Desilo]; In 2007 many sunken boats were uncovered at Desilo [SUPPORTED: https://en.wikipedia.org/wiki/Desilo]; The boats are believed to be Illyrian ships [SUPPORTED: https://en.wikipedia.org/wiki/Desilo]; The ships are believed to date to the first and second centuries B.C. [SUPPORTED: https://en.wikipedia.org/wiki/Desilo]; The boats were covered with fragments of amphorae [SUPPORTED: https://en.wikipedia.org/wiki/Desilo]"}]'::jsonb),
    ('7f9cea0c-abb9-41c8-b475-76703db262f3'::uuid, 'card_description', 'A Magna Graecia colony from 700 BC where the philosopher Pythagoras spent his final years and died. Fifteen standing columns of its temple of Hera still rise from the coastal plain.', 'On the gulf of Tarentum lay Metapontum, a city of Magna Graecia that seems to have been flourishing and opulent. It sought strict neutrality in 415 BCE, then allied with Athens.', 'teaser-card-s019:7f9cea0c-abb9-41c8-b475-76703db262f3:card_description', 'teaser-card-s019 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '5b2570a5144c5bd79fa62de3daf7b05c712996669541918f632f80ee562883a4|6e2aa40fe6b7bf13383c6164c5aea778b531ffd8f153179f918df1939e738dc9|6e2aa40fe6b7bf13383c6164c5aea778b531ffd8f153179f918df1939e738dc9', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the gulf of Tarentum lay Metapontum, a city of Magna Graecia that seems to have been flourishing and opulent. It sought strict neutrality in 415 BCE, then allied with Athens."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Metapontum lay on the gulf of Tarentum [S1]; Metapontum was a city of Magna Graecia [S1]; Metapontum seems to have been flourishing and opulent (hedged) [S5]; Metapontum sought strict neutrality in 415 BCE [S4]; Metapontum then allied with Athens [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Metapontum was an ancient city of Magna Graecia (southern Italy), a Greek colony [SUPPORTED: https://en.wikipedia.org/wiki/Metapontum]; Metapontum lay on the gulf of Tarentum [SUPPORTED: https://en.wikipedia.org/wiki/Metapontum]; Metapontum was a flourishing and opulent city (at the time of the Athenian expedition to Sicily) [SUPPORTED: https://en.wikipedia.org/wiki/Metapontum]; In 415 BCE Metapontum sought to maintain a strict neutrality [SUPPORTED: https://en.wikipedia.org/wiki/Metapontum]; After the neutrality Metapontum entered into an alliance with Athens [SUPPORTED: https://en.wikipedia.org/wiki/Metapontum]"}]'::jsonb),
    ('80260626-f0b7-4a1a-95e4-5f26bcfe1ecd'::uuid, 'card_description', 'The walls of the chamber are 6 metres in height, while the corridor profile is 180 centimetres in height.', 'In the central Alentejo, the Great Dolmen of Comenda da Igreja hides a funerary chamber beneath a granite slab, its walls 6 metres high and its corridor just 180 centimetres tall.', 'teaser-card-s019:80260626-f0b7-4a1a-95e4-5f26bcfe1ecd:card_description', 'teaser-card-s019 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '20f1ca55016ac9b9ed9ddfab765ff493f32061c6aae9e85288c09d4afa4a5c42|a3302adff3833028275c99240b9372603e66b5e7fe87cc996e09b0eb0b4da637|a3302adff3833028275c99240b9372603e66b5e7fe87cc996e09b0eb0b4da637', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the central Alentejo, the Great Dolmen of Comenda da Igreja hides a funerary chamber beneath a granite slab, its walls 6 metres high and its corridor just 180 centimetres tall."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is in the central Alentejo (Portugal) [S1]; the Great Dolmen of Comenda da Igreja is a funerary site with a funerary chamber [S1, S2]; the main chamber is covered by a granite slab [S2]; the walls of the chamber are 6 metres high [S3]; the corridor is 180 centimetres tall [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Great Dolmen of Comenda da Igreja is a megalithic funerary site (a dolmen tomb) in the central Alentejo region of Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Great_Dolmen_of_Comenda_da_Igreja]; The dolmen has a central chamber [SUPPORTED: https://en.wikipedia.org/wiki/Great_Dolmen_of_Comenda_da_Igreja]; The main chamber is covered by a granite slab [SUPPORTED: https://en.wikipedia.org/wiki/Great_Dolmen_of_Comenda_da_Igreja]; The walls of the chamber are 6 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Great_Dolmen_of_Comenda_da_Igreja]; The corridor is 180 centimetres tall [SUPPORTED: https://en.wikipedia.org/wiki/Great_Dolmen_of_Comenda_da_Igreja]"}]'::jsonb),
    ('805a50cd-f05e-4f4d-b7af-395948a00fff'::uuid, 'card_description', 'Stanwix is built on the site of a Roman fort known as Uxelodunum or Petriana, the former meaning "high fort".', 'Stanwix is built on Uxelodunum, the Roman high fort, largest on Hadrian''s Wall. Probably most of its Roman masonry was taken to build other buildings, yet in 2017 a bathhouse came to light.', 'teaser-card-s019:805a50cd-f05e-4f4d-b7af-395948a00fff:card_description', 'teaser-card-s019 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '970902bd486d4d875c59bedf0c9b44d1299ab65b14ff1309ffc33be6a66c021a|254788093fed3d8cecd9646db4e383dcf380772e2684559cc018d6fed3a57ac6|254788093fed3d8cecd9646db4e383dcf380772e2684559cc018d6fed3a57ac6', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Stanwix is built on Uxelodunum, the Roman high fort, largest on Hadrian''s Wall. Probably most of its Roman masonry was taken to build other buildings, yet in 2017 a bathhouse came to light."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Stanwix is built on the site of the Roman fort Uxelodunum [S1]; Uxelodunum means high fort [S1]; the fort was the largest on Hadrian''s Wall [S2]; probably most of the Roman masonry was taken to build other buildings (hedged) [S3]; a bathhouse was discovered in 2017 [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Stanwix (a district of Carlisle, England) is built on the site of Uxelodunum, a Roman fort [SUPPORTED: https://en.wikipedia.org/wiki/Stanwix]; The name Uxelodunum means high fort [SUPPORTED: https://en.wikipedia.org/wiki/Uxelodunum]; Uxelodunum was the largest fort on Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Uxelodunum]; Probably most of the Roman masonry of the fort was taken to build other buildings [SUPPORTED: https://en.wikipedia.org/wiki/Stanwix]; In 2017 a bathhouse was discovered (at Carlisle Cricket Club''s Edenside ground in Stanwix) [SUPPORTED: https://en.wikipedia.org/wiki/Stanwix]"}]'::jsonb),
    ('81be53ae-7297-4cf9-8f9f-96f6ac1ebfe8'::uuid, 'card_description', 'A collapsed Neolithic dolmen with one standing stone 1.6 meters high and a fallen capstone. Much of the structure was destroyed after its 18th-century excavation.', 'All that can be seen of West Lanyon Quoit in Cornwall are two large stones: a support still standing, and a capstone 4.1 metres long resting against it, once covered by a large barrow mound.', 'teaser-card-s019:81be53ae-7297-4cf9-8f9f-96f6ac1ebfe8:card_description', 'teaser-card-s019 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '471ff59c3e80f92f1083e509a3dcfd65213d153a355d6844bc417891b24efce3|bc9f96847db377f5855f0ede3aa3dada91cf05548536649af7cb77e74c293a7b|bc9f96847db377f5855f0ede3aa3dada91cf05548536649af7cb77e74c293a7b', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "All that can be seen of West Lanyon Quoit in Cornwall are two large stones: a support still standing, and a capstone 4.1 metres long resting against it, once covered by a large barrow mound."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "West Lanyon Quoit is in Cornwall [S1]; all that can be seen today are two large stones [S5]; one support stone is still standing [S6]; a capstone rests against the support stone [S7]; the capstone is 4.1 metres long [S7]; the quoit was once covered by a large barrow mound [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "West Lanyon Quoit is the remains of a prehistoric dolmen (a tomb) [SUPPORTED: https://en.wikipedia.org/wiki/West_Lanyon_Quoit]; It is in Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/West_Lanyon_Quoit]; All that can be seen of the monument today is two large stones [SUPPORTED: https://en.wikipedia.org/wiki/West_Lanyon_Quoit]; One support stone is still standing [SUPPORTED: https://en.wikipedia.org/wiki/West_Lanyon_Quoit]; The capstone is 4.1 metres long [SUPPORTED: https://en.wikipedia.org/wiki/West_Lanyon_Quoit]; The capstone rests against the standing support stone [SUPPORTED: https://en.wikipedia.org/wiki/West_Lanyon_Quoit]; The monument was once covered by a large barrow mound [SUPPORTED: https://en.wikipedia.org/wiki/West_Lanyon_Quoit]"}]'::jsonb),
    ('82f23c96-d8b2-41f0-a3e5-59ae9b89880c'::uuid, 'card_description', 'The upper part of the construction is an entablature made up of architrave, frieze and cornice.', 'On the line of the old Via Augusta rises the Arc de Berà, erected under Augustus around 13 BC: a single opening, its body decorated with fluted pilasters crowned by Corinthian capitals.', 'teaser-card-s019:82f23c96-d8b2-41f0-a3e5-59ae9b89880c:card_description', 'teaser-card-s019 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'e779a044dc5e59f0fff3ecc74680a2ddfb0ecc84776f2f6b1b7c843fe46070b1|eed43d4f1e7eee239346f4d1bcb9d4712eb025c975e87b3787aff1cba0f4c376|eed43d4f1e7eee239346f4d1bcb9d4712eb025c975e87b3787aff1cba0f4c376', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the line of the old Via Augusta rises the Arc de Berà, erected under Augustus around 13 BC: a single opening, its body decorated with fluted pilasters crowned by Corinthian capitals."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Arc de Berà stands on the line of the old Via Augusta [S3]; it was erected under Augustus [S7]; it was erected around 13 BC [S7]; it is an arch with a single opening [S5]; its body is decorated with fluted pilasters [S5]; the pilasters are crowned by Corinthian capitals [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Arc de Berà is a triumphal arch near Tarragona, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Arc_de_Ber%C3%A0]; It stands on the line of the old Via Augusta [SUPPORTED: https://en.wikipedia.org/wiki/Arc_de_Ber%C3%A0]; It was erected in the reign of Augustus [SUPPORTED: https://en.wikipedia.org/wiki/Arc_de_Ber%C3%A0]; It was erected around 13 BC [SUPPORTED: https://en.wikipedia.org/wiki/Arc_de_Ber%C3%A0]; The arch has a single opening [SUPPORTED: https://en.wikipedia.org/wiki/Arc_de_Ber%C3%A0]; The body of the arch is decorated with fluted pilasters [SUPPORTED: https://en.wikipedia.org/wiki/Arc_de_Ber%C3%A0]; The fluted pilasters are crowned by Corinthian capitals [SUPPORTED: https://en.wikipedia.org/wiki/Arc_de_Ber%C3%A0]"}]'::jsonb),
    ('83822807-fe8c-4ca5-946e-17c5e7c5cf25'::uuid, 'card_description', 'Three successive temples at Delphi from the 7th to 4th centuries BC, each replacing its predecessor. The famous Tholos stands in the same sanctuary.', 'At Delphi, three temples rose in turn over an older cult site, possibly dedicated to Gaia. The first Temple of Athena Pronaia was probably the earliest Doric temple; twelve columns survive.', 'teaser-card-s019:83822807-fe8c-4ca5-946e-17c5e7c5cf25:card_description', 'teaser-card-s019 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '06e14085fe899b7a315669f9fa95b45775a3d909266accefc5551a6d53a72113|6348d9b5e90adfd9ee5a86c0ee97c836022ec698d239babee628403881476870|6348d9b5e90adfd9ee5a86c0ee97c836022ec698d239babee628403881476870', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "At Delphi, three temples rose in turn over an older cult site, possibly dedicated to Gaia. The first Temple of Athena Pronaia was probably the earliest Doric temple; twelve columns survive."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the temple is at Delphi [S1]; three temples were built in succession at the site [S2, S3]; an older cult site lay at this spot [S4]; the older cult site was possibly dedicated to Gaia [S4]; the first temple dedicated to Athena was probably the earliest Doric temple [S6, S7]; twelve columns of it survive [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Temple of Athena Pronaia is a temple at Delphi (Greece), in the Sanctuary of Athena Pronaia [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_Pronaia]; Three temples were built in turn at the site [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_Pronaia]; The temples rose over an older cult site [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_Pronaia]; The older cult site was possibly dedicated to Gaia [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_Pronaia]; The first temple of Athena Pronaia (temple A) was built in the 7th century BC [SUPPORTED: https://delphi.culture.gr/the-temple-of-athina-pronaina/]; The first temple was probably the earliest Doric temple (its remains the earliest Doric architectural remains) [SUPPORTED: https://delphi.culture.gr/the-temple-of-athina-pronaina/]; Twelve columns of the first temple survive [SUPPORTED: https://delphi.culture.gr/the-temple-of-athina-pronaina/]"}]'::jsonb),
    ('8382ce85-cfd3-485e-b738-58f21611091e'::uuid, 'card_description', 'A medieval village formed along the King''s Road, with eight estates by the 16th century. Recent excavations reveal daily life under Swedish rule in remarkable detail.', 'Mankby grew along the King''s Road, a village of eight estates. In 1556 King Gustav I moved its people out for a royal mansion; it lay mostly forgotten until foundations were found in 2004.', 'teaser-card-s019:8382ce85-cfd3-485e-b738-58f21611091e:card_description', 'teaser-card-s019 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '416c48560d99662b725d8b10dbd27682f8e07a37f977e621566bafb306689611|84b7c817cb21712b6587b324e14bf3badf8f4f2b262b6a803bf4f8d15faca4df|84b7c817cb21712b6587b324e14bf3badf8f4f2b262b6a803bf4f8d15faca4df', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Mankby grew along the King''s Road, a village of eight estates. In 1556 King Gustav I moved its people out for a royal mansion; it lay mostly forgotten until foundations were found in 2004."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the village of Mankby was formed along the King''s Road [S3]; the village consisted of eight estates [S4]; in 1556 King Gustav I decided on a royal mansion and the village''s people were moved elsewhere [S6]; the village was mostly forgotten after it was abandoned [S7]; foundations were found in 2004 [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Mankby was a village (a settlement) in Finland, in today''s Espoo [SUPPORTED: https://en.wikipedia.org/wiki/Mankby]; The village grew (was formed) along the King''s Road [SUPPORTED: https://en.wikipedia.org/wiki/Mankby]; The village consisted of eight estates [SUPPORTED: https://en.wikipedia.org/wiki/Mankby]; In 1556 King Gustav I moved its people out to found a royal mansion [SUPPORTED: https://en.wikipedia.org/wiki/Mankby]; After the removal the site lay abandoned and mostly forgotten [SUPPORTED: https://en.wikipedia.org/wiki/Mankby]; Foundations were found in 2004 [SUPPORTED: https://en.wikipedia.org/wiki/Mankby]"}]'::jsonb),
    ('8438e161-08c5-48a3-88dd-923b99b9bdd6'::uuid, 'card_description', 'Roman villas buried and preserved by Vesuvius in 79 AD. One villa, the Villa Regina, is the only one still visible -- the others were reburied after excavation.', 'Buried and preserved by the eruption of Vesuvius in 79 AD, Villa Boscoreale gave up exquisite frescoes and a sumptuous treasure. Only the Villa Regina is still visible in situ today.', 'teaser-card-s019:8438e161-08c5-48a3-88dd-923b99b9bdd6:card_description', 'teaser-card-s019 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'c7a616c8a0d0ad4d3da047eda37752465f26677c77ca1691650ce18623b27c80|4d69a3ac5f92c6fe4fa6fa74aa0da468e299b230b9a48de72dc6ff45debf355f|4d69a3ac5f92c6fe4fa6fa74aa0da468e299b230b9a48de72dc6ff45debf355f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Buried and preserved by the eruption of Vesuvius in 79 AD, Villa Boscoreale gave up exquisite frescoes and a sumptuous treasure. Only the Villa Regina is still visible in situ today."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the villa was buried and preserved by the eruption of Vesuvius [S2]; the eruption took place in 79 AD [S2]; the Villa Boscoreale finds include exquisite frescoes [S5, S1]; the finds include a sumptuous treasure [S5, S1]; only the Villa Regina is still visible in situ today [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Villa Boscoreale is a name given to Roman villas in the district of Boscoreale, Italy [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Boscoreale]; The villas were buried and preserved by the eruption of Vesuvius in 79 AD [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Boscoreale]; The Boscoreale villas gave up exquisite frescoes [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Boscoreale]; The Boscoreale villas gave up a sumptuous treasure [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Boscoreale]; Only the Villa Regina is still visible in situ today [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Boscoreale]"}]'::jsonb),
    ('85664eb7-5761-407b-854b-aec846d137e6'::uuid, 'card_description', 'A Roman road whose medieval name means "road to the bath town" -- it led to the spa at Buxton. Sections of the original route are now protected monuments.', 'Batham Gate means road to the bath town: a Roman road running from the River Don to the spa town of Buxton, where in 1862 the oldest inscribed milestone found in Derbyshire turned up.', 'teaser-card-s019:85664eb7-5761-407b-854b-aec846d137e6:card_description', 'teaser-card-s019 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'e50497196de35d8235082763bce1d4ce9548274c58039c013b690022785e80cc|38fe3a4f0f3ed3903f62212aea22044ae4da97a69eaf7f40b19f17326fad3992|38fe3a4f0f3ed3903f62212aea22044ae4da97a69eaf7f40b19f17326fad3992', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Batham Gate means road to the bath town: a Roman road running from the River Don to the spa town of Buxton, where in 1862 the oldest inscribed milestone found in Derbyshire turned up."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the name Batham Gate means road to the bath town [S2]; Batham Gate is a Roman road [S1]; it ran from the River Don (Templebrough) to Buxton [S1]; Buxton is a spa town [S1]; a Roman milestone was found in Buxton in 1862 [S6]; the milestone is the oldest inscribed milestone found in Derbyshire [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Batham Gate is a Roman road (in Derbyshire, England) [SUPPORTED: https://en.wikipedia.org/wiki/Batham_Gate]; The name Batham Gate means road to the bath town [SUPPORTED: https://en.wikipedia.org/wiki/Batham_Gate]; The road ran from the River Don (Templebrough) [SUPPORTED: https://en.wikipedia.org/wiki/Batham_Gate]; The road ran to Buxton, a spa town [SUPPORTED: https://en.wikipedia.org/wiki/Batham_Gate]; A Roman milestone was found at Buxton [SUPPORTED: https://en.wikipedia.org/wiki/Batham_Gate]; The milestone was found in 1862 [SUPPORTED: https://en.wikipedia.org/wiki/Batham_Gate]; That milestone is the oldest inscribed milestone found in Derbyshire [SUPPORTED: https://en.wikipedia.org/wiki/Batham_Gate]"}]'::jsonb),
    ('8627799e-bfb9-4667-bbc6-d30ebdd99703'::uuid, 'card_description', 'A 43-meter passage grave ending in a small chamber roofed with a single slab. The corridor narrows steadily — you enter standing and finish crouching.', 'Under a mound near Seville, the Dolmen de la Pastora runs 43 metres to a circular chamber beneath a single granite capstone. Unlike similar tombs nearby, it is orientated towards the sunset.', 'teaser-card-s019:8627799e-bfb9-4667-bbc6-d30ebdd99703:card_description', 'teaser-card-s019 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '4b65a1c40f71034c6b4c0b2b6a81c033d3ed57fdfb1c88cc81a785620b24c1be|77df2fe91fe59b7223d5e6be41db438634747c1b404bfddd89711bd54236803e|77df2fe91fe59b7223d5e6be41db438634747c1b404bfddd89711bd54236803e', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Under a mound near Seville, the Dolmen de la Pastora runs 43 metres to a circular chamber beneath a single granite capstone. Unlike similar tombs nearby, it is orientated towards the sunset."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the dolmen lies under a mound [S3]; it is near Seville [S1]; it is a 43-metre long gallery [S4]; the passage ends in a circular chamber [S5]; the chamber is roofed with a single granite capstone [S5]; unlike other similar tombs in the region, it is orientated towards the sunset [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Dolmen de la Pastora is a tomb (a prehistoric passage grave) near Seville, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_la_Pastora]; It lies under a mound [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_la_Pastora]; The passage (gallery) is 43 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_la_Pastora]; The passage ends in a circular chamber [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_la_Pastora]; The chamber is roofed by a single granite capstone [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_la_Pastora]; It is orientated towards the sunset [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_la_Pastora]; Similar tombs nearby (in the region) tend to face sunrise instead [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_la_Pastora]"}]'::jsonb),
    ('86d27903-d193-4c17-b760-072129d86c0b'::uuid, 'card_description', 'The last fort at the western end of Hadrian''s Wall, perched on a 15-metre sea cliff. It was the largest fort on the entire Wall, built over the eightieth milecastle position.', 'On a sea-cliff over 50 feet high above the Solway Firth stood Mais, the last fort at the western end of Hadrian''s Wall and its second largest, first of turf and clay, then rebuilt in stone.', 'teaser-card-s019:86d27903-d193-4c17-b760-072129d86c0b:card_description', 'teaser-card-s019 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'aa7778c56164575d7ffe1a71463461b077d613a13f79950896adb703652f8769|b825df26895bcad53f01978077ff92851ed10f7f8879628de7f509d18b901353|b825df26895bcad53f01978077ff92851ed10f7f8879628de7f509d18b901353', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a sea-cliff over 50 feet high above the Solway Firth stood Mais, the last fort at the western end of Hadrian''s Wall and its second largest, first of turf and clay, then rebuilt in stone."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the fort stood on a sea-cliff over 50 feet high [S3]; it overlooked the Solway Firth [S1]; it was the last fort at the western end of Hadrian''s Wall [S1]; it was the second largest fort on the Wall [S2]; it was first built with a turf and clay rampart [S4]; it was later rebuilt in stone [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Mais (Bowness) was a Roman fort on Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Mais_(Bowness)]; It overlooked the Solway Firth and was the last fort at the western end of Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Mais_(Bowness)]; The fort stood on a sea-cliff over 50 feet high [SUPPORTED: https://en.wikipedia.org/wiki/Mais_(Bowness)]; It was the second largest fort on Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Mais_(Bowness)]; It was first built of turf and clay [SUPPORTED: https://en.wikipedia.org/wiki/Mais_(Bowness)]; It was later rebuilt in stone [SUPPORTED: https://en.wikipedia.org/wiki/Mais_(Bowness)]"}]'::jsonb),
    ('871fbe6a-2eb0-4d28-b2bf-1a58d9e5766c'::uuid, 'card_description', 'An ancient Black Sea port that was a Greek colony of Mesembria. The Romans named it Templum Iovis, Temple of Jupiter, reflecting its sacred significance.', 'Obzor has worn several names: Naulochos to Thracians and Greeks, a small port and colony of Mesembria; Templum Iovis, the Temple of Jupiter, to the Romans; and Tetranaulochus to Pliny.', 'teaser-card-s019:871fbe6a-2eb0-4d28-b2bf-1a58d9e5766c:card_description', 'teaser-card-s019 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'd9273763714e28bef839618ba460c33c46ced4d8d24c1d949ce46359ff8b99d2|5e4899c3b37c7abc0a00f447a4605c35c0715b260125f5844a3d65c58257e17d|5e4899c3b37c7abc0a00f447a4605c35c0715b260125f5844a3d65c58257e17d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Obzor has worn several names: Naulochos to Thracians and Greeks, a small port and colony of Mesembria; Templum Iovis, the Temple of Jupiter, to the Romans; and Tetranaulochus to Pliny."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Obzor has been known by several names [S1]; Naulochos was the name used by Thracians and Greeks [S1, S2]; Naulochos was a small port [S3]; Naulochos was a colony of Mesembria [S3]; the Romans called it Templum Iovis [S1, S4]; Templum Iovis means Temple of Jupiter [S4]; Pliny called it Tetranaulochus [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-045 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Obzor is a settlement (a seaside town, in antiquity a small port) in Bulgaria [SUPPORTED: https://en.wikipedia.org/wiki/Obzor]; Obzor has had several names over time [SUPPORTED: https://en.wikipedia.org/wiki/Obzor]; Its name was Naulochos to the Thracians [SUPPORTED: https://en.wikipedia.org/wiki/Obzor]; Its name was Naulochos to the Greeks [SUPPORTED: https://en.wikipedia.org/wiki/Obzor]; Naulochos was a small port [SUPPORTED: https://en.wikipedia.org/wiki/Obzor]; Naulochos was a colony of Mesembria [SUPPORTED: https://en.wikipedia.org/wiki/Obzor]; The Romans called it Templum Iovis [SUPPORTED: https://en.wikipedia.org/wiki/Obzor]; Templum Iovis means the Temple of Jupiter [SUPPORTED: https://en.wikipedia.org/wiki/Obzor]; Pliny called it Tetranaulochus [SUPPORTED: https://en.wikipedia.org/wiki/Obzor]"}]'::jsonb),
    ('87b7df7d-023f-43ce-b644-4c12394a8f9f'::uuid, 'card_description', 'The Għajn Tuffieħa Roman Baths were discovered in 1929 during government works to cap a fresh water spring in the area.', 'In 1929, workers capping a fresh water spring uncovered the Għajn Tuffieħa Roman Baths. Baths that needed a constant flow of water may owe their place here to that spring, or one like it.', 'teaser-card-s019:87b7df7d-023f-43ce-b644-4c12394a8f9f:card_description', 'teaser-card-s019 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '3d089d99f6e212a21373de752e253b46b0781c999d28d4b40f7752e1cf351027|111559d72bd0cafecbdd28c85405829da7791dcb5f19656eba2fae3230761465|111559d72bd0cafecbdd28c85405829da7791dcb5f19656eba2fae3230761465', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In 1929, workers capping a fresh water spring uncovered the Għajn Tuffieħa Roman Baths. Baths that needed a constant flow of water may owe their place here to that spring, or one like it."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the baths were discovered in 1929 [S1]; the discovery came during works to cap a fresh water spring [S1]; the baths needed a constant flow of water [S2]; the spring, or a similar one, may explain why the baths were built at this place [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-045 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Għajn Tuffieħa Roman Baths are a Roman bath complex (thermae) at Għajn Tuffieħa, Mġarr, in Malta [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ajn_Tuffie%C4%A7a_Roman_Baths]; The baths were discovered in 1929 [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ajn_Tuffie%C4%A7a_Roman_Baths]; The discovery was made by workers capping a fresh water spring [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ajn_Tuffie%C4%A7a_Roman_Baths]; Baths need a constant flow of water, and the spring (or a similar one) may explain why these baths were built here [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ajn_Tuffie%C4%A7a_Roman_Baths]"}]'::jsonb),
    ('87dcefc2-025d-458b-9418-16e4bac7d17f'::uuid, 'card_description', 'The site was excavated in the 1950s by Sir Ian Richmond and his final report was published in 1969.', 'The Durotriges held Hod Hill in the late Iron Age, but whether their tribe first fortified it is unknown; radiocarbon suggests 500 BC for the main rampart. Then came a Roman camp.', 'teaser-card-s019:87dcefc2-025d-458b-9418-16e4bac7d17f:card_description', 'teaser-card-s019 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'e62999d7f665c8f84a562ba7bfc88acc75b1037dbd59870d4f6b76c6c4a5eb4f|d2cac7fbf2680b3f4f4a85d4017a742d358c739d4529cc113a0a4e323656f25f|d2cac7fbf2680b3f4f4a85d4017a742d358c739d4529cc113a0a4e323656f25f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Durotriges held Hod Hill in the late Iron Age, but whether their tribe first fortified it is unknown; radiocarbon suggests 500 BC for the main rampart. Then came a Roman camp."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Durotriges inhabited the hillfort in the late Iron Age [S5]; it is unknown whether the Durotriges are the same tribe that first fortified the hilltop [S5]; radiocarbon analysis suggests 500 BC for the main rampart [S5]; the Romans built a camp in the original fort after it [S6, S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-045 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Hod Hill is a hill fort in Dorset, England [SUPPORTED: https://en.wikipedia.org/wiki/Hod_Hill]; The Durotriges held (inhabited) Hod Hill in the late Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Hod_Hill]; It is unknown whether the Durotriges were the tribe that first fortified the hill [SUPPORTED: https://en.wikipedia.org/wiki/Hod_Hill]; Radiocarbon analysis suggests a date of 500 BC for the main rampart [SUPPORTED: https://en.wikipedia.org/wiki/Hod_Hill]; A Roman camp was later built at Hod Hill [SUPPORTED: https://en.wikipedia.org/wiki/Hod_Hill]"}]'::jsonb),
    ('880170da-bad3-44c5-a994-0bf644eb4ead'::uuid, 'card_description', 'A major Early Bronze Age cemetery dated 2600–2300 BC with a fortified settlement nearby. Part of the Keros-Syros Cycladic culture known for its marble figurines.', 'On Syros, the Early Bronze Age tombs of Chalandriani all face between northwest and northeast, and yielded so-called frying pans, some with longboat motifs almost unknown elsewhere.', 'teaser-card-s019:880170da-bad3-44c5-a994-0bf644eb4ead:card_description', 'teaser-card-s019 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'bbc5c999f144d92ddf6b44d19abd05e9923df847f4671d49853d2f2e545334e3|d363755c0281a87c08f5214823a74af1ff99a27db8b25405ad53da435a3e8cd7|d363755c0281a87c08f5214823a74af1ff99a27db8b25405ad53da435a3e8cd7', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On Syros, the Early Bronze Age tombs of Chalandriani all face between northwest and northeast, and yielded so-called frying pans, some with longboat motifs almost unknown elsewhere."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Chalandriani is on Syros [S1]; the tombs are Early Bronze Age [S1]; the tombs all face between northwest and northeast [S4]; the grave goods include so-called frying pans [S3]; some of the frying pans are decorated with longboat motifs [S3]; the longboat motifs are almost unknown from other sites [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-045 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Chalandriani is a cemetery of tombs, in Greece [SUPPORTED: https://en.wikipedia.org/wiki/Chalandriani]; Chalandriani lies on the island of Syros [SUPPORTED: https://en.wikipedia.org/wiki/Chalandriani]; The tombs of Chalandriani are Early Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Chalandriani]; The tombs of Chalandriani all face between northwest and northeast [SUPPORTED: https://en.wikipedia.org/wiki/Chalandriani]; The tombs yielded so-called frying pans among their grave goods [SUPPORTED: https://en.wikipedia.org/wiki/Chalandriani]; Some of the frying pans are decorated with longboat motifs [SUPPORTED: https://en.wikipedia.org/wiki/Chalandriani]; Longboat motifs on frying pans are almost unknown from other sites [SUPPORTED: https://en.wikipedia.org/wiki/Chalandriani]"}]'::jsonb),
    ('882c38f5-5b59-47b8-b6df-27f6d07b7abe'::uuid, 'card_description', 'A 3rd-century BC corbel arch bridge: 3.95-metre span, opening cut in unmortared limestone as an isosceles triangle 1.84 metres high. Remarkably large for a false-arch structure.', 'Near Eleutherna on Crete, unmortared limestone blocks frame a triangular opening 1.84 m high: the Eleutherna Bridge, an ancient Greek false arch with a span of 3.95 m, still in use.', 'teaser-card-s019:882c38f5-5b59-47b8-b6df-27f6d07b7abe:card_description', 'teaser-card-s019 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'ea71a2a585898c98861ddd667f31adb878d0db84b05c956e9098fb85d4fe01a5|4c8caa71173b3efaf05c10663b87529ff28a487044b473dc34a0ea025575c299|4c8caa71173b3efaf05c10663b87529ff28a487044b473dc34a0ea025575c299', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near Eleutherna on Crete, unmortared limestone blocks frame a triangular opening 1.84 m high: the Eleutherna Bridge, an ancient Greek false arch with a span of 3.95 m, still in use."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the bridge is near Eleutherna on Crete [S1]; the opening is cut from unmortared limestone blocks [S3]; the opening is triangular [S3]; the opening is 1.84 m high [S3]; it is an ancient Greek bridge with a false arch [S1, S2]; the span is 3.95 m [S2]; the bridge is still in use [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-045 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Eleutherna Bridge is an ancient Greek bridge near Eleutherna [SUPPORTED: https://en.wikipedia.org/wiki/Eleutherna_Bridge]; Eleutherna, and so the bridge, is on Crete [SUPPORTED: https://en.wikipedia.org/wiki/Eleutherna_Bridge]; The bridge has a false (corbel) arch [SUPPORTED: https://en.wikipedia.org/wiki/Eleutherna_Bridge]; The opening is framed by unmortared limestone blocks [SUPPORTED: https://en.wikipedia.org/wiki/Eleutherna_Bridge]; The opening is triangular [SUPPORTED: https://en.wikipedia.org/wiki/Eleutherna_Bridge]; The triangular opening is 1.84 m high [SUPPORTED: https://en.wikipedia.org/wiki/Eleutherna_Bridge]; The bridge has a span of 3.95 m [SUPPORTED: https://en.wikipedia.org/wiki/Eleutherna_Bridge]; The bridge is still in use [SUPPORTED: https://en.wikipedia.org/wiki/Eleutherna_Bridge]"}]'::jsonb),
    ('888edebd-abcc-4eb9-a513-947ddcbe5453'::uuid, 'card_description', 'An Inca site at 3,850 metres elevation with 14 terraces and partial buildings. Located near Chinchero, it may have served as an agricultural storage complex for nearby Inca estates.', 'Above the left bank of the Urubamba River, near the village of Raqch''i, the archaeological site of Machu Colca waits at about 3,850 metres in the Cusco Region. Will you make the climb?', 'teaser-card-s019:888edebd-abcc-4eb9-a513-947ddcbe5453:card_description', 'teaser-card-s019 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '36a18aa9378fa5839201511ee8be6af130861d5e55e8c37dd9c1adbe95c1423f|6a6e38703c535ceda1956805b79a995749e94550dd2390a1bb2eb0af49f4c083|6a6e38703c535ceda1956805b79a995749e94550dd2390a1bb2eb0af49f4c083', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Above the left bank of the Urubamba River, near the village of Raqch''i, the archaeological site of Machu Colca waits at about 3,850 metres in the Cusco Region. Will you make the climb?"}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Machu Colca is an archaeological site [S1]; it lies above the left bank of the Urubamba River [S3]; it is near the village of Raqch''i [S3]; it is at about 3,850 metres of elevation [S3]; it is in the Cusco Region [S2]; the question implies the site sits high up, so a visit means going up (a climb) [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Machu Colca is an archaeological site (central claim: what kind of place it is) [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Colca]; The site is in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Colca]; The site lies in the Cusco Region [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Colca]; The site is at about 3,850 metres elevation [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Colca]; The site is above the Urubamba River [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Colca]; The site is above the left bank (not the right) of the river [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Colca]; The site is near the village of Raqch''i [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Colca]"}]'::jsonb),
    ('88c87513-c453-4b72-9630-287bf1a186c3'::uuid, 'card_description', 'Thirty stone uprights on dry heathland at 330 metres in southwest Shropshire. Local folklore tells of a fairy cow milked by a witch into a sieve — draining it dry and breaking the enchantment forever.', 'Mitchell''s Fold Stone Circle is a Bronze Age ring of dolerite from nearby Stapeley Hill, 353 metres up in Shropshire. Its name may come from Old English for big; many stones are missing.', 'teaser-card-s019:88c87513-c453-4b72-9630-287bf1a186c3:card_description', 'teaser-card-s019 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '7e5c5ff766e5f113d5a45001d15690f8ba2b3fbcdc6dc3ad318ef8fb7ed88900|a0e5d91c52a66d085213e1f6bc1ca15a2b2761e3672af46ce0c7c73e60bc67a5|a0e5d91c52a66d085213e1f6bc1ca15a2b2761e3672af46ce0c7c73e60bc67a5', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Mitchell''s Fold Stone Circle is a Bronze Age ring of dolerite from nearby Stapeley Hill, 353 metres up in Shropshire. Its name may come from Old English for big; many stones are missing."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Mitchell''s Fold Stone Circle is a Bronze Age stone circle (ring) [S1]; its stones are dolerite [S4]; the stones came from nearby Stapeley Hill [S4]; it stands 353 metres up (at a height of 353 m AOD) [S1]; it is in Shropshire [S1]; its name may come from Old English for big [S3]; many of its stones are missing [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Mitchell''s Fold Stone Circle is a stone circle (central claim: what kind of place it is) [SUPPORTED: https://en.wikipedia.org/wiki/Mitchell%27s_Fold]; The circle dates to the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Mitchell%27s_Fold]; The circle is in Shropshire [SUPPORTED: https://en.wikipedia.org/wiki/Mitchell%27s_Fold]; The stones are dolerite [SUPPORTED: https://en.wikipedia.org/wiki/Mitchell%27s_Fold]; The dolerite came from nearby Stapeley Hill [SUPPORTED: https://en.wikipedia.org/wiki/Mitchell%27s_Fold]; The circle lies 353 metres up [SUPPORTED: https://en.wikipedia.org/wiki/Mitchell%27s_Fold]; The name may come from Old English [SUPPORTED: https://en.wikipedia.org/wiki/Mitchell%27s_Fold]; The Old English word means big [SUPPORTED: https://en.wikipedia.org/wiki/Mitchell%27s_Fold]; Many of the stones are missing [SUPPORTED: https://en.wikipedia.org/wiki/Mitchell%27s_Fold]"}]'::jsonb),
    ('8958a97d-425b-4f9c-a503-897815a44756'::uuid, 'card_description', 'Occupied from 2600 to 1300 BC — two concentric wall rings, thousands of arrowheads, and evidence of early copper smelting. Palmela-style points found here spread across the western Iberian peninsula.', 'Thousands of arrowheads came out of the Castro of Vila Nova de São Pedro, a fortified Chalcolithic settlement where a domed kiln fed by a cistern once served the making of ceramics.', 'teaser-card-s019:8958a97d-425b-4f9c-a503-897815a44756:card_description', 'teaser-card-s019 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'eaeeacde20c4f0693206b93f1fd0b951bd0690dae04d8e3e785271777dd04c9e|efe2c85a8895812a2126c948433975aa1cf1cced7e2528eade4d0ce3bdafde4b|efe2c85a8895812a2126c948433975aa1cf1cced7e2528eade4d0ce3bdafde4b', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Thousands of arrowheads came out of the Castro of Vila Nova de São Pedro, a fortified Chalcolithic settlement where a domed kiln fed by a cistern once served the making of ceramics."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "thousands of arrowheads were found at the Castro of Vila Nova de São Pedro [S2]; it is a fortified settlement [S2]; it is Chalcolithic [S1, S2]; it holds the remains of a domed kiln [S3]; the kiln received its water from a cistern [S4]; the kiln group served the making of ceramics [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Castro of Vila Nova de São Pedro is a settlement/archaeological site (central claim: what kind of place it is) [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Vila_Nova_de_S%C3%A3o_Pedro]; The site is Chalcolithic [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Vila_Nova_de_S%C3%A3o_Pedro]; The settlement was fortified [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Vila_Nova_de_S%C3%A3o_Pedro]; Thousands of arrowheads were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Vila_Nova_de_S%C3%A3o_Pedro]; The settlement had a domed kiln [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Vila_Nova_de_S%C3%A3o_Pedro]; The settlement had a cistern [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Vila_Nova_de_S%C3%A3o_Pedro]; The kiln received water from the cistern [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Vila_Nova_de_S%C3%A3o_Pedro]; The kiln served the making of ceramics [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Vila_Nova_de_S%C3%A3o_Pedro]"}]'::jsonb),
    ('89dd0394-47e5-479e-a2a7-6e78b3d7a267'::uuid, 'card_description', 'Castle Hill rises 110 meters above the Thames Valley, its summit enclosed by an Iron Age fort with ditches carved into chalk bedrock. A second wooded hill, Round Hill, reaches 120 meters nearby.', 'Two wooded chalk hills rise from the Thames Valley: Wittenham Clumps. Castle Hill held an Iron Age hill fort whose people caught fish and wild boar and herded cattle and sheep.', 'teaser-card-s019:89dd0394-47e5-479e-a2a7-6e78b3d7a267:card_description', 'teaser-card-s019 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '4ca680e02aff17a029d76c0e08c7cec1954ed2a18faad3a71b20345533fd13fb|bad13e28320f6bed3b012bc2292b02a0ae096e960564fe322822429def9dcad8|bad13e28320f6bed3b012bc2292b02a0ae096e960564fe322822429def9dcad8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Two wooded chalk hills rise from the Thames Valley: Wittenham Clumps. Castle Hill held an Iron Age hill fort whose people caught fish and wild boar and herded cattle and sheep."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Wittenham Clumps are two hills [S1]; the hills are wooded and chalk [S1]; they are in the Thames Valley [S1]; Castle Hill was the site of an Iron Age hill fort [S3]; the Iron Age inhabitants caught fish and wild boar [S6]; the Iron Age inhabitants herded cattle and sheep [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Wittenham Clumps are two hills (central claim: what kind of place it is, with where) [SUPPORTED: https://en.wikipedia.org/wiki/Wittenham_Clumps]; The hills are wooded [SUPPORTED: https://en.wikipedia.org/wiki/Wittenham_Clumps]; The hills are chalk [SUPPORTED: https://en.wikipedia.org/wiki/Wittenham_Clumps]; The hills are in the Thames Valley [SUPPORTED: https://en.wikipedia.org/wiki/Wittenham_Clumps]; Castle Hill held an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Wittenham_Clumps]; The Iron Age inhabitants caught fish and wild boar [SUPPORTED: https://en.wikipedia.org/wiki/Wittenham_Clumps]; The Iron Age inhabitants herded cattle and sheep [SUPPORTED: https://en.wikipedia.org/wiki/Wittenham_Clumps]"}]'::jsonb),
    ('89dd3a0c-d36c-439d-8ccc-f005666e7ec9'::uuid, 'card_description', 'By 650 BC the settlement had grown into a busy port-city with maritime trade extending to the central and western Mediterranean.', 'On San Pantaleo Island in the Stagnone Lagoon, the port-city of Motya kept an artificial lake, the cothon, that long puzzled archaeologists. It is known, too, for its marble Charioteer.', 'teaser-card-s019:89dd3a0c-d36c-439d-8ccc-f005666e7ec9:card_description', 'teaser-card-s019 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'f1288db3dbe7403c99050fc0bba0f39631cd0ceb08145e9122077a1c1b086c7f|edca6f2a789678dc920cb73b904ee73a6566de78a63272fd6c7d97554ce76c2c|edca6f2a789678dc920cb73b904ee73a6566de78a63272fd6c7d97554ce76c2c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On San Pantaleo Island in the Stagnone Lagoon, the port-city of Motya kept an artificial lake, the cothon, that long puzzled archaeologists. It is known, too, for its marble Charioteer."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Motya is on San Pantaleo Island [S1]; it is in the Stagnone Lagoon [S1]; Motya was a port-city [S4]; the cothon is an artificial lake at Motya [S6]; the cothon long puzzled archaeologists (something unexplained) [S6]; Motya is known for its marble Charioteer statue [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Motya was an ancient port-city (central claim: what kind of place it is) [SUPPORTED: https://en.wikipedia.org/wiki/Motya]; Motya was on San Pantaleo Island [SUPPORTED: https://en.wikipedia.org/wiki/Motya]; San Pantaleo Island lies in the Stagnone Lagoon [SUPPORTED: https://en.wikipedia.org/wiki/Motya]; Motya kept an artificial lake, the cothon [SUPPORTED: https://en.wikipedia.org/wiki/Motya]; The cothon long puzzled archaeologists [SUPPORTED: https://en.wikipedia.org/wiki/Motya]; Motya is known for a Charioteer statue [SUPPORTED: https://en.wikipedia.org/wiki/Motya]; The Charioteer is made of marble [SUPPORTED: https://en.wikipedia.org/wiki/Motya]"}]'::jsonb),
    ('8ae2a431-14b9-4900-9b54-e8832b52cea0'::uuid, 'card_description', 'One of a chain of Iron Age hillforts running along a mountain range. Its ramparts follow the summit contours, creating a defended space visible from the valley floor below.', 'Moel y Gaer probably dates from the Iron Age, but no definitive evidence gives the exact period it was occupied. Digs have targeted possible pits and what seems to be a roundhouse.', 'teaser-card-s019:8ae2a431-14b9-4900-9b54-e8832b52cea0:card_description', 'teaser-card-s019 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '0fe332a230fe3bf5832d9fb570cd2ae6dcaa513cc0604f98f295349497bc9d5f|b68ec7d7bf99b59221536863f4e489cd3eedf59af716f2ab5dd97c3969d055e8|b68ec7d7bf99b59221536863f4e489cd3eedf59af716f2ab5dd97c3969d055e8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Moel y Gaer probably dates from the Iron Age, but no definitive evidence gives the exact period it was occupied. Digs have targeted possible pits and what seems to be a roundhouse."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Moel y Gaer probably dates from the Iron Age [S2]; no definitive evidence gives the exact period of occupation (something unknown) [S2]; excavations have targeted possible pits [S5]; excavations have targeted what seems to be a roundhouse [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-047 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Moel y Gaer near Bodfari, Wales, is an Iron Age hillfort (a fort on a summit near Bodfari in Denbighshire) [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Bodfari]; Moel y Gaer probably dates from the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Bodfari]; No definitive evidence establishes the exact period during which the site was occupied (the period is unknown) [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Bodfari]; Excavations (digs) have been carried out at the site and have targeted possible pits [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Bodfari]; The excavations have targeted what seems to be a roundhouse [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Bodfari]"}]'::jsonb),
    ('8b1abd85-fc57-40d7-a4c6-c987d4d0bc29'::uuid, 'card_description', 'Woodland promontory enclosure at 175 metres above the River Bray near South Molton in Devon. The earthwork occupies a natural spur, with the river providing defence to the west.', 'In woodland on a promontory above the River Bray, near South Molton, the earthwork of Bremridge Wood marks an Iron Age enclosure or hill fort, on land once part of a Domesday Book estate.', 'teaser-card-s019:8b1abd85-fc57-40d7-a4c6-c987d4d0bc29:card_description', 'teaser-card-s019 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '53f286457b3097f713b6e0ad9d2e01820b39fc25a1e93d9d5a13344995081abc|b209c7c31e607d391601be7b6e9c56ea44e4e34d145d6cd523db55c0ecd66e41|b209c7c31e607d391601be7b6e9c56ea44e4e34d145d6cd523db55c0ecd66e41', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In woodland on a promontory above the River Bray, near South Molton, the earthwork of Bremridge Wood marks an Iron Age enclosure or hill fort, on land once part of a Domesday Book estate."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is in woodland [S2]; it is on a promontory above the River Bray [S2]; it is near South Molton [S1]; the remains are an earthwork [S2]; the earthwork marks an Iron Age enclosure or hill fort [S1]; the land was once part of a Domesday Book estate [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-047 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Bremridge Wood is the site of an Iron Age enclosure or hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Bremridge_Wood]; The site has an earthwork [SUPPORTED: https://en.wikipedia.org/wiki/Bremridge_Wood]; The site lies near South Molton [SUPPORTED: https://en.wikipedia.org/wiki/Bremridge_Wood]; The earthwork lies in woodland [SUPPORTED: https://en.wikipedia.org/wiki/Bremridge_Wood]; The earthwork lies on a promontory [SUPPORTED: https://en.wikipedia.org/wiki/Bremridge_Wood]; The promontory is above the River Bray [SUPPORTED: https://en.wikipedia.org/wiki/Bremridge_Wood]; The land was once part of a Domesday Book estate [SUPPORTED: https://en.wikipedia.org/wiki/Bremridge_Wood]"}]'::jsonb),
    ('8be0203c-2703-42bd-947d-f0d46b916b71'::uuid, 'card_description', 'A harbour town of ancient Gortyna that housed a famous healing temple of Asclepius. Pilgrims traveled here seeking cures, sleeping in the temple to receive divine dreams.', 'Near modern Lentas lay Leben, a harbour town of ancient Crete serving Gortyna. Its temple of Asclepius was of great celebrity, and on the Peutinger Table its name appears as Ledena.', 'teaser-card-s019:8be0203c-2703-42bd-947d-f0d46b916b71:card_description', 'teaser-card-s019 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'b4258f7511b168cef00388782d3ddc432f4d30f8d0d8c761fd672ce7228ba469|7c2862e000722e58bf81b51e126e947d4feba719b695a89abacc28a3b72d27d2|7c2862e000722e58bf81b51e126e947d4feba719b695a89abacc28a3b72d27d2', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near modern Lentas lay Leben, a harbour town of ancient Crete serving Gortyna. Its temple of Asclepius was of great celebrity, and on the Peutinger Table its name appears as Ledena."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is near modern Lentas [S5]; Leben was a harbour town of ancient Crete [S1]; it served Gortyna (was a harbour of Gortyna) [S1]; it had a temple of Asclepius [S2]; the temple was of great celebrity [S2]; in the Peutinger Table the name appears as Ledena [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-047 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Leben was a harbour town of ancient Crete [SUPPORTED: https://en.wikipedia.org/wiki/Leben_(Crete)]; Leben served as the harbour of Gortyna [SUPPORTED: https://en.wikipedia.org/wiki/Leben_(Crete)]; Leben lay near modern Lentas [SUPPORTED: https://en.wikipedia.org/wiki/Leben_(Crete)]; Leben had a temple of Asclepius [SUPPORTED: https://en.wikipedia.org/wiki/Leben_(Crete)]; The temple of Asclepius was of great celebrity [SUPPORTED: https://en.wikipedia.org/wiki/Leben_(Crete)]; Leben appears by name on the Peutinger Table [SUPPORTED: https://en.wikipedia.org/wiki/Leben_(Crete)]; The name of Leben on the Peutinger Table is Ledena [SUPPORTED: https://en.wikipedia.org/wiki/Leben_(Crete)]"}]'::jsonb),
    ('8d4f7a98-2c79-4a0e-ae9b-c8f4a665902f'::uuid, 'card_description', 'A Roman ruin site that was repeatedly uncovered by storms in 1520, 1552, and 1562, then entirely eroded away by the sea. Nothing of the original fortress remains today.', 'Storm erosion uncovered more of the Roman ruin Brittenburg in 1520, 1552 and 1562, and it has since eroded away entirely. All that remains is a set of finds and a famous map by Ortelius.', 'teaser-card-s019:8d4f7a98-2c79-4a0e-ae9b-c8f4a665902f:card_description', 'teaser-card-s019 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '38fd511d70ea609befce416c45776a280880c99e57710148e423b096b9326b46|e22a4e233a674e845287a6cd2294a94124d9dfd7b2aec3d76e2a40fd978a5ea2|e22a4e233a674e845287a6cd2294a94124d9dfd7b2aec3d76e2a40fd978a5ea2', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Storm erosion uncovered more of the Roman ruin Brittenburg in 1520, 1552 and 1562, and it has since eroded away entirely. All that remains is a set of finds and a famous map by Ortelius."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Brittenburg was a Roman ruin [S1]; storm erosion uncovered more of it in 1520, 1552 and 1562 [S2]; it has since eroded away entirely [S2]; all that remains is a set of finds [S7]; all that remains includes a famous map by Ortelius [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-047 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Brittenburg is a Roman ruin (site west of Leiden between Katwijk aan Zee and Noordwijk aan Zee) [SUPPORTED: https://en.wikipedia.org/wiki/Brittenburg]; Storm erosion uncovered more of the ruin in 1520, 1552 and 1562 [SUPPORTED: https://en.wikipedia.org/wiki/Brittenburg]; The ruin has since eroded away entirely [SUPPORTED: https://en.wikipedia.org/wiki/Brittenburg]; All that remains is a set of finds [SUPPORTED: https://en.wikipedia.org/wiki/Brittenburg]; All that remains also includes a famous map by Ortelius [SUPPORTED: https://en.wikipedia.org/wiki/Brittenburg]"}]'::jsonb),
    ('8dedf95c-00b3-490e-94fa-3d558e4bc6be'::uuid, 'card_description', 'The fanum is thought to have been constructed in the 2nd century or perhaps at the end of the 1st.', 'In a public garden south of Périgueux rises the Tower of Vesunna, the round cella of a Gallo-Roman temple to Vesunna, goddess of the Petrocorii, approximately 24.46 meters high.', 'teaser-card-s019:8dedf95c-00b3-490e-94fa-3d558e4bc6be:card_description', 'teaser-card-s019 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '3af9e430751aec257956e45554c4008964e41f9ff296c4630a154a909d40da5c|6b3ef107caa086fb0759a482111f6fc04d4c94959d2aadf6af802b956578fee9|6b3ef107caa086fb0759a482111f6fc04d4c94959d2aadf6af802b956578fee9', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In a public garden south of Périgueux rises the Tower of Vesunna, the round cella of a Gallo-Roman temple to Vesunna, goddess of the Petrocorii, approximately 24.46 meters high."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Tower stands in a public garden [S3]; it is south of Périgueux [S2]; it is the round cella of a temple [S1, S7]; the temple is Gallo-Roman [S1]; the temple is dedicated to Vesunna [S1]; Vesunna is a goddess of the Petrocorii [S1]; it is approximately 24.46 meters high [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-047 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Tower of Vesunna is the round cella of a temple [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_Vesunna]; The temple was Gallo-Roman [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_Vesunna]; The temple was dedicated to Vesunna [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_Vesunna]; Vesunna was a goddess [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_Vesunna]; Vesunna was a goddess of the Petrocorii [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_Vesunna]; The tower stands in a public garden [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_Vesunna]; The tower lies south of Périgueux [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_Vesunna]; The tower is approximately 24.46 meters high [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_Vesunna]"}]'::jsonb),
    ('8ece5123-5b53-4545-929d-0519137c13ea'::uuid, 'card_description', '4th-century BC arch bridge discovered in 1966 near the eastern harbour of Rhodes. The oldest known voussoir arch bridge of the ancient world — a modest span that outlasted every empire that used it.', 'Near the Akandia Bay, the Rhodes Footbridge crosses an artificial canal on a surprisingly low arch of wedge-shaped poros stones: the oldest known Greek bridge with a voussoir arch.', 'teaser-card-s019:8ece5123-5b53-4545-929d-0519137c13ea:card_description', 'teaser-card-s019 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'f6a57804ef1132141b8d9c42d87d49365ee345a19cd059cda051cc2166864638|f0bb756ac785ed4ac768738896a48282c98ac391f7e692a7b0978e7dd3afa095|f0bb756ac785ed4ac768738896a48282c98ac391f7e692a7b0978e7dd3afa095', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near the Akandia Bay, the Rhodes Footbridge crosses an artificial canal on a surprisingly low arch of wedge-shaped poros stones: the oldest known Greek bridge with a voussoir arch."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Rhodes Footbridge is near the Akandia Bay [S3]; it crosses an artificial canal [S4, S6]; its arch has a surprisingly low rise [S8]; the arch is made of wedge-shaped stones [S6]; the stones are poros stone [S5]; it is the oldest known Greek bridge with a voussoir arch [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-048 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Rhodes Footbridge is an ancient footbridge (an arch bridge) in the city of Rhodes, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Rhodes_Footbridge]; The bridge is near Akandia Bay [SUPPORTED: https://en.wikipedia.org/wiki/Rhodes_Footbridge]; It crosses an artificial canal [SUPPORTED: https://en.wikipedia.org/wiki/Rhodes_Footbridge]; The canal is crossed by an arch of wedge-shaped stones that served as a footbridge [SUPPORTED: https://en.wikipedia.org/wiki/Rhodes_Footbridge]; The arch is surprisingly low [SUPPORTED: https://en.wikipedia.org/wiki/Rhodes_Footbridge]; The arch stones are poros stone [SUPPORTED: https://en.wikipedia.org/wiki/Rhodes_Footbridge]; It is the oldest known Greek bridge with a voussoir arch [SUPPORTED: https://en.wikipedia.org/wiki/Rhodes_Footbridge]"}]'::jsonb),
    ('8f256d92-11a1-4310-90e2-be5cebfc350e'::uuid, 'card_description', 'A 411-metre-long effigy mound shaped like an uncoiling serpent — the largest serpent effigy in the world. It was built on the rim of an ancient meteorite crater in Adams County, Ohio.', 'The Great Serpent Mound stretches 1,348 feet on a bluff above Ohio Brush Creek, the largest serpent effigy known in the world, raised on the site of a meteorite impact.', 'teaser-card-s019:8f256d92-11a1-4310-90e2-be5cebfc350e:card_description', 'teaser-card-s019 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '3f6c76622b69b71e69f5fad6427f2c4256cfab7cf1d131e23d7fd455714cd030|4741997a9c70b0bbbb3e1c61a6c59796177556525f5fb3c2fa75bde36c3154b1|4741997a9c70b0bbbb3e1c61a6c59796177556525f5fb3c2fa75bde36c3154b1', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Great Serpent Mound stretches 1,348 feet on a bluff above Ohio Brush Creek, the largest serpent effigy known in the world, raised on the site of a meteorite impact."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Great Serpent Mound is 1,348 feet long [S1]; it stands on a bluff above Ohio Brush Creek [S5]; it is the largest serpent effigy known in the world [S3]; it is located on the site of a meteorite impact [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-048 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Great Serpent Mound is a precontact effigy mound (a serpent-shaped earthwork) in Ohio, USA [SUPPORTED: https://en.wikipedia.org/wiki/Serpent_Mound]; It stretches 1,348 feet [SUPPORTED: https://en.wikipedia.org/wiki/Serpent_Mound]; It lies on a bluff above Ohio Brush Creek [SUPPORTED: https://en.wikipedia.org/wiki/Serpent_Mound]; It is the largest serpent effigy known in the world [SUPPORTED: https://en.wikipedia.org/wiki/Serpent_Mound]; It was raised on the site of a meteorite impact [SUPPORTED: https://en.wikipedia.org/wiki/Serpent_Mound]"}]'::jsonb),
    ('8f32afcc-457a-4143-8862-ebc774736fb3'::uuid, 'card_description', 'Mid-3rd-millennium BC Cycladic settlement on Ios, excavated 1984–1997. Stone buildings survive in exceptional condition, revealing dense multi-room architecture rare for the Aegean Bronze Age.', 'On a hill near the west coast of Ios, Skarkos keeps an early Cycladic settlement in an exceptionally good state of preservation, where digs unearthed marble figurines, obsidian and seals.', 'teaser-card-s019:8f32afcc-457a-4143-8862-ebc774736fb3:card_description', 'teaser-card-s019 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '84b61e742d779beba92f3b6dad3ee874d3746ecfdf1b4b5ad3abec5417a33c16|dfa24ae7133753cc57ba4379c1217b6192bd32edda8426c669311847f5e542aa|dfa24ae7133753cc57ba4379c1217b6192bd32edda8426c669311847f5e542aa', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a hill near the west coast of Ios, Skarkos keeps an early Cycladic settlement in an exceptionally good state of preservation, where digs unearthed marble figurines, obsidian and seals."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Skarkos is on a hill near the west coast of Ios [S3]; it holds an early Cycladic settlement [S6]; the settlement is in an exceptionally good state of preservation [S6]; excavations unearthed marble figurines [S8]; excavations unearthed obsidian (obsidian ware) [S8]; excavations unearthed seals [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-048 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Skarkos is a settlement on the island of Ios, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Skarkos]; It is on a hill near the west coast of Ios [SUPPORTED: https://en.wikipedia.org/wiki/Skarkos]; The settlement is early Cycladic [SUPPORTED: https://en.wikipedia.org/wiki/Skarkos]; The settlement is in an exceptionally good state of preservation [SUPPORTED: https://en.wikipedia.org/wiki/Skarkos]; Excavations unearthed marble figurines [SUPPORTED: https://en.wikipedia.org/wiki/Skarkos]; Excavations unearthed obsidian (obsidian ware) [SUPPORTED: https://en.wikipedia.org/wiki/Skarkos]; Excavations unearthed seals [SUPPORTED: https://en.wikipedia.org/wiki/Skarkos]"}]'::jsonb),
    ('8f53beb3-710b-4ace-9ebd-85757f1542e2'::uuid, 'card_description', 'The site contains a variety of architectural features including platforms, plazas, retaining walls or terraces, funerary areas, ramps, and paved roads.', 'Found in 1871 while a railroad was being built, Las Mercedes Archaeological Site has platforms, plazas, ramps and paved roads near Turrialba Volcano, probably once the center of a chiefdom.', 'teaser-card-s019:8f53beb3-710b-4ace-9ebd-85757f1542e2:card_description', 'teaser-card-s019 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '785b64ef886b5ae06a20fb83502e1498b6eb5c8e4ce1e13a8992a269f6065b01|f8340afaa059e21e4149c392cdc1ab8063dbfe22de15fd30d9ae0e4b0fbe4022|f8340afaa059e21e4149c392cdc1ab8063dbfe22de15fd30d9ae0e4b0fbe4022', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Found in 1871 while a railroad was being built, Las Mercedes Archaeological Site has platforms, plazas, ramps and paved roads near Turrialba Volcano, probably once the center of a chiefdom."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site was found in 1871 [S8]; it was found while a railroad was being built [S8]; it has platforms [S2]; it has plazas [S2]; it has ramps [S2]; it has paved roads [S2]; it is near Turrialba Volcano [S1]; it was probably once the center of a chiefdom [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-048 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Las Mercedes is an archaeological site in Costa Rica [SUPPORTED: https://en.wikipedia.org/wiki/Las_Mercedes_(archaeological_site,_Costa_Rica)]; The site lies near Turrialba Volcano [SUPPORTED: https://en.wikipedia.org/wiki/Las_Mercedes_(archaeological_site,_Costa_Rica)]; The site was found in 1871 [SUPPORTED: https://en.wikipedia.org/wiki/Las_Mercedes_(archaeological_site,_Costa_Rica)]; It was found while a railroad was being built [SUPPORTED: https://en.wikipedia.org/wiki/Las_Mercedes_(archaeological_site,_Costa_Rica)]; The site has platforms [SUPPORTED: https://en.wikipedia.org/wiki/Las_Mercedes_(archaeological_site,_Costa_Rica)]; The site has plazas [SUPPORTED: https://en.wikipedia.org/wiki/Las_Mercedes_(archaeological_site,_Costa_Rica)]; The site has ramps [SUPPORTED: https://en.wikipedia.org/wiki/Las_Mercedes_(archaeological_site,_Costa_Rica)]; The site has paved roads [SUPPORTED: https://en.wikipedia.org/wiki/Las_Mercedes_(archaeological_site,_Costa_Rica)]; The site was probably once the center of a chiefdom [SUPPORTED: https://en.wikipedia.org/wiki/Las_Mercedes_(archaeological_site,_Costa_Rica)]"}]'::jsonb),
    ('8fe59448-2356-47b1-810a-d31c76a580e3'::uuid, 'card_description', 'A Moche temple complex where the Lady of Cao was found — a tattooed female ruler buried with war clubs and gold, challenging assumptions about gender and power.', 'In the Chicama Valley, El Brujo''s biggest constructions belong to the Moche. A 17th-century letter found at the site may contain translations of numbers written in Quingnam.', 'teaser-card-s019:8fe59448-2356-47b1-810a-d31c76a580e3:card_description', 'teaser-card-s019 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', '7d4a9b3cb5b75f65eccd1d9d2f9e26ed220483ad2951b57ebe69fd5590318537|d39d44e52d7fc065c2eadda5959951811e5ec13ad09ae4ec16201a5a859c8571|d39d44e52d7fc065c2eadda5959951811e5ec13ad09ae4ec16201a5a859c8571', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the Chicama Valley, El Brujo''s biggest constructions belong to the Moche. A 17th-century letter found at the site may contain translations of numbers written in Quingnam."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "El Brujo lies in the Chicama Valley [S1]; the biggest constructions on the site belong to the Moche [S2]; a 17th-century letter was found at the site [S6]; the letter may contain translations of numbers written in Quingnam (hedged) [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-048 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "El Brujo is an archaeological site (complex) in the Chicama Valley, Peru [SUPPORTED: https://en.wikipedia.org/wiki/El_Brujo]; The biggest constructions on the site belong to the Moche culture [SUPPORTED: https://en.wikipedia.org/wiki/El_Brujo]; A 17th-century letter was found at the site [SUPPORTED: https://en.wikipedia.org/wiki/El_Brujo]; The letter may contain translations of numbers written in Quingnam [SUPPORTED: https://en.wikipedia.org/wiki/El_Brujo]"}]'::jsonb),
    ('90bd1f84-149e-4ee7-98c4-9c14b56298f1'::uuid, 'card_description', 'A broch on a rocky islet accessible only at very low tide, once connected by a causeway now lost. The entrance is blocked with rubble but the lintel still holds.', 'On a low rocky islet in West Burra Firth stands the ruined Broch of West Burrafirth. The Norse named the fjord after it, and within its walls four mural cells can still be seen.', 'teaser-card-s019:90bd1f84-149e-4ee7-98c4-9c14b56298f1:card_description', 'teaser-card-s019 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'be23816e7bb215bea6c18911fb1f9171658e0690cd3b25420946cc1468ec4551|a8394862721b381f9242d6ad9e07609f53f64d4c6c4faf21dbfa59b59dc279b5|a8394862721b381f9242d6ad9e07609f53f64d4c6c4faf21dbfa59b59dc279b5', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a low rocky islet in West Burra Firth stands the ruined Broch of West Burrafirth. The Norse named the fjord after it, and within its walls four mural cells can still be seen."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the broch stands on a low rocky islet [S2]; the islet is in West Burra Firth [S2]; the site is the Broch of West Burrafirth [S1]; the broch is ruined [S3]; the Norse named the fjord after the broch [S7]; four mural cells can be seen within its walls [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-049 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Broch of West Burrafirth is a broch (an Iron Age fortified dwelling) on the west side of Mainland, Shetland, Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_West_Burrafirth]; The broch stands on a low rocky islet [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_West_Burrafirth]; The islet lies in West Burra Firth [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Broch_of_West_Burrafirth]; The broch is ruined [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_West_Burrafirth]; The Norse named the fjord (Borgarfjord, later Burra Firth) after the broch [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_West_Burrafirth]; Mural cells can be seen within the broch''s walls (inside the broch) [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_West_Burrafirth]; The number of mural cells that can still be seen is four [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_West_Burrafirth]"}]'::jsonb),
    ('924cc0ad-a5ee-4200-84b1-8d41fc60d1ff'::uuid, 'card_description', 'Just 40 metres across, this hilltop enclosure in West Somerset was too small for a garrison — more likely a homestead for a single extended family. Its earthworks survive as a scheduled monument.', 'In Somerset lies Long Wood Enclosure, approximately 40 metres in diameter and ringed by a bank and ditches, a place that may once have been an Iron Age hill fort.', 'teaser-card-s019:924cc0ad-a5ee-4200-84b1-8d41fc60d1ff:card_description', 'teaser-card-s019 (teaser-card): teaser card, 162 characters, checked PASS, web-verified VERIFIED', 'c82cc249675d1c8511624c544f105370a9567626bcb4d7c04909b1490e6fb48d|b5c6decb740877acfb087efeddfe1057c2a6f7110d1f14728c6fcfe0b2a063b9|b5c6decb740877acfb087efeddfe1057c2a6f7110d1f14728c6fcfe0b2a063b9', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In Somerset lies Long Wood Enclosure, approximately 40 metres in diameter and ringed by a bank and ditches, a place that may once have been an Iron Age hill fort."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the enclosure lies in Somerset [S1]; the enclosure is approximately 40 metres in diameter [S2]; it is ringed by a bank and ditches [S3]; it may once have been an Iron Age hill fort [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-049 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Long Wood Enclosure is an enclosure in Somerset, England, that may have been an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Long_Wood_Enclosure]; The enclosure is approximately 40 metres in diameter [SUPPORTED: https://en.wikipedia.org/wiki/Long_Wood_Enclosure]; The enclosure is ringed by a bank and ditches [SUPPORTED: https://en.wikipedia.org/wiki/Long_Wood_Enclosure]; It is uncertain whether it was once an Iron Age hill fort (the identification is only possible: ''may once have been'') [SUPPORTED: https://en.wikipedia.org/wiki/Long_Wood_Enclosure]"}]'::jsonb),
    ('92a50129-08f7-47c2-903e-6d50c29c2bef'::uuid, 'card_description', 'Built in the early 1st century AD during Augustus''s reign, this gravity dam on the Huerva River created a reservoir to supply the colony of Caesaraugusta — the city now known as Zaragoza.', 'Built in the time of Augustus, the Roman Muel Dam held back the Huerva River until silt filled its lake to the top of the wall, preserving the lower portion of the structure.', 'teaser-card-s019:92a50129-08f7-47c2-903e-6d50c29c2bef:card_description', 'teaser-card-s019 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '8fdfc68ceae76337c04e0b392b08c246bd1ae2f6565abb8c62d68edbedd9b15e|addd0d28913232e6e2295e50d4761ccbdfc31fc3df376f31ae57a41feb7dbdf4|addd0d28913232e6e2295e50d4761ccbdfc31fc3df376f31ae57a41feb7dbdf4', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Built in the time of Augustus, the Roman Muel Dam held back the Huerva River until silt filled its lake to the top of the wall, preserving the lower portion of the structure."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the dam was built in the time of Augustus [S2]; the dam is Roman [S1]; the dam held back the Huerva River [S1, S2, S5]; silt filled its lake to the top of the wall [S5]; the siltation preserved the lower portion of the structure [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-049 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Muel Dam is a Roman dam (a gravity dam) at Muel in Zaragoza province, Aragon, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Muel_Dam]; It was built in the time of Augustus [SUPPORTED: https://en.wikipedia.org/wiki/Muel_Dam]; The dam held back the Huerva River (impounding a lake) [SUPPORTED: https://en.wikipedia.org/wiki/Muel_Dam]; Silt filled the lake to the top of the wall [SUPPORTED: https://en.wikipedia.org/wiki/Muel_Dam]; The silting preserved the lower portion of the structure [SUPPORTED: https://en.wikipedia.org/wiki/Muel_Dam]"}]'::jsonb),
    ('92cad00e-4027-4e01-bb7d-2da01760d197'::uuid, 'card_description', 'A 3700 BC chambered long barrow and one of the longest Neolithic burial mounds in Britain at 100 meters. It held the remains of at least 46 individuals over 1,000 years.', 'Near Avebury, West Kennet Long Barrow runs 100 metres. The bones of men, women and children were placed in its chamber, and in the Late Neolithic sarsen boulders blocked its entrance.', 'teaser-card-s019:92cad00e-4027-4e01-bb7d-2da01760d197:card_description', 'teaser-card-s019 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'b6c47dda7911db55aa49042d9d4d5a5a37ae710d26c5635c7bffa83d4027bc03|6fc3af1eb0fba9c74b2e8cced1ec8ce56cc34a06eeadc8262a5f57434b3dccd7|6fc3af1eb0fba9c74b2e8cced1ec8ce56cc34a06eeadc8262a5f57434b3dccd7', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near Avebury, West Kennet Long Barrow runs 100 metres. The bones of men, women and children were placed in its chamber, and in the Late Neolithic sarsen boulders blocked its entrance."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the long barrow is near Avebury [S1]; the long barrow is 100 metres long [S6]; human bones were placed in its chamber [S3]; the bones were of men, women and children [S3]; in the Late Neolithic its entrance was blocked [S4]; the entrance was blocked with sarsen boulders [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-049 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "West Kennet Long Barrow is a chambered long barrow (a tomb) [SUPPORTED: https://en.wikipedia.org/wiki/West_Kennet_Long_Barrow]; It is near Avebury (Wiltshire, England) [SUPPORTED: https://en.wikipedia.org/wiki/West_Kennet_Long_Barrow]; The barrow is 100 metres long [SUPPORTED: https://en.wikipedia.org/wiki/West_Kennet_Long_Barrow]; Human bones were placed in its chamber [SUPPORTED: https://en.wikipedia.org/wiki/West_Kennet_Long_Barrow]; The bones were those of men, women and children [SUPPORTED: https://en.wikipedia.org/wiki/West_Kennet_Long_Barrow]; The entrance was blocked in the Late Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/West_Kennet_Long_Barrow]; The entrance was blocked with sarsen boulders [SUPPORTED: https://en.wikipedia.org/wiki/West_Kennet_Long_Barrow]"}]'::jsonb),
    ('92d26614-c2fb-4b94-9342-99a5bd2407ab'::uuid, 'card_description', 'Excavations for an episode of Channel 4''s Time Team showed the hillfort''s occupation began about 600 BC.', 'Caerau Hillfort crowns a ridge-top plateau in Cardiff, an Iron Age fort occupied from about 600 BC, yet built on a Neolithic site where flint tools and weapons dating to 3600 BC were found.', 'teaser-card-s019:92d26614-c2fb-4b94-9342-99a5bd2407ab:card_description', 'teaser-card-s019 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'e5fce017dcd185a767ce2c14dc7b80f3a448e9306cca65f652074742326a6798|a31008fab21c0bc1da9930cd30266e9f7c6ead30e28a6619b27aa783c75990f2|a31008fab21c0bc1da9930cd30266e9f7c6ead30e28a6619b27aa783c75990f2', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Caerau Hillfort crowns a ridge-top plateau in Cardiff, an Iron Age fort occupied from about 600 BC, yet built on a Neolithic site where flint tools and weapons dating to 3600 BC were found."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the hillfort lies on a ridge-top plateau [S1]; the hillfort is in Cardiff [S1]; it is an Iron Age fort [S1]; it was occupied from about 600 BC [S2]; it was built on a Neolithic site [S1]; flint tools and weapons dating to 3600 BC were found there [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-049 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Caerau Hillfort is a hillfort in Cardiff, Wales [SUPPORTED: https://en.wikipedia.org/wiki/Caerau_Hillfort]; The hillfort occupies a ridge-top plateau [SUPPORTED: https://en.wikipedia.org/wiki/Caerau_Hillfort]; Caerau is an Iron Age fort [SUPPORTED: https://en.wikipedia.org/wiki/Caerau_Hillfort]; The fort was occupied from about 600 BC [SUPPORTED: https://en.wikipedia.org/wiki/Caerau_Hillfort]; The hillfort was built on a Neolithic site [SUPPORTED: https://en.wikipedia.org/wiki/Caerau_Hillfort]; Flint tools and weapons were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Caerau_Hillfort]; The flint tools and weapons date to 3600 BC [SUPPORTED: https://en.wikipedia.org/wiki/Caerau_Hillfort]"}]'::jsonb),
    ('936b5a30-e1dd-4524-95c2-e7214ecf3090'::uuid, 'card_description', 'The archaeological site of Grand contains a wide amphitheater and a mosaic of 232 m2. The amphitheater was built at the end of the 1st century and can contain 17,000 people.', 'Once the Gallo-Roman city of Andésina, the Archaeological Site of Grand holds an amphitheater for 17,000 people and a mosaic showing a theater scene of the Phasma of Menander.', 'teaser-card-s019:936b5a30-e1dd-4524-95c2-e7214ecf3090:card_description', 'teaser-card-s019 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', 'e27aaa4dc56329326a5d8478dcc67ad177ec5dd5b46cd8f8d0224bd787491916|eacdf099896ca769375e827f550455e5b1fd84389fb5dda91f010f4ddfe8c57d|eacdf099896ca769375e827f550455e5b1fd84389fb5dda91f010f4ddfe8c57d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Once the Gallo-Roman city of Andésina, the Archaeological Site of Grand holds an amphitheater for 17,000 people and a mosaic showing a theater scene of the Phasma of Menander."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site was once the Gallo-Roman city of Andésina [S3]; the site holds an amphitheater [S1]; the amphitheater holds 17,000 people [S4]; the site holds a mosaic [S1]; the mosaic shows a theater scene of the Phasma of Menander [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Archaeological Site of Grand is the site of the ancient Gallo-Roman city of Andésina (central claim: a Gallo-Roman city site) [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_site_of_Grand]; The site is in France (Vosges department, Grand Est) [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_site_of_Grand]; The site holds an amphitheater [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_site_of_Grand]; The amphitheater holds 17,000 people [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_site_of_Grand]; The site holds a mosaic [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_site_of_Grand]; The mosaic shows a theater scene of the Phasma of Menander [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_site_of_Grand]"}]'::jsonb),
    ('93a36090-1dd8-43e4-8da1-79782cb01b96'::uuid, 'card_description', 'A five-stone axial circle from the Bronze Age, with tall portal stones aligned north-south. Set on bogland overlooking a deep mountain valley.', 'In County Cork, the Bronze Age Kealkill Stone Circle stands near two tall menhirs and a ring cairn. It held no sign of burial, and nothing was found that could date it.', 'teaser-card-s019:93a36090-1dd8-43e4-8da1-79782cb01b96:card_description', 'teaser-card-s019 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '67732b29cc606fda78fdd86f87cf38fcfdd42618946d3f9587e8d25fa1ce941a|e03a3fbe1759c7735139d2d6ec06689b129ded42c7898e2220ce8a6587ba685a|e03a3fbe1759c7735139d2d6ec06689b129ded42c7898e2220ce8a6587ba685a', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In County Cork, the Bronze Age Kealkill Stone Circle stands near two tall menhirs and a ring cairn. It held no sign of burial, and nothing was found that could date it."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the stone circle is in County Cork [S1]; it is a Bronze Age stone circle [S1]; two tall menhirs stand near it [S3, S4]; a ring cairn stands near it [S3]; no sign of burial was found in it [S6]; nothing was found that could date it [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Kealkill Stone Circle is a stone circle in County Cork, Ireland (central claim: a stone circle) [SUPPORTED: https://en.wikipedia.org/wiki/Kealkill_stone_circle]; The circle dates to the Bronze Age (as a typological attribution) [SUPPORTED: https://en.wikipedia.org/wiki/Kealkill_stone_circle]; Two tall menhirs stand near the circle [SUPPORTED: https://en.wikipedia.org/wiki/Kealkill_stone_circle]; A ring cairn stands near the circle [SUPPORTED: https://en.wikipedia.org/wiki/Kealkill_stone_circle]; The circle held no sign of burial [SUPPORTED: https://en.wikipedia.org/wiki/Kealkill_stone_circle]; Nothing was found that could date it [SUPPORTED: https://en.wikipedia.org/wiki/Kealkill_stone_circle]"}]'::jsonb),
    ('945482c9-9445-4622-add2-2a6334ccbd5b'::uuid, 'card_description', 'The Eifel aqueduct was destroyed by Germanic tribes in 260 during an attack on Cologne, and was never brought back into operation, even though the city continued to exist.', 'From a spring near Nettersheim, the Eifel Aqueduct carried water some 95 kilometres to the city that is now Cologne, almost entirely below ground and moved by gravity alone.', 'teaser-card-s019:945482c9-9445-4622-add2-2a6334ccbd5b:card_description', 'teaser-card-s019 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', 'e2f613779bf60352f1fab208c5b14326185831dad99e7018548eaccf0111e7b3|4b2e32192de2921bbf2ffb2bb26c340bfd54f0c1712e3c2856d887f606f06a42|4b2e32192de2921bbf2ffb2bb26c340bfd54f0c1712e3c2856d887f606f06a42', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "From a spring near Nettersheim, the Eifel Aqueduct carried water some 95 kilometres to the city that is now Cologne, almost entirely below ground and moved by gravity alone."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the aqueduct began at a spring near Nettersheim [S4]; it carried water some 95 kilometres [S2]; the water went to the city that is now Cologne [S2]; the construction was almost entirely below ground [S3]; the water flowed by gravity alone [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Eifel Aqueduct is a Roman aqueduct in Germany that carried water to a city (central claim: an aqueduct) [SUPPORTED: https://en.wikipedia.org/wiki/Eifel_Aqueduct]; The aqueduct began at a spring near Nettersheim [SUPPORTED: https://en.wikipedia.org/wiki/Eifel_Aqueduct]; It carried water some 95 kilometres [SUPPORTED: https://en.wikipedia.org/wiki/Eifel_Aqueduct]; The water went to the city that is now Cologne (ancient Colonia Claudia Ara Agrippinensium) [SUPPORTED: https://en.wikipedia.org/wiki/Eifel_Aqueduct]; The construction was almost entirely below ground [SUPPORTED: https://en.wikipedia.org/wiki/Eifel_Aqueduct]; The water was moved by gravity alone [SUPPORTED: https://en.wikipedia.org/wiki/Eifel_Aqueduct]"}]'::jsonb),
    ('95034077-b765-40f7-aefc-7e4f660613f3'::uuid, 'card_description', '2nd–3rd century AD temple of Mithras at Vindobala on Hadrian''s Wall. Located 137 metres west of the garrison — where soldiers worshipped in secret, beyond the edge of the empire''s known world.', 'In 1844 a farmer by Hadrian''s Wall found a statue and altars in his field: the Rudchester Mithraeum, a temple to Mithras. The statue was broken up, but the altars were all saved.', 'teaser-card-s019:95034077-b765-40f7-aefc-7e4f660613f3:card_description', 'teaser-card-s019 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '638f6356212c73db7b2292f5bc29366535617688635c3c7a4a7cfcac085353cc|364aceb871980900984f0844c4b5fb54d746c55c081dce82eb65be8d926925fc|364aceb871980900984f0844c4b5fb54d746c55c081dce82eb65be8d926925fc', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In 1844 a farmer by Hadrian''s Wall found a statue and altars in his field: the Rudchester Mithraeum, a temple to Mithras. The statue was broken up, but the altars were all saved."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "in 1844 the site was discovered [S3]; the finder was a farmer [S3]; the site lies by Hadrian''s Wall [S1]; the farmer found a statue and altars [S3]; the finds lay in his field [S3]; the site is the Rudchester Mithraeum, a temple to Mithras [S1, S3]; the statue was broken up [S4]; the altars were all saved [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Rudchester Mithraeum is a temple to Mithras (central claim: a Mithraic temple) [SUPPORTED: https://en.wikipedia.org/wiki/Rudchester_Mithraeum]; The site is at Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Rudchester_Mithraeum]; The site is in England (Rudchester, Northumberland) [SUPPORTED: https://en.wikipedia.org/wiki/Vindobala]; The site was discovered in 1844 [SUPPORTED: https://en.wikipedia.org/wiki/Rudchester_Mithraeum]; It was found by a farmer, in his field [SUPPORTED: https://en.wikipedia.org/wiki/Rudchester_Mithraeum]; A statue was found [SUPPORTED: https://en.wikipedia.org/wiki/Rudchester_Mithraeum]; Altars were found [SUPPORTED: https://en.wikipedia.org/wiki/Rudchester_Mithraeum]; The statue was broken up [SUPPORTED: https://en.wikipedia.org/wiki/Rudchester_Mithraeum]; The altars were all saved [SUPPORTED: https://en.wikipedia.org/wiki/Rudchester_Mithraeum]"}]'::jsonb),
    ('966f26e0-c2ae-4a0f-ac46-8a481ad80b19'::uuid, 'card_description', 'A Lycian city with three harbors and a 24-metre-wide main street running through the center. Hadrian''s Waterway Gate stands at the southern end, flanked by ruined shops.', 'The pirate Zekenites once held Phaselis, a Greek and Roman city on the coast of Lycia, until his defeat in 77 or 76 BC. A 24-metre-wide ancient street still runs through its middle.', 'teaser-card-s019:966f26e0-c2ae-4a0f-ac46-8a481ad80b19:card_description', 'teaser-card-s019 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '599661efc1dffbe365e9085f08badb24dae2ee3ff9bb03e1e2c414f2cbb93f3a|14a308300f447aea1e296beb2236bb6e0ac2af838e7d6188e9b26058e49b7ef2|14a308300f447aea1e296beb2236bb6e0ac2af838e7d6188e9b26058e49b7ef2', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The pirate Zekenites once held Phaselis, a Greek and Roman city on the coast of Lycia, until his defeat in 77 or 76 BC. A 24-metre-wide ancient street still runs through its middle."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the pirate Zekenites once held Phaselis [S2]; Phaselis is a Greek and Roman city [S1]; Phaselis lies on the coast of Lycia [S1]; Zekenites''s hold lasted until his defeat in 77 or 76 BC [S2]; a 24-metre-wide ancient street runs through the middle of the city [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Phaselis is a Greek and Roman city on the coast of Lycia (central claim: a city) [SUPPORTED: https://en.wikipedia.org/wiki/Phaselis]; Phaselis is in Türkiye (Kemer district, Antalya Province) [SUPPORTED: https://en.wikipedia.org/wiki/Phaselis]; A pirate named Zekenites held (took over) Phaselis [SUPPORTED: https://en.wikipedia.org/wiki/Phaselis]; Zekenites held the city until his defeat [SUPPORTED: https://en.wikipedia.org/wiki/Phaselis]; The defeat was in 77 or 76 BC [SUPPORTED: https://en.wikipedia.org/wiki/Phaselis]; An ancient street 24 metres wide exists at Phaselis [SUPPORTED: https://en.wikipedia.org/wiki/Phaselis]; The street runs through the middle of the city and is still there today [SUPPORTED: https://en.wikipedia.org/wiki/Phaselis]"}]'::jsonb),
    ('970e9f98-8206-46d0-a591-b20b2df667ba'::uuid, 'card_description', 'A portal tomb with a capstone weighing an estimated 150 tonnes -- the heaviest in Europe. How Neolithic builders raised this colossal stone remains a mystery.', 'The granite capstone of Brownshill Dolmen weighs an estimated 150 metric tons, reputed to be the heaviest in Europe. Built between 4000 and 3000 BC, the tomb has never been excavated.', 'teaser-card-s019:970e9f98-8206-46d0-a591-b20b2df667ba:card_description', 'teaser-card-s019 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '98389df163e66738878386360aeba583d8b5b01584a46604f792dea39eec6519|b3bce412ab8a5d2925d02fa5abe3e5cb27723d32a565cba3131a1fbb77f06b59|b3bce412ab8a5d2925d02fa5abe3e5cb27723d32a565cba3131a1fbb77f06b59', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The granite capstone of Brownshill Dolmen weighs an estimated 150 metric tons, reputed to be the heaviest in Europe. Built between 4000 and 3000 BC, the tomb has never been excavated."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the capstone is of granite [S4]; the capstone weighs an estimated 150 metric tons [S2]; it is reputed to be the heaviest in Europe [S2]; the tomb was built between 4000 and 3000 BC [S3]; the tomb has not been excavated [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Brownshill Dolmen is a tomb (a megalithic portal tomb) in Ireland (County Carlow) [SUPPORTED: https://en.wikipedia.org/wiki/Brownshill_Dolmen]; The capstone of the dolmen is granite [SUPPORTED: https://en.wikipedia.org/wiki/Brownshill_Dolmen]; The capstone weighs an estimated 150 metric tons [SUPPORTED: https://en.wikipedia.org/wiki/Brownshill_Dolmen]; The capstone is reputed to be the heaviest in Europe [SUPPORTED: https://en.wikipedia.org/wiki/Brownshill_Dolmen]; The tomb was built between 4000 and 3000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Brownshill_Dolmen]; The tomb has never been excavated [SUPPORTED: https://heritageireland.ie/unguided-sites/brownshill-portal-dolmen/]"}]'::jsonb),
    ('972a2d53-376a-4f73-98bb-7a408040de58'::uuid, 'card_description', 'A 15th-century botanical garden by the ruler Nezahualcoyotl—one of the first in the Americas. It collected plant and animal specimens for encyclopedic study.', 'In the 15th century Nezahualcoyotl, ruler of Texcoco, created Texcotzingo, summer imperial gardens whose waterworks and terraces made un-arable land lush with maize, beans and squash.', 'teaser-card-s019:972a2d53-376a-4f73-98bb-7a408040de58:card_description', 'teaser-card-s019 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'dc7f21cb34f4ef60283efe1b77048630247a441c87189170d5f2aa0163371bac|e045f1f30b41e4ecc4c01d2fe08eb390a48b1d426a3a7ee18eef34b7dc732b7d|e045f1f30b41e4ecc4c01d2fe08eb390a48b1d426a3a7ee18eef34b7dc732b7d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the 15th century Nezahualcoyotl, ruler of Texcoco, created Texcotzingo, summer imperial gardens whose waterworks and terraces made un-arable land lush with maize, beans and squash."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "in the 15th century Texcotzingo was created [S4]; Nezahualcoyotl created it [S4]; Nezahualcoyotl was the ruler of Texcoco [S4]; Texcotzingo was summer imperial gardens [S3]; waterworks (hydraulic projects) and terraces were built there [S3, S5]; they turned un-arable land into lush gardens [S5]; the gardens held maize, beans and squash [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Texcotzingo is a site of gardens (botanical/imperial gardens and archaeological site) in Mexico [SUPPORTED: https://en.wikipedia.org/wiki/Texcotzingo]; The gardens served as summer imperial gardens [SUPPORTED: https://en.wikipedia.org/wiki/Texcotzingo]; Texcotzingo was created by Nezahualcoyotl [SUPPORTED: https://en.wikipedia.org/wiki/Texcotzingo]; Nezahualcoyotl was the ruler of Texcoco [SUPPORTED: https://en.wikipedia.org/wiki/Texcotzingo]; The gardens were created in the 15th century [SUPPORTED: https://en.wikipedia.org/wiki/Texcotzingo]; The site had waterworks and terraces (hydraulic projects and terrace gardens) [SUPPORTED: https://en.wikipedia.org/wiki/Texcotzingo]; The waterworks and terraces made previously un-arable land lush [SUPPORTED: https://en.wikipedia.org/wiki/Texcotzingo]; The lush gardens grew maize, beans and squash [SUPPORTED: https://en.wikipedia.org/wiki/Texcotzingo]"}]'::jsonb),
    ('9785a238-2527-4fdc-891a-93ebfcdfd9ce'::uuid, 'card_description', 'An open-air sanctuary to Zeus the City Protector, built around 500 BC on the Acropolis. No foundations survive — its plan was worked out from cuttings in bedrock.', 'On the Acropolis of Athens, no foundations of the Sanctuary of Zeus Polieus have been found, yet rock-cuttings hint at its layout. Its east is believed to have held oxen for the Bouphonia.', 'teaser-card-s019:9785a238-2527-4fdc-891a-93ebfcdfd9ce:card_description', 'teaser-card-s019 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '22b61f7102534fb8cc0372af118b62b023db3f19b1f61ae38113fcc189dfc0ee|c8b46f6fe80af53c14bbc61a835ea20014a156dd713bca45b50cbdc652b2213c|c8b46f6fe80af53c14bbc61a835ea20014a156dd713bca45b50cbdc652b2213c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the Acropolis of Athens, no foundations of the Sanctuary of Zeus Polieus have been found, yet rock-cuttings hint at its layout. Its east is believed to have held oxen for the Bouphonia."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the sanctuary is on the Acropolis of Athens [S1]; no foundations of the sanctuary have been found [S2]; rock-cuttings hint at its layout [S2]; its eastern part is believed to have held oxen [S3]; the oxen were for the Bouphonia [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Sanctuary of Zeus Polieus was a sanctuary (walled open-air, dedicated to Zeus Polieus) on the Acropolis of Athens [SUPPORTED: https://en.wikipedia.org/wiki/Sanctuary_of_Zeus_Polieus]; No foundations of the sanctuary have been found [SUPPORTED: https://en.wikipedia.org/wiki/Sanctuary_of_Zeus_Polieus]; Rock-cuttings on the Acropolis hint at (allow inference of) the sanctuary''s layout [SUPPORTED: https://en.wikipedia.org/wiki/Sanctuary_of_Zeus_Polieus]; The boundaries of the sanctuary are reconstructed from rock cuttings in the Acropolis bedrock [SUPPORTED: https://perseus-aa.github.io/items/aa_70.html]; The eastern section of the sanctuary is believed to have held (accommodated) oxen [SUPPORTED: https://en.wikipedia.org/wiki/Sanctuary_of_Zeus_Polieus]; The oxen were for the Bouphonia, an annual ceremony [SUPPORTED: https://en.wikipedia.org/wiki/Sanctuary_of_Zeus_Polieus]; The Bouphonia rites were held within the Zeus Polieus precinct, an annual sacrifice of oxen to Zeus Polieus [SUPPORTED: https://perseus-aa.github.io/items/aa_70.html]"}]'::jsonb),
    ('97ecf20f-9ce3-44d1-98ba-931c8335c386'::uuid, 'card_description', 'Roman villa occupied 1st–5th century AD in Loures. Excavations in 1995 found burial tombs, salting tanks, incendiary remnants, wall fragments, and a capital — a layered estate ending in fire.', 'In 1995, excavators at the Roman Villa of Almoinhas in Loures found burial tombs, salting tanks, walls and Roman coins, relics of a villa dating to the first to fifth century AD.', 'teaser-card-s019:97ecf20f-9ce3-44d1-98ba-931c8335c386:card_description', 'teaser-card-s019 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '271912c1e8d03dad9e403c895982c7be26a2e3d70c404804e5386980a7ccdc2c|679acdbb8d9c0e9cf9fc2be91bb14dbe6e13c32673a2e6a40bec21d8dde9ac62|679acdbb8d9c0e9cf9fc2be91bb14dbe6e13c32673a2e6a40bec21d8dde9ac62', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In 1995, excavators at the Roman Villa of Almoinhas in Loures found burial tombs, salting tanks, walls and Roman coins, relics of a villa dating to the first to fifth century AD."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "excavations took place in 1995 [S4]; the villa is in Loures [S1]; the excavators found burial tombs [S4]; the excavators found salting tanks [S4]; the excavators found walls [S4]; the finds included Roman coins [S5]; the villa dates to the first to fifth century AD [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Roman Villa of Almoinhas is a Roman villa in Loures, Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Almoinhas]; The villa dates to the first to fifth century AD [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Almoinhas]; Excavations at the site took place in 1995 [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Almoinhas]; The 1995 excavators found burial tombs [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Almoinhas]; The 1995 excavators found walls and salting tanks [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Almoinhas]; The finds included Roman coins [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Almoinhas]; The first finds date to 1995, when municipal excavations uncovered graves, walls, a salting tank and coins [SUPPORTED: https://www.rtp.pt/noticias/pais/descoberta-villa-romana-em-almoinhas_n34841]"}]'::jsonb),
    ('9803a37d-458e-445c-9fec-8d94a0f89f1c'::uuid, 'card_description', 'Founded 709 BC. Sarcophagi, grave goods, and ancient artefacts have been recovered from this necropolis -- remnants of one of the oldest cities on the Propontis shore.', 'Founded in 709 B.C. on the Hellespont, the Greek city of Parion once held a monumental altar whose sides, the ancient writer Strabo said, were the length of a stadion.', 'teaser-card-s019:9803a37d-458e-445c-9fec-8d94a0f89f1c:card_description', 'teaser-card-s019 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', 'edec7ad7a36032eab919b9d74c0871d552ae1839e5392e704f362d4312ea87ef|64327720c69e3a2ffab78c6c47f1f0913e0de0a911fc23e278e60c91ce59c64e|64327720c69e3a2ffab78c6c47f1f0913e0de0a911fc23e278e60c91ce59c64e', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Founded in 709 B.C. on the Hellespont, the Greek city of Parion once held a monumental altar whose sides, the ancient writer Strabo said, were the length of a stadion."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Parion was founded in 709 BC [S2]; Parion lies on the Hellespont [S1]; Parion is a Greek city [S1]; it once held a monumental altar [S3]; the altar''s sides were the length of a stadion [S3]; the ancient writer Strabo said so [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Parion is an ancient Greek city (in Mysia) [SUPPORTED: https://en.wikipedia.org/wiki/Parium]; Parion lies on the Hellespont (note: Strabo 10.5.7 calls Parium a city on the Propontis; Wikipedia and the Roman province Hellespontus use the broader name) [SUPPORTED: https://en.wikipedia.org/wiki/Parium]; Parion was founded in 709 B.C. (the excavation team words it more cautiously: the foundation ''might be dated to 709 BC'') [SUPPORTED: https://en.wikipedia.org/wiki/Parium]; Parion once held a monumental altar (known from ancient sources; Wikipedia adds that there is no archaeological evidence of it) [SUPPORTED: https://en.wikipedia.org/wiki/Parium]; The altar was remarkable in size (monumental) [SUPPORTED: https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0198:book=13:chapter=1]; Strabo said the altar''s sides were the length of a stadion [SUPPORTED: https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0198:book=10:chapter=5:section=7]"}]'::jsonb),
    ('98915fdd-4e67-42aa-8631-53a063cd5109'::uuid, 'card_description', 'Ceredigion fort whose name means "Christmas Castle." The Penbryn Spoons -- rare late Iron Age artefacts -- were found here. Two concentric banks enclose a space 230 metres across.', 'In 1829 a tenant farmer found two objects of cast bronze beneath a heap of stones inside Castell Nadolig, an Iron Age hillfort on a low summit whose ramparts now form parts of hedgebanks.', 'teaser-card-s019:98915fdd-4e67-42aa-8631-53a063cd5109:card_description', 'teaser-card-s019 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'f2be616337f1b3e3d7d8d5348af61a733ad54fd78213c6e54801815e825df8ff|21f11b5a5f4535cde80e5d2f8b9505f7ca8ad1a8532a687276cf2ddaf016deb5|21f11b5a5f4535cde80e5d2f8b9505f7ca8ad1a8532a687276cf2ddaf016deb5', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In 1829 a tenant farmer found two objects of cast bronze beneath a heap of stones inside Castell Nadolig, an Iron Age hillfort on a low summit whose ramparts now form parts of hedgebanks."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "in 1829 [S7]; a tenant farmer found the objects [S7]; two objects were found [S7]; the objects were of cast bronze [S7]; they lay beneath a heap of stones [S7]; the find was made inside the hillfort Castell Nadolig [S7, S1]; Castell Nadolig is an Iron Age hillfort [S1]; the hillfort is sited on a low summit [S3]; its ramparts now form parts of hedgebanks [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Castell Nadolig is an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Nadolig]; Castell Nadolig lies in Ceredigion, Wales [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Nadolig]; The find was made in 1829 [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Nadolig]; Two objects were found [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Nadolig]; The two objects were of cast bronze [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Nadolig]; The finder was a tenant farmer [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Nadolig]; The objects lay beneath a heap of stones [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Nadolig]; The objects were found inside the hillfort itself [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Nadolig]; The hillfort stands on a low summit [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Nadolig]; The surviving ramparts now form parts of hedgebanks [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Nadolig]"}]'::jsonb),
    ('990741ec-f247-483a-8b8e-29f634e63f96'::uuid, 'card_description', 'A legionary fortress built in the 70s AD, rebuilt in stone, then rebuilt again in the 3rd century. Three phases trace the evolution of Roman military architecture.', 'Where Chester stands, a Roman legion built Deva Victrix in the 70s AD: barracks, baths and an unusual elliptical building, never finished, perhaps meant as the governor''s headquarters.', 'teaser-card-s019:990741ec-f247-483a-8b8e-29f634e63f96:card_description', 'teaser-card-s019 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '991de969ce0dc7c2a65873f5f52d29e2f04cd8707001e889621ae45283bb2a8f|c49d7b3472211a15a4409c8a5a33c9cdce2ec8b9ebb0e00f2cdf867ae22fc46c|c49d7b3472211a15a4409c8a5a33c9cdce2ec8b9ebb0e00f2cdf867ae22fc46c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Where Chester stands, a Roman legion built Deva Victrix in the 70s AD: barracks, baths and an unusual elliptical building, never finished, perhaps meant as the governor''s headquarters."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Deva Victrix stands where the modern city of Chester stands [S1, S6]; a Roman legion built the fortress of Deva Victrix [S1, S2]; it was built in the 70s AD [S2]; the fortress contained barracks [S7]; the fortress contained baths [S7]; the fortress contained an unusual elliptical building [S7]; the elliptical building was never finished [S7]; the elliptical building was perhaps meant as the governor''s headquarters (hedged) [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Deva Victrix was a Roman legionary fortress (and town) [SUPPORTED: https://en.wikipedia.org/wiki/Deva_Victrix]; The site lies where the modern city of Chester stands [SUPPORTED: https://en.wikipedia.org/wiki/Deva_Victrix]; It was built by a Roman legion (Legio II Adiutrix) [SUPPORTED: https://en.wikipedia.org/wiki/Deva_Victrix]; It was built in the 70s AD [SUPPORTED: https://en.wikipedia.org/wiki/Deva_Victrix]; The fortress contained barracks [SUPPORTED: https://en.wikipedia.org/wiki/Deva_Victrix]; The fortress contained baths [SUPPORTED: https://en.wikipedia.org/wiki/Deva_Victrix]; The fortress contained an unusual elliptical building [SUPPORTED: https://en.wikipedia.org/wiki/Deva_Victrix]; The elliptical building was never finished [UNVERIFIABLE, no proving quote: None]; The elliptical building was perhaps meant as the governor''s headquarters [SUPPORTED: https://archaeology.co.uk/articles/opinion/excavating-the-ca-archives-roman-chester.htm]"}]'::jsonb),
    ('995d7504-5526-4e4e-96d5-a03ba4470425'::uuid, 'card_description', 'Ancient city on three levels: hilltop acropolis with a temple, a covered 6th-century BC reservoir, and a stoa built directly over it -- water engineering and worship layered on one ridge.', 'Founded by the Dorians on the northwest coast of Rhodes, Camirus rises in three levels to the temple complex of Athena Kameiras. Its covered reservoir held water for up to 400 families.', 'teaser-card-s019:995d7504-5526-4e4e-96d5-a03ba4470425:card_description', 'teaser-card-s019 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'af59f18e4dac598a3852888626244e590ac4c960c5e6f649fcf691857588d7c2|1e743c81e366baba6e3829899df1df31ede39de2d83c13cf019995464eacc109|1e743c81e366baba6e3829899df1df31ede39de2d83c13cf019995464eacc109', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Founded by the Dorians on the northwest coast of Rhodes, Camirus rises in three levels to the temple complex of Athena Kameiras. Its covered reservoir held water for up to 400 families."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Camirus was founded by the Dorians [S3]; it lies on the northwest coast of Rhodes [S1, S2]; the city was built on three levels [S4]; at the top, the acropolis held the temple complex of Athena Kameiras [S5]; the city had a covered reservoir [S7]; the reservoir held water for up to 400 families [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Camirus was a city of ancient Rhodes, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Camirus]; Camirus was founded by the Dorians [SUPPORTED: https://en.wikipedia.org/wiki/Camirus]; Camirus lies on the northwest coast of Rhodes [SUPPORTED: https://en.wikipedia.org/wiki/Camirus]; The city rises in three levels [SUPPORTED: https://en.wikipedia.org/wiki/Camirus]; The top level holds the temple complex of Athena Kameiras [SUPPORTED: https://en.wikipedia.org/wiki/Camirus]; Camirus had a covered reservoir [SUPPORTED: https://en.wikipedia.org/wiki/Camirus]; The reservoir held water for up to 400 families [SUPPORTED: https://en.wikipedia.org/wiki/Camirus]"}]'::jsonb),
    ('9983bdce-9f35-47a3-a570-4021cfa41b97'::uuid, 'card_description', 'In the fourth century, Kourion suffered from five heavy earthquakes, but the city was mostly rebuilt.', 'On a limestone promontory nearly 100 metres high along Episkopi Bay sits the acropolis of Kourion. Five heavy earthquakes struck in the fourth century, yet the city was mostly rebuilt.', 'teaser-card-s019:9983bdce-9f35-47a3-a570-4021cfa41b97:card_description', 'teaser-card-s019 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '8ed2b69762db0f49c83bb639256c385d33cb9e96561794e14258400da87d9de8|4c76108cb85e62fb496af0024241d0114ae2612be4538eca495e84643f4a2707|4c76108cb85e62fb496af0024241d0114ae2612be4538eca495e84643f4a2707', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a limestone promontory nearly 100 metres high along Episkopi Bay sits the acropolis of Kourion. Five heavy earthquakes struck in the fourth century, yet the city was mostly rebuilt."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the acropolis of Kourion sits on a limestone promontory [S3]; the promontory is nearly 100 metres high [S3]; it lies along Episkopi Bay [S3]; five heavy earthquakes struck Kourion in the fourth century [S2]; the city was mostly rebuilt [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Kourion was an ancient city with an acropolis (on Cyprus) [SUPPORTED: https://en.wikipedia.org/wiki/Kourion]; The acropolis of Kourion sits on a limestone promontory [SUPPORTED: https://en.wikipedia.org/wiki/Kourion]; The promontory is nearly 100 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Kourion]; The promontory lies along Episkopi Bay [SUPPORTED: https://en.wikipedia.org/wiki/Kourion]; Five heavy earthquakes struck Kourion in the fourth century [SUPPORTED: https://en.wikipedia.org/wiki/Kourion]; The city was mostly rebuilt after the earthquakes [SUPPORTED: https://en.wikipedia.org/wiki/Kourion]"}]'::jsonb),
    ('99c67365-3376-46ae-9e60-0d2ec03bfff4'::uuid, 'card_description', 'Dedications to Coventina and votive deposits were found in a walled area which had been built to contain the outflow from a spring now called "Coventina''s Well".', 'A walled spring called Coventina''s Well held 13,487 coins, a relief of three water nymphs and altars to the goddess Coventina, some showing her reclining and partially clothed.', 'teaser-card-s019:99c67365-3376-46ae-9e60-0d2ec03bfff4:card_description', 'teaser-card-s019 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '3dd38fe8514dd46533b1cde72daae6d595a4c66844b2485d2531fe03fb95eca3|a6ae86f56725ea82f507bd4a21f06377ac00ca6096868683d1a11d8ebde805fd|a6ae86f56725ea82f507bd4a21f06377ac00ca6096868683d1a11d8ebde805fd', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "A walled spring called Coventina''s Well held 13,487 coins, a relief of three water nymphs and altars to the goddess Coventina, some showing her reclining and partially clothed."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the spring is walled (it lies in a walled enclosure) [S1, S2]; the spring is called Coventina''s Well [S1]; the well held 13,487 coins [S3]; the well held a relief of three water nymphs [S3]; the well held altars to the goddess Coventina [S3, S6]; some of the altars show Coventina reclining [S4]; some of the altars show Coventina partially clothed [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Coventina''s Well is a spring within a walled area (a Romano-British water shrine site on Hadrian''s Wall) [SUPPORTED: https://en.wikipedia.org/wiki/Coventina]; The walled spring is called Coventina''s Well [SUPPORTED: https://en.wikipedia.org/wiki/Coventina]; The well held 13,487 coins [SUPPORTED: https://en.wikipedia.org/wiki/Coventina]; The well held a relief of three water nymphs [SUPPORTED: https://en.wikipedia.org/wiki/Coventina]; Coventina is a goddess (of wells and springs) [SUPPORTED: https://en.wikipedia.org/wiki/Coventina]; The well held altars to the goddess Coventina [SUPPORTED: https://en.wikipedia.org/wiki/Coventina]; Some of the altars show Coventina reclining and partially clothed [SUPPORTED: https://en.wikipedia.org/wiki/Coventina]"}]'::jsonb),
    ('99e7c866-2d43-4ae6-abb7-3d174f4990ab'::uuid, 'card_description', 'Set on a granite tor in Lustleigh Cleave, this oval fort exploits natural rock outcrops as primary defenses. From the summit, the line of sight reaches Haytor, Bowerman''s Nose, and Hamel Down.', 'High on a ridge above the River Bovey, the granite of Hunter''s Tor holds an Iron Age hill fort, an oval 116 metres long with three ramparts to the South East and two to the North West.', 'teaser-card-s019:99e7c866-2d43-4ae6-abb7-3d174f4990ab:card_description', 'teaser-card-s019 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '1e9b9eb6262d0caca1ca6df943e30d14ddced4ba81e8bf3ccdc3f8a6671953d0|40b0ca5596ef274a7649588ea1a0c3def9b8af3d284061243ea82a6b3d526224|40b0ca5596ef274a7649588ea1a0c3def9b8af3d284061243ea82a6b3d526224', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "High on a ridge above the River Bovey, the granite of Hunter''s Tor holds an Iron Age hill fort, an oval 116 metres long with three ramparts to the South East and two to the North West."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site lies on a ridge above the River Bovey [S3]; it is high on the ridge (at its apex) [S3]; Hunter''s Tor is a granite tor [S1]; the tor holds an Iron Age hill fort [S4]; the hill fort is an oval enclosure [S5]; the oval is 116 metres long [S5]; it has three ramparts to the South East [S5]; it has two ramparts to the North West [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Hunter''s Tor holds a hill fort (central claim: the site is a hill fort on the tor in Lustleigh Cleave) [SUPPORTED: https://en.wikipedia.org/wiki/Hunter%27s_Tor,_Lustleigh_Cleave]; The hill fort dates to the Iron Age [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Hunter%27s_Tor,_Lustleigh_Cleave]; Hunter''s Tor is made of granite [SUPPORTED: https://en.wikipedia.org/wiki/Hunter%27s_Tor,_Lustleigh_Cleave]; The tor stands high, on the apex of a ridge [SUPPORTED: https://en.wikipedia.org/wiki/Hunter%27s_Tor,_Lustleigh_Cleave]; The ridge is above the River Bovey [SUPPORTED: https://en.wikipedia.org/wiki/Hunter%27s_Tor,_Lustleigh_Cleave]; The hill fort is an oval enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Hunter%27s_Tor,_Lustleigh_Cleave]; The oval is 116 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Hunter%27s_Tor,_Lustleigh_Cleave]; It has three ramparts to the South East [SUPPORTED: https://en.wikipedia.org/wiki/Hunter%27s_Tor,_Lustleigh_Cleave]; It has two ramparts to the North West [SUPPORTED: https://en.wikipedia.org/wiki/Hunter%27s_Tor,_Lustleigh_Cleave]"}]'::jsonb),
    ('9afe9a14-d2a8-495a-b0d3-ddb86a761a31'::uuid, 'card_description', 'A Bronze Age cairn with 18 thin jagged stone pillars jutting from a low mound like a crown. Originally 30 pillars stood here before 19th-century treasure hunters disturbed it.', '18 thin jagged pillars jut from the low Bronze Age cairn of Bryn Cader Faner, a name thought to mean ''the hill of the throne with the flag''. Treasure hunters left a hole in its centre.', 'teaser-card-s019:9afe9a14-d2a8-495a-b0d3-ddb86a761a31:card_description', 'teaser-card-s019 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'e1358a1fb76bc4d38e1174684aed26d5551a5fb8a98243e4b065c492a0c5cafa|0eb8b2472897ea62c5c07214fa8dc6f828274d40c89b6cb5827a9ddd5b98e1c3|0eb8b2472897ea62c5c07214fa8dc6f828274d40c89b6cb5827a9ddd5b98e1c3', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "18 thin jagged pillars jut from the low Bronze Age cairn of Bryn Cader Faner, a name thought to mean ''the hill of the throne with the flag''. Treasure hunters left a hole in its centre."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "there are 18 pillars [S2]; the pillars are thin and jagged [S2]; the pillars jut from the cairn [S2]; the cairn is low [S2]; Bryn Cader Faner is a Bronze Age cairn [S1]; the name is thought to mean ''the hill of the throne with the flag'' (hedged) [S6]; treasure hunters disturbed the site and left a hole [S4]; the hole is in the centre of the cairn [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Bryn Cader Faner is a cairn (central claim: a round cairn in Wales) [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Cader_Faner]; The cairn dates to the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Cader_Faner]; The cairn is low [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Cader_Faner]; There are 18 pillars [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Cader_Faner]; The pillars are thin and jagged [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Cader_Faner]; The pillars jut from the cairn [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Cader_Faner]; The name Bryn Cader Faner is thought to mean ''the hill of the throne with the flag'' [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Cader_Faner]; Treasure hunters disturbed the site [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Cader_Faner]; They left a hole in the centre of the cairn [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Cader_Faner]"}]'::jsonb),
    ('9b34941b-70ae-4be4-80a5-eefc3c470ce0'::uuid, 'card_description', 'A Roman city founded by Trajan around 102 AD to celebrate his Dacian Wars victory. It reached its zenith under the Antonine dynasty and minted its own coins.', 'Trajan founded Nicopolis ad Istrum in memory of his Dacian Wars victory. Its agora held his statue on horseback, and the city had a heated building with shops and enclosed space for walks.', 'teaser-card-s019:9b34941b-70ae-4be4-80a5-eefc3c470ce0:card_description', 'teaser-card-s019 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '0a7a7d83e6c69525e94c3c4e678b5a34da803876a03042a080e80584f266e53d|56a575df962cfe3beb23703a45586ca3961e9b356270d1855f502232c49cf2cf|56a575df962cfe3beb23703a45586ca3961e9b356270d1855f502232c49cf2cf', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Trajan founded Nicopolis ad Istrum in memory of his Dacian Wars victory. Its agora held his statue on horseback, and the city had a heated building with shops and enclosed space for walks."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Trajan founded Nicopolis ad Istrum [S4]; the founding was in memory of his victory in the Dacian Wars [S4]; the agora held a statue of Trajan on horseback [S7]; the city had a heated building with shops [S8]; the building had enclosed space for walks [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Nicopolis ad Istrum was a Roman (and Early Byzantine) town in northern Bulgaria [SUPPORTED: https://en.wikipedia.org/wiki/Nicopolis_ad_Istrum]; The ruins of Nicopolis ad Istrum lie in Bulgaria [SUPPORTED: https://en.wikipedia.org/wiki/Nicopolis_ad_Istrum]; Trajan founded Nicopolis ad Istrum [SUPPORTED: https://en.wikipedia.org/wiki/Nicopolis_ad_Istrum]; Trajan founded it in memory of his victory in the Dacian Wars [SUPPORTED: https://en.wikipedia.org/wiki/Nicopolis_ad_Istrum]; The agora held a statue of Trajan on horseback [SUPPORTED: https://en.wikipedia.org/wiki/Nicopolis_ad_Istrum]; The city had a heated building with shops and enclosed space for walks [SUPPORTED: https://en.wikipedia.org/wiki/Nicopolis_ad_Istrum]"}]'::jsonb),
    ('9b3bade9-0410-4e3d-8c00-89cdc1b776ed'::uuid, 'card_description', 'Non-concentric layout: a 1.2-hectare inner enclosure inside a larger 4-hectare outer ring on Keynston Down. The offset arrangement reflects two distinct phases of construction.', 'On a hill on Keynston Down lies Buzbury Rings, an Iron Age hillfort: an inner enclosure of about 3 acres sits off-centre in an outer one of about 10 acres, whose ditch is now buried.', 'teaser-card-s019:9b3bade9-0410-4e3d-8c00-89cdc1b776ed:card_description', 'teaser-card-s019 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'e31ae4ab0315e9385d2ca9a5b0c06fb69cc2eb3fac6ac2f714802935a91ad584|16879e73c022cbc81039481d99fa094d2affeb0ca017888d3ffbb89b6b585659|16879e73c022cbc81039481d99fa094d2affeb0ca017888d3ffbb89b6b585659', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a hill on Keynston Down lies Buzbury Rings, an Iron Age hillfort: an inner enclosure of about 3 acres sits off-centre in an outer one of about 10 acres, whose ditch is now buried."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Buzbury Rings lies on a hill on Keynston Down [S2]; it is an Iron Age hillfort [S1]; it has an inner enclosure of about 3 acres [S3]; it has an outer enclosure of about 10 acres [S4]; the inner enclosure sits off-centre in the outer one (not concentric) [S4]; the outer enclosure''s outer ditch is now buried [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Buzbury Rings is a hillfort (central claim; in Dorset, England) [SUPPORTED: https://en.wikipedia.org/wiki/Buzbury_Rings]; The hillfort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Buzbury_Rings]; It lies on a hill [SUPPORTED: https://en.wikipedia.org/wiki/Buzbury_Rings]; The hill is on Keynston Down [SUPPORTED: https://en.wikipedia.org/wiki/Buzbury_Rings]; The inner enclosure is about 3 acres [SUPPORTED: https://en.wikipedia.org/wiki/Buzbury_Rings]; The outer enclosure is about 10 acres [SUPPORTED: https://en.wikipedia.org/wiki/Buzbury_Rings]; The inner enclosure sits off-centre (not concentric) within the outer one [SUPPORTED: https://en.wikipedia.org/wiki/Buzbury_Rings]; The outer ditch is now buried [SUPPORTED: https://en.wikipedia.org/wiki/Buzbury_Rings]"}]'::jsonb),
    ('9bec7da2-8ff6-46be-a2cf-34d689358bf2'::uuid, 'card_description', 'The stoa stretched along most of the southern edge of the Classical Agora, facing north onto it. The first traces were identified and excavated in 1936 under the direction of Eugene Vanderpool.', 'Behind a two-aisled colonnade facing the Agora, South Stoa I held fifteen rooms, probably headquarters and dining rooms for Athenian officials. It appears to be the earliest of its design.', 'teaser-card-s019:9bec7da2-8ff6-46be-a2cf-34d689358bf2:card_description', 'teaser-card-s019 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '4f6b26d8430c0b30d24b8ec3235e2c78a97050216d9898cb5b80571f459babec|2b8cf323caf60943947d2350fa70f91258b6340d3b06723a9f115092726e9f25|2b8cf323caf60943947d2350fa70f91258b6340d3b06723a9f115092726e9f25', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Behind a two-aisled colonnade facing the Agora, South Stoa I held fifteen rooms, probably headquarters and dining rooms for Athenian officials. It appears to be the earliest of its design."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "South Stoa I had a two-aisled colonnade [S6]; the colonnade faced the Agora [S4, S6]; the rooms lay behind the colonnade (along the back wall) [S6]; the stoa held fifteen rooms [S6]; it probably served as headquarters and dining rooms (hedged) [S2]; the headquarters and dining rooms were for Athenian officials [S2]; it appears to be the earliest example of its design (hedged) [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "South Stoa I is a stoa (colonnaded building) on the Agora of Athens (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/South_Stoa_I_(Athens)]; It had a two-aisled colonnade [SUPPORTED: https://en.wikipedia.org/wiki/South_Stoa_I_(Athens)]; The colonnade faced the Agora [SUPPORTED: https://en.wikipedia.org/wiki/South_Stoa_I_(Athens)]; It held fifteen rooms [SUPPORTED: https://en.wikipedia.org/wiki/South_Stoa_I_(Athens)]; The rooms lay behind the colonnade, along the back wall [SUPPORTED: https://en.wikipedia.org/wiki/South_Stoa_I_(Athens)]; It probably served as headquarters for Athenian officials [SUPPORTED: https://en.wikipedia.org/wiki/South_Stoa_I_(Athens)]; The rooms were probably dining rooms [SUPPORTED: https://en.wikipedia.org/wiki/South_Stoa_I_(Athens)]; The users were Athenian officials (magistrates) [SUPPORTED: https://en.wikipedia.org/wiki/South_Stoa_I_(Athens)]; It appears to be the earliest of its design [SUPPORTED: https://en.wikipedia.org/wiki/South_Stoa_I_(Athens)]"}]'::jsonb),
    ('9c2327c0-112b-4d32-9d73-c4ffac345288'::uuid, 'card_description', 'The Gallic city that became modern Grenoble, first mentioned in a 43 BC letter to Cicero. It was renamed Gratianopolis in 381 AD to honor Emperor Gratian.', 'Cularo, a town founded by the Allobroges, thanked the emperor Gratian for its bishopric by renaming itself Gratianopolis in 381. That name became Grenoble, where Gallo-Roman walls remain.', 'teaser-card-s019:9c2327c0-112b-4d32-9d73-c4ffac345288:card_description', 'teaser-card-s019 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'cff62c6838d099a1dd9c9cab7fe08d0a73af094584872853d04d14c930045df0|2fd58fdd675cb44c1e103575da7537d107ae932d4f4aaeaff1f544eb0909490f|2fd58fdd675cb44c1e103575da7537d107ae932d4f4aaeaff1f544eb0909490f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cularo, a town founded by the Allobroges, thanked the emperor Gratian for its bishopric by renaming itself Gratianopolis in 381. That name became Grenoble, where Gallo-Roman walls remain."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cularo was a town [S3]; the town was founded by the Allobroges [S3]; the inhabitants thanked the emperor Gratian for creating their bishopric [S5]; they did so by renaming the town Gratianopolis [S5]; the renaming took place in 381 [S5]; the name Gratianopolis became Grenoble [S6]; sections of Gallo-Roman walls remain in Grenoble [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cularo was a Gallic town that evolved into modern Grenoble [SUPPORTED: https://en.wikipedia.org/wiki/Cularo]; Grenoble, the later Cularo, is in France [SUPPORTED: https://en.wikipedia.org/wiki/Grenoble]; The town of Cularo was founded by the Allobroges [SUPPORTED: https://en.wikipedia.org/wiki/Cularo]; The inhabitants wished to thank the emperor Gratian for creating the bishopric and renamed the town Gratianopolis [SUPPORTED: https://en.wikipedia.org/wiki/Cularo]; The renaming to Gratianopolis took place in 381 [SUPPORTED: https://fr.wikipedia.org/wiki/Histoire_de_Grenoble]; The name Gratianopolis became Grenoble [SUPPORTED: https://en.wikipedia.org/wiki/Cularo]; Gallo-Roman walls remain in Grenoble [SUPPORTED: https://en.wikipedia.org/wiki/Cularo]"}]'::jsonb),
    ('9ceb5947-c91f-4a1f-8c8f-6a67dbb88de2'::uuid, 'card_description', 'Phoenician colony from the 7th century BC on an Atlantic peninsula, settled for nearly 3,000 years without interruption. By the 18th century it was western Europe''s dominant Atlantic trading port.', 'Phoenicians founded Cádiz as a trading post for gold, tin and especially silver. Tradition dates it to circa 1100 BC, yet no strata on the site can be dated earlier than the 9th century BC.', 'teaser-card-s019:9ceb5947-c91f-4a1f-8c8f-6a67dbb88de2:card_description', 'teaser-card-s019 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '0888b7bdf0eeb5914d0c4545de19dae04430a487838d607de203a16138a20860|cb75c907fee018e996904b90e131fd6a5553471e9ed5688d600b68d61f134a77|cb75c907fee018e996904b90e131fd6a5553471e9ed5688d600b68d61f134a77', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Phoenicians founded Cádiz as a trading post for gold, tin and especially silver. Tradition dates it to circa 1100 BC, yet no strata on the site can be dated earlier than the 9th century BC."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Phoenicians founded Cádiz [S1]; it was founded as a trading post [S1]; it was founded to access metals including gold, tin and especially silver [S2]; tradition dates the founding to circa 1100 BC [S3]; no archaeological strata on the site can be dated earlier than the 9th century BC [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cádiz (Gadir) is a city/settlement in Spain founded by Phoenicians (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/C%C3%A1diz]; The Phoenicians founded it as a trading post / trading hub [SUPPORTED: https://en.wikipedia.org/wiki/C%C3%A1diz]; The metals sought were gold, tin and especially silver [SUPPORTED: https://en.wikipedia.org/wiki/C%C3%A1diz]; Tradition dates the founding of Cádiz to circa 1100 BC [SUPPORTED: https://en.wikipedia.org/wiki/C%C3%A1diz]; No archaeological strata on the site can be dated earlier than the 9th century BC [SUPPORTED: https://en.wikipedia.org/wiki/C%C3%A1diz]; There is a discrepancy between the c. 1100 BC tradition and the archaeological strata, which has been resolved by assuming a small seasonal trading post at first [SUPPORTED: https://en.wikipedia.org/wiki/C%C3%A1diz]"}]'::jsonb),
    ('9cf1ec14-dd93-4270-897f-158203e91758'::uuid, 'card_description', 'Its drystone walls rise to nearly 7 metres above the doorway, crowned by a massive triangular lintel stone. External diameter: 14.5 metres, built entirely without mortar from local Sutherland stone.', 'Over the entrance of Dun Dornaigil, an Iron Age broch in Sutherland, sits a massive triangular lintel, the wall there rising to nearly 7 metres. Inside, collapsed rubble bars the way.', 'teaser-card-s019:9cf1ec14-dd93-4270-897f-158203e91758:card_description', 'teaser-card-s019 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'e5bfdfaac8b0072ab21af6f3a6d7740f4b017c58d4c29791c3f7a9673ef74d07|f731071f627ae91d53b5c84dd2e9e7bb26707b9f8b993c470e1f699893d3675b|f731071f627ae91d53b5c84dd2e9e7bb26707b9f8b993c470e1f699893d3675b', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Over the entrance of Dun Dornaigil, an Iron Age broch in Sutherland, sits a massive triangular lintel, the wall there rising to nearly 7 metres. Inside, collapsed rubble bars the way."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Dun Dornaigil is an Iron Age broch [S1]; it lies in Sutherland [S1]; a massive triangular lintel sits over the entrance [S6]; the wall above the doorway rises to nearly 7 metres [S4]; collapsed rubble inside blocks access to the interior [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Dun Dornaigil is a broch (a drystone round tower), the site''s type (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Dornaigil]; The broch dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Dornaigil]; The broch is in Sutherland, Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Dornaigil]; A massive triangular lintel sits over the entrance [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Dornaigil]; The wall above the doorway rises to nearly 7 metres [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Dornaigil]; Inside, collapsed rubble blocks access to the interior of the broch [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Dornaigil]"}]'::jsonb),
    ('9db1409d-3216-4448-b9c9-c42d5071ba4d'::uuid, 'card_description', 'Bronze Age axial stone circle of 13 stones — four now missing — with a diameter of 9.1 metres in Cork. Its portal stones stand nearly 2.5 metres tall, among the tallest in the region.', 'The axis of Bohonagh Stone Circle points to sunset at the equinoxes. Many of its stones have quartz inclusions, and in 1959 excavators found a central pit with charcoal and cremated bone.', 'teaser-card-s019:9db1409d-3216-4448-b9c9-c42d5071ba4d:card_description', 'teaser-card-s019 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '9907b908e707393e04e86be4798a97be0e8089712056f13451eb7b204db93b19|814c8e152e1d33c8153fa8d3f23654b6a614afd7a4b908e43106d396bc3e51e8|814c8e152e1d33c8153fa8d3f23654b6a614afd7a4b908e43106d396bc3e51e8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The axis of Bohonagh Stone Circle points to sunset at the equinoxes. Many of its stones have quartz inclusions, and in 1959 excavators found a central pit with charcoal and cremated bone."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the circle''s axis points to sunset at the equinoxes [S6]; many of the stones have quartz inclusions [S7]; the site was excavated in 1959 [S8]; the excavation found a central pit [S8]; the pit contained charcoal and cremated bone [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Bohonagh is a stone circle (an axial stone circle) in Ireland (County Cork) (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Bohonagh]; Bohonagh Stone Circle is in Ireland, in County Cork near Rosscarbery [SUPPORTED: https://en.wikipedia.org/wiki/Bohonagh]; The axis of the circle points to sunset at the equinoxes [SUPPORTED: https://en.wikipedia.org/wiki/Bohonagh]; The equinoctial sunset is seen at the circle (independent corroboration of the equinox sunset alignment) [SUPPORTED: https://roaringwaterjournal.com/tag/equinox-at-bohonagh/]; Many of the stones of the circle have quartz inclusions [SUPPORTED: https://en.wikipedia.org/wiki/Bohonagh]; The site was excavated in 1959 [SUPPORTED: https://en.wikipedia.org/wiki/Bohonagh]; The excavators found a central pit containing charcoal and cremated bone [SUPPORTED: https://en.wikipedia.org/wiki/Bohonagh]"}]'::jsonb),
    ('9dbff73b-6505-430a-9b75-8630df8b451c'::uuid, 'card_description', 'Clausentum was a small town in the Roman province of Britannia. Four Roman milestones and three possible milestones were found at Bitterne between 1800 and 1850.', 'Clausentum was a small town in Roman Britannia, later walled in stone around 280–90, at about the same time as the fort at nearby Portchester. Four Roman milestones were found at Bitterne.', 'teaser-card-s019:9dbff73b-6505-430a-9b75-8630df8b451c:card_description', 'teaser-card-s019 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'a931c8b52520e13613f5946d91b504deb10bbd5a2dbb876e676cdfa2694ebf12|9f64401b4b63155c32c606de38a860ca51efd65befcf325ad94812905b66cf62|9f64401b4b63155c32c606de38a860ca51efd65befcf325ad94812905b66cf62', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Clausentum was a small town in Roman Britannia, later walled in stone around 280–90, at about the same time as the fort at nearby Portchester. Four Roman milestones were found at Bitterne."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Clausentum was a small town [S1]; it lay in Roman Britannia [S1]; it was later walled in stone [S6]; the wall was erected around 280-90 [S7]; this was at about the same time as the fort at nearby Portchester [S7]; four Roman milestones were found at Bitterne [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Clausentum was a small town in the Roman province of Britannia (at Bitterne Manor, Southampton, England) [SUPPORTED: https://en.wikipedia.org/wiki/Clausentum]; The site of Clausentum is at Bitterne Manor (Bitterne), a suburb of Southampton [SUPPORTED: https://en.wikipedia.org/wiki/Clausentum]; A stone defensive wall was later erected around the town [SUPPORTED: https://en.wikipedia.org/wiki/Clausentum]; The walls were erected around 280-90 [SUPPORTED: https://en.wikipedia.org/wiki/Clausentum]; The walling was at about the same time as the fort at nearby Portchester [SUPPORTED: https://en.wikipedia.org/wiki/Clausentum]; Four Roman milestones were found at Bitterne [SUPPORTED: https://en.wikipedia.org/wiki/Clausentum]"}]'::jsonb),
    ('9e855760-fb85-46b1-8d8b-3395a3d7bce3'::uuid, 'card_description', NULL, 'Dafo Temple keeps a Big Buddha almost 15 meters in height, its nose alone 1.5 meters. Nearby lies a grotto considered among China''s earliest, where a reclining Buddha rests.', 'teaser-card-s019:9e855760-fb85-46b1-8d8b-3395a3d7bce3:card_description', 'teaser-card-s019 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', 'aadd449410c43067a7afe45beff20ea2f2a90a635cbd3586b5a0efe2a5726572|0ec5399ea215a58b1344bef4ae1ca2a83d46d492bbe73f39b77ac4e28933479f|0ec5399ea215a58b1344bef4ae1ca2a83d46d492bbe73f39b77ac4e28933479f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Dafo Temple keeps a Big Buddha almost 15 meters in height, its nose alone 1.5 meters. Nearby lies a grotto considered among China''s earliest, where a reclining Buddha rests."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Dafo Temple has a Big Buddha [S1, S2]; the Big Buddha is almost 15 meters in height [S2]; the Big Buddha''s nose alone is 1.5 meters [S2]; a grotto lies nearby (in the surrounding area) [S3]; the grotto is considered among China''s earliest [S3]; a reclining Buddha is found in the grotto [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Dafo Temple is a temple (a Buddhist temple in Zhejiang, symbol of Xinchang County) [SUPPORTED: https://en.wikipedia.org/wiki/Dafo_Temple_(Xinchang)]; The temple keeps a Big Buddha (a Big Buddha Hall with the Big Buddha statue) [SUPPORTED: https://en.wikipedia.org/wiki/Dafo_Temple_(Xinchang)]; The Big Buddha is almost 15 meters in height [SUPPORTED: https://en.wikipedia.org/wiki/Dafo_Temple_(Xinchang)]; The Big Buddha''s nose alone is 1.5 meters [SUPPORTED: https://en.wikipedia.org/wiki/Dafo_Temple_(Xinchang)]; A grotto lies nearby (in the surrounding area of the temple) [SUPPORTED: https://en.wikipedia.org/wiki/Dafo_Temple_(Xinchang)]; The grotto is considered among China''s earliest [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Dafo_Temple_(Xinchang)]; A reclining Buddha rests in the grotto [SUPPORTED: https://en.wikipedia.org/wiki/Dafo_Temple_(Xinchang)]"}]'::jsonb),
    ('a0c043a9-fc02-49d8-93e8-39100e5ed8c7'::uuid, 'card_description', 'Rock-hewn into the Mtkvari River''s left bank, this ancient town spans Early Iron Age through Late Medieval structures — blending Anatolian and Iranian rock-cut architectural styles in a single site.', 'Some 10 kilometers east of Gori lies Uplistsikhe, a rock-hewn town archaeologists count among Georgia''s oldest urban settlements, where a narrow pass and a tunnel cut through rock.', 'teaser-card-s019:a0c043a9-fc02-49d8-93e8-39100e5ed8c7:card_description', 'teaser-card-s019 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'de11234f0ffc85345bf4653794cef1ade23975bb86746b7ea60d340312517b92|7ee0eaee34872c86a38352ba330daafb85fd69557db282dea8fe5e1456de9012|7ee0eaee34872c86a38352ba330daafb85fd69557db282dea8fe5e1456de9012', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Some 10 kilometers east of Gori lies Uplistsikhe, a rock-hewn town archaeologists count among Georgia''s oldest urban settlements, where a narrow pass and a tunnel cut through rock."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Uplistsikhe lies some 10 kilometers east of Gori [S1]; Uplistsikhe is a rock-hewn town [S1]; archaeologists count it among Georgia''s oldest urban settlements [S2]; a narrow pass is cut through rock [S5]; a tunnel is part of the site, alongside the pass [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Uplistsikhe is a town (an ancient town in Georgia) [SUPPORTED: https://en.wikipedia.org/wiki/Uplistsikhe]; Uplistsikhe is rock-hewn [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Uplistsikhe]; Uplistsikhe lies some 10 kilometers east of Gori [SUPPORTED: https://en.wikipedia.org/wiki/Uplistsikhe]; Archaeologists count Uplistsikhe among Georgia''s oldest urban settlements [SUPPORTED: https://en.wikipedia.org/wiki/Uplistsikhe]; A narrow pass is cut through rock at the site [SUPPORTED: https://en.wikipedia.org/wiki/Uplistsikhe]; A tunnel is cut through rock at the site [SUPPORTED: https://en.wikipedia.org/wiki/Uplistsikhe]"}]'::jsonb),
    ('a1118dbb-9f77-4aae-a1d9-7fd43a7b29ec'::uuid, 'card_description', 'Twin Iron Age hillforts facing each other across a ridge. The White Caterthun has a massive collapsed stone wall; the Brown has four concentric earthwork rings.', 'On a ridge near Brechin, the Caterthuns hold two Iron Age forts: the White Caterthun, an oval fort of massive dry-stone wall, and the Brown Caterthun, a series of earthen embankments.', 'teaser-card-s019:a1118dbb-9f77-4aae-a1d9-7fd43a7b29ec:card_description', 'teaser-card-s019 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '3de232f0193eb5549c78b57669031e4a53828a08cd6a0d569153fc2838a5b2a9|3542f896b98af50b59d22b784adad4706baa53865d803f05f7fd5e25dfeca063|3542f896b98af50b59d22b784adad4706baa53865d803f05f7fd5e25dfeca063', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a ridge near Brechin, the Caterthuns hold two Iron Age forts: the White Caterthun, an oval fort of massive dry-stone wall, and the Brown Caterthun, a series of earthen embankments."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Caterthuns are a ridge (of hills) [S1]; the ridge is near Brechin [S1]; the Caterthuns hold two Iron Age forts [S2]; the two forts are the White Caterthun and the Brown Caterthun [S2]; the White Caterthun is an oval fort [S3]; the White Caterthun fort consists of a massive dry-stone wall [S3]; the Brown Caterthun is a series of earthen embankments [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Caterthuns are the site of two Iron Age forts [SUPPORTED: https://en.wikipedia.org/wiki/Caterthuns]; The Caterthuns are on a ridge [SUPPORTED: https://en.wikipedia.org/wiki/Caterthuns]; The ridge is near Brechin [SUPPORTED: https://en.wikipedia.org/wiki/Caterthuns]; The two forts are named the White Caterthun and the Brown Caterthun [SUPPORTED: https://en.wikipedia.org/wiki/Caterthuns]; The White Caterthun is an oval fort [SUPPORTED: https://en.wikipedia.org/wiki/Caterthuns]; The White Caterthun''s fort consists of a massive dry-stone wall [SUPPORTED: https://en.wikipedia.org/wiki/Caterthuns]; The Brown Caterthun is a series of earthen embankments [SUPPORTED: https://en.wikipedia.org/wiki/Caterthuns]"}]'::jsonb),
    ('a1174754-0d0f-4d54-8802-e51658125770'::uuid, 'card_description', 'The mound at Pirak rises 8 metres and covers 4.8 hectares in Balochistan. Occupation ran from 1800 to 800 BC near two related Indus-era sites along the Nari River.', 'In Balochistan, Pirak has some very early ironwork and iron artefacts. Its excavator dates the occupation from circa 1800 BCE to 800 BCE and records three phases of unbroken occupation.', 'teaser-card-s019:a1174754-0d0f-4d54-8802-e51658125770:card_description', 'teaser-card-s019 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '2dbc7ba6dda71e39f2f990b4bfb977ac37f6132cd9f3816f7f689961b3172088|2fb0ef18cd44d208b4dc31eef26cf2f8318955360f183c375305061453e43189|2fb0ef18cd44d208b4dc31eef26cf2f8318955360f183c375305061453e43189', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In Balochistan, Pirak has some very early ironwork and iron artefacts. Its excavator dates the occupation from circa 1800 BCE to 800 BCE and records three phases of unbroken occupation."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Pirak is in Balochistan [S1]; Pirak has some very early ironwork and iron artefacts [S6]; the excavator dates the occupation from circa 1800 BCE to 800 BCE [S5]; the excavator records three phases of unbroken occupation [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Pirak is an archaeological site in Balochistan (Pakistan) [SUPPORTED: https://en.wikipedia.org/wiki/Pirak]; Pirak has some very early ironwork and iron artefacts [SUPPORTED: https://en.wikipedia.org/wiki/Pirak]; Its excavator dates the occupation from circa 1800 BCE to 800 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Pirak]; The excavator records three phases of unbroken occupation [SUPPORTED: https://en.wikipedia.org/wiki/Pirak]"}]'::jsonb),
    ('a28e4962-5513-4955-b1e0-d6a8f8f244cc'::uuid, 'card_description', 'Around 3000 BC. A Neolithic gallery grave of the Wartberg culture near Marburg — unique for its exceptionally rich ceramic assemblage. Its sunken rectangular chamber measured 5 x 2.2 metres.', 'In 1931 a farmer ploughing near Marburg encountered an obstacle: the Lohra Megalithic Tomb, a large main chamber with a small open antechamber, its dead cremated.', 'teaser-card-s019:a28e4962-5513-4955-b1e0-d6a8f8f244cc:card_description', 'teaser-card-s019 (teaser-card): teaser card, 162 characters, checked PASS, web-verified VERIFIED', '9b1c44e3c1fce9db0251ef100a5a844bf0ef529e53326f10eb24635ae9540e09|57b6f7733a5f083a4ef404aa59e6aa9b67e64b592534c934bbc7437b642dc2a4|57b6f7733a5f083a4ef404aa59e6aa9b67e64b592534c934bbc7437b642dc2a4', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In 1931 a farmer ploughing near Marburg encountered an obstacle: the Lohra Megalithic Tomb, a large main chamber with a small open antechamber, its dead cremated."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the tomb was found in 1931 [S5]; it was found by a farmer ploughing [S5]; the farmer encountered an obstacle (which was the tomb) [S5]; the tomb is near Marburg [S1]; the tomb has a large main chamber [S6]; the tomb has a small open antechamber [S6]; the dead in the tomb had been cremated [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Lohra Megalithic Tomb is a megalithic tomb/monument [SUPPORTED: https://en.wikipedia.org/wiki/Lohra_(megalithic_tomb)]; The tomb is near Marburg (Germany) [SUPPORTED: https://en.wikipedia.org/wiki/Lohra_(megalithic_tomb)]; The tomb was found in 1931 [SUPPORTED: https://en.wikipedia.org/wiki/Lohra_(megalithic_tomb)]; It was a farmer who found it, while ploughing [SUPPORTED: https://en.wikipedia.org/wiki/Lohra_(megalithic_tomb)]; The farmer encountered an obstacle (the tomb''s sandstone block) when ploughing [SUPPORTED: https://en.wikipedia.org/wiki/Lohra_(megalithic_tomb)]; The tomb has a large main chamber [SUPPORTED: https://en.wikipedia.org/wiki/Lohra_(megalithic_tomb)]; The tomb has a small open antechamber [SUPPORTED: https://en.wikipedia.org/wiki/Lohra_(megalithic_tomb)]; The dead were cremated [SUPPORTED: https://en.wikipedia.org/wiki/Lohra_(megalithic_tomb)]"}]'::jsonb),
    ('a29d5e41-b7ef-4f9d-baf2-33c562ba9273'::uuid, 'card_description', 'A 735 BC Urartian fortress, the best preserved in the Sevan basin. Foundations of city walls, gates, and grain storage rooms survive among the ruins.', 'On the southern shore of Lake Sevan, a cuneiform stele at Teysheba says the Urartian king Rusa I founded it in honor of the weather god Theispas, to cow the enemies of Biaina.', 'teaser-card-s019:a29d5e41-b7ef-4f9d-baf2-33c562ba9273:card_description', 'teaser-card-s019 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '6aebe0d4b4be2b92c86ede301137ee5cc74171ffa72b55aacfe73d9d7592846e|c202cf2ac250b5961cf7e4b0f519886d2bc1450466d3c5ef4aecd78f2266052c|c202cf2ac250b5961cf7e4b0f519886d2bc1450466d3c5ef4aecd78f2266052c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the southern shore of Lake Sevan, a cuneiform stele at Teysheba says the Urartian king Rusa I founded it in honor of the weather god Theispas, to cow the enemies of Biaina."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is on the southern shore of Lake Sevan [S6]; a stele at the site bears a cuneiform inscription [S4]; the inscription says the Urartian king Rusa I established the site [S4]; it was founded in honor of the weather god Theispas [S4]; the inscription says it was founded to cow the enemies of Biaina [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Teysheba (the site also called Odzaberd) is an ancient settlement (citadel, fortress and outer town) on the shore of Lake Sevan, Armenia [SUPPORTED: https://en.wikipedia.org/wiki/Odzaberd]; The site lies on the southern shore of Lake Sevan [SUPPORTED: https://en.wikipedia.org/wiki/Odzaberd]; The site is known as Teysheba (variant spellings of the Urartian god''s name, Teisheba) [SUPPORTED: https://en.wikipedia.org/wiki/Odzaberd]; A stele at the site bears a cuneiform inscription (in Urartian) [SUPPORTED: https://en.wikipedia.org/wiki/Odzaberd]; The stele says the Urartian king Rusa I founded the place [SUPPORTED: https://en.wikipedia.org/wiki/Odzaberd]; The foundation was in honor of the weather god Theispas [SUPPORTED: https://en.wikipedia.org/wiki/Odzaberd]; The purpose was to cow the enemies of Biaina [SUPPORTED: https://en.wikipedia.org/wiki/Odzaberd]"}]'::jsonb),
    ('a38ebb14-4f7b-459e-9ca4-0cbc15d16a32'::uuid, 'card_description', 'A rocky hillock near Beddgelert, rising 76 meters above the Glaslyn valley, with stone ramparts from an 800 BC fort. Arthurian legend places Merlin here and two battling dragons beneath its pool.', 'Rising some 76 m above the Glaslyn valley, the wooded hillock of Dinas Emrys is where, legend says, Vortigern fled from the Anglo-Saxon invaders to make his royal retreat.', 'teaser-card-s019:a38ebb14-4f7b-459e-9ca4-0cbc15d16a32:card_description', 'teaser-card-s019 (teaser-card): teaser card, 171 characters, checked PASS, web-verified VERIFIED', 'a2d55ea3a3c05a5dfe363c6dab42e4824e4aee405b6bf994cf90caca8b144cee|9b275d3ef6c631e961dfe6788be221f2499718058312e717d93ca489628e10f2|9b275d3ef6c631e961dfe6788be221f2499718058312e717d93ca489628e10f2', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Rising some 76 m above the Glaslyn valley, the wooded hillock of Dinas Emrys is where, legend says, Vortigern fled from the Anglo-Saxon invaders to make his royal retreat."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Dinas Emrys rises some 76 m above the Glaslyn valley [S2]; Dinas Emrys is a wooded hillock [S1]; according to legend, Vortigern fled from the Anglo-Saxon invaders [S6]; according to legend, he chose this hill as the site of his royal retreat [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Dinas Emrys is a rocky, wooded hillock with a hillfort (in Wales, near Beddgelert, Gwynedd) [SUPPORTED: https://en.wikipedia.org/wiki/Dinas_Emrys]; It rises some 76 m above the Glaslyn valley [SUPPORTED: https://en.wikipedia.org/wiki/Dinas_Emrys]; According to legend Vortigern fled from the Anglo-Saxon invaders (into Wales) [SUPPORTED: https://en.wikipedia.org/wiki/Dinas_Emrys]; Vortigern chose this hillfort as the site for his royal retreat [SUPPORTED: https://en.wikipedia.org/wiki/Dinas_Emrys]"}]'::jsonb),
    ('a3c3f3e8-b249-4f70-bb03-8cd733213e76'::uuid, 'card_description', 'A Celtic settlement dating to around 300 BC on the southern slopes of the Sandberg ridge near Platt. The Sandberg also preserves traces reaching back to the Neolithic period.', 'Around 300 B.C. a Celtic city lay on the southern slopes of the Sandberg ridge near Platt, at its climax at least 450 buildings and a halidom district with several cult sites.', 'teaser-card-s019:a3c3f3e8-b249-4f70-bb03-8cd733213e76:card_description', 'teaser-card-s019 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '0cf8e59c8073ad1212328320318563860335cd2a5ea9580cfc69101a18d04c93|68b2f32b5cfb1535da369c70ca9ea4c94101706c0d355794a1e80121eb1d09df|68b2f32b5cfb1535da369c70ca9ea4c94101706c0d355794a1e80121eb1d09df', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Around 300 B.C. a Celtic city lay on the southern slopes of the Sandberg ridge near Platt, at its climax at least 450 buildings and a halidom district with several cult sites."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "around 300 B.C. a Celtic city existed here [S2]; the city lay on the southern slopes of the Sandberg ridge [S2]; the ridge lies near Platt (the Platt area) [S1, S2]; at its climax the settlement comprised at least 450 buildings [S3]; it included a halidom district with several cult sites [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "A Celtic city (settlement) lay on the southern slopes of the Sandberg ridge near Platt, Austria [SUPPORTED: https://en.wikipedia.org/wiki/Platt,_Austria]; The Sandberg ridge lies by the village of Platt (between Platt and Roseldorf) [SUPPORTED: https://en.wikipedia.org/wiki/Sandberg_(Celtic_settlement)]; The city dates to around 300 B.C. [SUPPORTED: https://en.wikipedia.org/wiki/Platt,_Austria]; At its climax the settlement comprised at least 450 buildings [SUPPORTED: https://en.wikipedia.org/wiki/Platt,_Austria]; The settlement included a halidom (sacred) district with several cult sites [SUPPORTED: https://en.wikipedia.org/wiki/Platt,_Austria]; Excavations confirmed the structures to be Celtic sanctuaries (cult sites) [SUPPORTED: https://en.wikipedia.org/wiki/Sandberg_(Celtic_settlement)]"}]'::jsonb),
    ('a42d9ff4-6d8d-4cb2-bb1d-64b1c66cb290'::uuid, 'card_description', 'Llyn Cerrig Bach is a small lake located between Rhosneigr and Valley in the west of Anglesey.', 'In 1942, as peat was dug for a runway extension, over 150 Iron Age metal objects surfaced at Llyn Cerrig Bach, apparently votive offerings. The first was an iron gang chain for slaves.', 'teaser-card-s019:a42d9ff4-6d8d-4cb2-bb1d-64b1c66cb290:card_description', 'teaser-card-s019 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '81bd1927cb5882429e530097a110e92d9b7f423c9b761a390e3159d1d985c15c|e5ecfaa24efb2afedd41bb84e60f239b6408a4df75d6d3d7cea5d6572bfd9cf5|e5ecfaa24efb2afedd41bb84e60f239b6408a4df75d6d3d7cea5d6572bfd9cf5', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In 1942, as peat was dug for a runway extension, over 150 Iron Age metal objects surfaced at Llyn Cerrig Bach, apparently votive offerings. The first was an iron gang chain for slaves."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the discovery was made in 1942 [S2]; peat was being dug for a runway extension when the objects surfaced [S4, S5]; over 150 Iron Age metal objects were found [S2]; the objects were found at Llyn Cerrig Bach [S2, S5]; the objects were apparently votive offerings [S2]; the first object found was an iron gang chain [S6]; the gang chain was used for slaves [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Llyn Cerrig Bach is a small lake in the west of Anglesey, Wales, where an Iron Age deposit of metalwork was found [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Cerrig_Bach]; The objects were discovered there in 1942 [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Cerrig_Bach]; There were over 150 objects [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Cerrig_Bach]; The objects are of the Iron Age (deposited from about 300 BC to 100 AD) [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Cerrig_Bach]; The objects are metal (mainly iron, some bronze or copper alloy) [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Cerrig_Bach]; The objects are apparently votive offerings [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Cerrig_Bach]; They surfaced when ground was being cleared for a runway extension [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Cerrig_Bach]; They surfaced while peat was being dug (extracted) [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Cerrig_Bach]; The first object found was an iron gang chain [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Cerrig_Bach]; The gang chain was used for slaves [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Cerrig_Bach]"}]'::jsonb),
    ('a62177c7-346f-4323-a896-087f608ea5be'::uuid, 'card_description', 'A 2nd-century AD temple to Zeus Theos in Dura-Europos. The city blended Greek, Parthian, and Roman religion in one multicultural frontier post.', 'Above the east entrance of the Temple of Zeus Theos, an inscription named its builder, one Seleukos, and the year AD 114. Within its monumental court stood a large Naos.', 'teaser-card-s019:a62177c7-346f-4323-a896-087f608ea5be:card_description', 'teaser-card-s019 (teaser-card): teaser card, 169 characters, checked PASS, web-verified VERIFIED', '0829c422723cb88c763d157861888a7ab2ddb27db6985474f93ad6cedcdd9485|703b9cb92e8939631ae2a393ee33bd196f523ecbb8d7c179ab4bb27956fe63ab|703b9cb92e8939631ae2a393ee33bd196f523ecbb8d7c179ab4bb27956fe63ab', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Above the east entrance of the Temple of Zeus Theos, an inscription named its builder, one Seleukos, and the year AD 114. Within its monumental court stood a large Naos."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the temple''s entrance was on the east side [S5]; an inscription above the entrance named the builder [S6]; the builder was one Seleukos [S6]; the inscription gave the year of construction as AD 114 [S6]; the temple had a monumental court [S7]; a large Naos stood within the court [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Temple of Zeus Theos at Dura Europos (Syria) is a temple, one of the city''s most important sanctuaries [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Zeus_Theos,_Dura-Europos]; The temple''s entrance was on the east side, with an inscription above it [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Zeus_Theos,_Dura-Europos]; The inscription named the builder as one Seleukos [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Zeus_Theos,_Dura-Europos]; The inscription gave the year AD 114 [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Zeus_Theos,_Dura-Europos]; The inscription over the east entrance names Seleukos and the year 114 (independent German article) [SUPPORTED: https://de.wikipedia.org/wiki/Tempel_des_Zeus_Theos]; The temple complex had a monumental court [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Zeus_Theos,_Dura-Europos]; Within the court stood a large Naos [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Zeus_Theos,_Dura-Europos]"}]'::jsonb),
    ('a71bf02d-0df6-4b15-8436-be73a43950f4'::uuid, 'card_description', 'A theatre built in Augustus''s time using the natural hillside for seating. Much was destroyed, but the ingenious slope-built design is still visible.', 'Built in the time of Augustus, the Roman Theatre of Tarraco yielded materials for new buildings after a fire in the 3rd century. Today only the first five rows of seating remain intact.', 'teaser-card-s019:a71bf02d-0df6-4b15-8436-be73a43950f4:card_description', 'teaser-card-s019 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '9e3accccc3f288a6aa6e22ec939bda398a7dcedb1535758a43a30a7c15f19320|91b383d977a00e213cce2274e5697ad1892eedfcfa61d40f9524fb03da2bf8b3|91b383d977a00e213cce2274e5697ad1892eedfcfa61d40f9524fb03da2bf8b3', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Built in the time of Augustus, the Roman Theatre of Tarraco yielded materials for new buildings after a fire in the 3rd century. Today only the first five rows of seating remain intact."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the theatre was built in the time of Augustus [S3]; the theatre is the Roman Theatre of Tarraco [S1]; after a fire in the 3rd century, new buildings were constructed using materials salvaged from the theatre [S5]; today only the first five rows of seating remain intact [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Roman Theatre of Tarraco is a Roman theatre in the Roman colonia of Tarraco (the central claim: a theatre) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Tarraco)]; Tarraco is the ancient name of present-day Tarragona, in Spain [SUPPORTED: https://en.wikipedia.org/wiki/Tarraco]; The theatre was built in the time of Augustus [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Tarraco)]; After a fire in the 3rd century, new buildings were constructed using materials salvaged from the theatre [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Tarraco)]; Today only the first five rows of seating remain intact [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Tarraco)]"}]'::jsonb),
    ('a733c26d-3c3d-492a-b644-231da1aecf02'::uuid, 'card_description', 'Arthur''s Stone is located between the villages of Dorstone and Bredwardine, and more generally between Hereford to the east and Hay-on-Wye to the west.', 'On a ridge above the Golden Valley and the Wye Valley, Arthur''s Stone rests a capstone estimated at more than 25 tonnes on nine uprights. The tomb dates from 3700 BC to 2700 BC.', 'teaser-card-s019:a733c26d-3c3d-492a-b644-231da1aecf02:card_description', 'teaser-card-s019 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'af4e7c31856e76a1193c24eae72e3f13f598d240e7a4656e3fb291d89edcb722|720c3088a0dd39443ebbdd404be3abc4c342ef8ff205328882434dbbc919d79d|720c3088a0dd39443ebbdd404be3abc4c342ef8ff205328882434dbbc919d79d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a ridge above the Golden Valley and the Wye Valley, Arthur''s Stone rests a capstone estimated at more than 25 tonnes on nine uprights. The tomb dates from 3700 BC to 2700 BC."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the tomb is on a ridge overlooking the Golden Valley and the Wye Valley [S2]; the tomb is topped by a capstone estimated at more than 25 tonnes [S5]; the capstone rests on nine uprights [S6]; the tomb dates from 3700 BC to 2700 BC [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Arthur''s Stone is a Neolithic chambered tomb (dolmen) in Herefordshire, England (the central claim: a tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Arthur%27s_Stone,_Herefordshire]; It stands on a ridge above the Golden Valley and the Wye Valley [SUPPORTED: https://en.wikipedia.org/wiki/Arthur%27s_Stone,_Herefordshire]; The capstone is estimated to weigh more than 25 tonnes [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Arthur%27s_Stone,_Herefordshire]; The capstone rests on nine uprights [SUPPORTED: https://en.wikipedia.org/wiki/Arthur%27s_Stone,_Herefordshire]; The tomb dates from 3700 BC to 2700 BC [SUPPORTED: https://en.wikipedia.org/wiki/Arthur%27s_Stone,_Herefordshire]"}]'::jsonb),
    ('a7da6780-ed32-4c7b-8347-dff4995c0ee5'::uuid, 'card_description', 'A Roman sandstone lion standing on a deer, originally from a tomb. At nearly a meter long, it shows the monumental funerary art that once lined Roman roadsides.', 'Once a tomb ornament, the Corbridge Lion stands in sandstone on a prone animal, possibly a deer. Later a water pipe ran through its mouth, and in 1907 it was found in a water tank.', 'teaser-card-s019:a7da6780-ed32-4c7b-8347-dff4995c0ee5:card_description', 'teaser-card-s019 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '6a3920e3d852910f6eed67458c2f1b646e4677140d8095070c09338d8683c98e|0721795511ad914ee0e3fbe8c95d80c49b70410e7f68bad5cbb5e634d1eead27|0721795511ad914ee0e3fbe8c95d80c49b70410e7f68bad5cbb5e634d1eead27', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Once a tomb ornament, the Corbridge Lion stands in sandstone on a prone animal, possibly a deer. Later a water pipe ran through its mouth, and in 1907 it was found in a water tank."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Lion was originally a tomb ornament [S2]; the Lion is carved in sandstone [S1]; the lion stands on a prone animal [S1]; the prone animal is possibly a deer [S1]; later a water pipe ran through its mouth [S3]; it was found in 1907 [S4]; it was found in a water tank [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Corbridge Lion is an ancient Roman sculpture of a lion from the Roman site at Corbridge, Northumberland, England (the central claim: a sculpture) [SUPPORTED: https://en.wikipedia.org/wiki/Corbridge_Lion]; It was originally a tomb ornament [SUPPORTED: https://en.wikipedia.org/wiki/Corbridge_Lion]; The lion is made of sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Corbridge_Lion]; The lion stands on a prone animal [SUPPORTED: https://en.wikipedia.org/wiki/Corbridge_Lion]; The prone animal is possibly a deer [SUPPORTED: https://en.wikipedia.org/wiki/Corbridge_Lion]; Later a water pipe ran through its mouth (re-use after its funerary role) [SUPPORTED: https://en.wikipedia.org/wiki/Corbridge_Lion]; It was found in a water tank [SUPPORTED: https://en.wikipedia.org/wiki/Corbridge_Lion]; It was found in 1907 [SUPPORTED: https://en.wikipedia.org/wiki/Corbridge_Lion]"}]'::jsonb),
    ('a8238496-728d-4971-9f4d-3ed5ce0f9ff8'::uuid, 'card_description', 'A Romano-Celtic temple whose ruins sit beside a 16th-century farm built directly on the sanctuary''s foundations. Old stones are reused forever.', 'Called the Temple of Mars on no decisive evidence, this Romano-Celtic fanum at Corseul is one of the largest sanctuaries in all of Gaul. Its cella once held the statue of a deity.', 'teaser-card-s019:a8238496-728d-4971-9f4d-3ed5ce0f9ff8:card_description', 'teaser-card-s019 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '812bc679c42b09a0615a0d4a6a9316d62c248f1e9f03fb55d5f3cc9f2352698b|15ba25562f7a97b2b7fa0254dde52ee69afcbab3977a75d24a6fbb6909e193dd|15ba25562f7a97b2b7fa0254dde52ee69afcbab3977a75d24a6fbb6909e193dd', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Called the Temple of Mars on no decisive evidence, this Romano-Celtic fanum at Corseul is one of the largest sanctuaries in all of Gaul. Its cella once held the statue of a deity."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is called the Temple of Mars [S1, S6]; the attribution to Mars rests on no decisive evidence [S6]; it is a Romano-Celtic fanum [S1]; it is at Corseul [S1]; it is one of the largest sanctuaries in all of Gaul [S8]; its cella once held the statue of a deity [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Temple of Mars at Corseul is a Romano-Celtic fanum (a temple sanctuary) (the central claim: a temple) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Mars_(Corseul)]; It is located at Corseul, in France [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Mars_(Corseul)]; The site is called the Temple of Mars [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Mars_(Corseul)]; The name Temple of Mars rests on no decisive evidence [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Mars_(Corseul)]; It is one of the largest sanctuaries in all of Gaul [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Mars_(Corseul)]; Its cella once held the statue of a deity [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Mars_(Corseul)]"}]'::jsonb),
    ('a847144c-8a1f-4075-9999-e7a7a5a68d69'::uuid, 'card_description', 'Woodland-covered trivallate fort in Tisbury parish with three rows of ramparts and ditches, roughly triangular in plan. A large entrance opens southeast; referenced in Tisbury''s 984 AD charter.', 'Castle Ditches wraps a small hill above the River Nadder in a triple row of ramparts and ditches, the ramparts up to about 40 feet high. Its ancient name was probably Spelsbury.', 'teaser-card-s019:a847144c-8a1f-4075-9999-e7a7a5a68d69:card_description', 'teaser-card-s019 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '44e436c3829f4422b9aa953ecffada83203e19a6fc2692bd7353ca617f84a941|2dd2af5453bebcde7f447b27b14780a07a4284e6890d314744983f6fc9974073|2dd2af5453bebcde7f447b27b14780a07a4284e6890d314744983f6fc9974073', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Castle Ditches wraps a small hill above the River Nadder in a triple row of ramparts and ditches, the ramparts up to about 40 feet high. Its ancient name was probably Spelsbury."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the fort follows the contours of a small hill [S2]; the hill overlooks the River Nadder valley [S6]; the earthworks are a triple row of ramparts and ditches [S3]; the ramparts reach up to about 40 feet in height [S5]; its ancient name was probably Spelsbury [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Castle Ditches is an Iron Age hillfort in Tisbury parish, Wiltshire, England (the central claim: a hillfort) [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Ditches]; The hillfort wraps a small hill, following its contours [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Ditches]; The hill lies above the River Nadder [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Ditches]; The earthworks are a triple row of ramparts and ditches [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Ditches]; The ramparts are up to about 40 feet high [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Ditches]; Its ancient name was probably Spelsbury [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Ditches]"}]'::jsonb),
    ('a84f2dc9-ad83-4d21-95c3-c117cecbdf18'::uuid, 'card_description', 'The second-largest walled city in Roman Britain, tribal capital of the Dobunni. It served as capital of the Diocletian-era province of Britannia Prima.', 'At Cirencester stood Corinium Dobunnorum, tribal capital of the Dobunni, its forum and basilica bigger than any other in Britain apart from Londinium''s. It was finally abandoned around 430.', 'teaser-card-s019:a84f2dc9-ad83-4d21-95c3-c117cecbdf18:card_description', 'teaser-card-s019 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '465f174815d0da10232836c50929e01bab408d980494e10663e6cab7add6c0aa|0d309b3090ba86bab8324392acb7310a7d6cc56d9c779fa3de8fc4c7b60cbe89|0d309b3090ba86bab8324392acb7310a7d6cc56d9c779fa3de8fc4c7b60cbe89', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "At Cirencester stood Corinium Dobunnorum, tribal capital of the Dobunni, its forum and basilica bigger than any other in Britain apart from Londinium''s. It was finally abandoned around 430."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is at Cirencester [S1]; Corinium Dobunnorum was a settlement that stood there [S1]; it was the tribal capital of the Dobunni [S4]; its forum and basilica were bigger than any other in Britain apart from Londinium''s [S6]; it was finally abandoned [S8]; the final abandonment was around 430 [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Corinium Dobunnorum was a Roman-period (Romano-British) settlement, a town [SUPPORTED: https://en.wikipedia.org/wiki/Corinium_Dobunnorum]; The settlement stood at Cirencester [SUPPORTED: https://en.wikipedia.org/wiki/Corinium_Dobunnorum]; It was the tribal capital of the Dobunni [SUPPORTED: https://en.wikipedia.org/wiki/Corinium_Dobunnorum]; The town had a forum and a basilica [SUPPORTED: https://en.wikipedia.org/wiki/Corinium_Dobunnorum]; Its forum and basilica were bigger than any other in Britain apart from Londinium''s [SUPPORTED: https://en.wikipedia.org/wiki/Corinium_Dobunnorum]; The town was finally abandoned [SUPPORTED: https://en.wikipedia.org/wiki/Corinium_Dobunnorum]; The final abandonment was around the year 430 [SUPPORTED: https://en.wikipedia.org/wiki/Corinium_Dobunnorum]"}]'::jsonb),
    ('a8c2a8e8-d03c-4037-ab82-8c246b2d6e29'::uuid, 'card_description', 'The caves are in the valley of the river Escalona and were used by prehistoric people who left rock art. The caves were discovered in the early twentieth century by a local teacher, Jaume Garí i Poch.', 'In the valley of the river Escalona, the Cuevas de la Araña hold a painted bow and arrow goat hunt and a human figure foraging honey, a painting estimated to be around 8000 years old.', 'teaser-card-s019:a8c2a8e8-d03c-4037-ab82-8c246b2d6e29:card_description', 'teaser-card-s019 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '0c0127bc6650a3432c4640630dfe71ab8642cb343596733534020fccf41a8bce|358265bb1605af4fb33ce1181cc4d0c6dc29d4fb5aeb83d923c36bf6db3e731a|358265bb1605af4fb33ce1181cc4d0c6dc29d4fb5aeb83d923c36bf6db3e731a', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the valley of the river Escalona, the Cuevas de la Araña hold a painted bow and arrow goat hunt and a human figure foraging honey, a painting estimated to be around 8000 years old."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the caves are in the valley of the river Escalona [S2]; the caves hold a painted bow and arrow goat hunt [S2, S3]; the caves hold a painted scene of a human figure foraging honey [S2, S3]; the honey-foraging painting is estimated to be around 8000 years old [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Cuevas de la Araña are a group of caves with prehistoric rock art (in Bicorp, Valencia, Spain) [SUPPORTED: https://en.wikipedia.org/wiki/Cuevas_de_la_Ara%C3%B1a]; The caves are in the valley of the river Escalona [SUPPORTED: https://en.wikipedia.org/wiki/Cuevas_de_la_Ara%C3%B1a]; The caves hold a painted bow and arrow goat hunt [SUPPORTED: https://en.wikipedia.org/wiki/Cuevas_de_la_Ara%C3%B1a]; The caves hold a painting of a human figure foraging honey [SUPPORTED: https://en.wikipedia.org/wiki/Cuevas_de_la_Ara%C3%B1a]; The honey-gathering painting is estimated to be around 8000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Cuevas_de_la_Ara%C3%B1a]"}]'::jsonb),
    ('a945d5ef-bbbf-42bd-be5b-27c25eda9df1'::uuid, 'card_description', 'Spanning 20–30 hectares, this site was inhabited from the Copper Age through the Roman era — one of the longest-occupied settlements in the Almería region, first found in 1859.', NULL, 'teaser-card-s019:a945d5ef-bbbf-42bd-be5b-27c25eda9df1:card_description', 'teaser-card-s019 (card-clear-contradicted-after-verify): card cleared (contradicted-after-verify)', '||2689c7a8d7cfbff7a3e06ba3db02ea1898abe8c3355099fb53c66f64a77280e9', '[{"source": "lane WB run wb-ws-2026-09-27-06: contradicted-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The web check contradicts: The site spreads over 20 to 30 hectares (https://turismoroquetasdemar.es/monumentos/yacimiento-ribera-algaida-turaniana/: \"Este importante enclave de 13 hectáreas, ubicado en Roquetas de Mar (Almería)\"); The web check contradicts: The occupation ended with the Roman Era (occupied until the Roman Era) (https://turismoroquetasdemar.es/monumentos/yacimiento-ribera-algaida-turaniana/: \"hasta una posterior etapa como aldea musulmana en el siglo XI\")"}]'::jsonb),
    ('aa60e5f1-a3f5-4f27-b152-44ad38e72f54'::uuid, 'card_description', 'Two superimposed sites on a hill 159 m above Exeter: a hillfort at 145 m placed for simultaneous sight-lines to neighbouring forts, and a later Roman signal station at the summit.', 'North of Exeter, a Roman signal station crowns Stoke Hill, 159 metres above sea level; slightly below, an Iron Age hill fort is placed to sight a number of other hill forts at once.', 'teaser-card-s019:aa60e5f1-a3f5-4f27-b152-44ad38e72f54:card_description', 'teaser-card-s019 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '07f202900cc50aed87a5e633e612b5ff81d39152a95707aa7917ab3617a40733|70c6144dbafc83adbe8c24cf80052e60be6223b948c1c72a079b9853915b1b9b|70c6144dbafc83adbe8c24cf80052e60be6223b948c1c72a079b9853915b1b9b', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "North of Exeter, a Roman signal station crowns Stoke Hill, 159 metres above sea level; slightly below, an Iron Age hill fort is placed to sight a number of other hill forts at once."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Stoke Hill lies north of Exeter [S1]; a Roman signal station stands on Stoke Hill [S2]; the signal station is at the highest point of the hill (crowns it) [S5]; the signal station is 159 metres above sea level [S5]; an Iron Age hill fort is on Stoke Hill [S2]; the hill fort is slightly below the signal station [S3]; the fort''s position gives it sight of a number of other hill forts simultaneously [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Stoke Hill is a hill with a Roman signal station and an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Stoke_Hill]; The hill lies north of Exeter [SUPPORTED: https://en.wikipedia.org/wiki/Stoke_Hill]; An Iron Age hill fort is on Stoke Hill [SUPPORTED: https://en.wikipedia.org/wiki/Stoke_Hill]; The signal station on Stoke Hill is Roman [SUPPORTED: https://en.wikipedia.org/wiki/Stoke_Hill]; The signal station crowns the hill, at its highest point [SUPPORTED: https://en.wikipedia.org/wiki/Stoke_Hill]; The signal station stands 159 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Stoke_Hill]; The Iron Age hill fort lies slightly below the Roman signal station [SUPPORTED: https://en.wikipedia.org/wiki/Stoke_Hill]; The hill fort is placed to have sight of a number of other hill forts at once [SUPPORTED: https://en.wikipedia.org/wiki/Stoke_Hill]"}]'::jsonb),
    ('aaf549ca-d5c7-47da-a42a-76d0806d21e9'::uuid, 'card_description', 'A 542-meter cave packed with cave bear fossils from 65,000–31,000 years ago. Medieval people mistook the massive bones for dragon remains — hence the name.', 'Behind a 20 m wide entrance, the Drachenhöhle held cave bear and cave lion fossils, open hearths and Paleolithic stone tools, unearthed when its sediments were mined for fertilizer.', 'teaser-card-s019:aaf549ca-d5c7-47da-a42a-76d0806d21e9:card_description', 'teaser-card-s019 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '2ca52c01a02d3e94e5e7498554d5ec5631af0f5b2109fdb090f443b0a8b4208f|74f07da22ed6adc39706dae3c2f7594822f6298a7ff08b175ca38ff1907761b0|74f07da22ed6adc39706dae3c2f7594822f6298a7ff08b175ca38ff1907761b0', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Behind a 20 m wide entrance, the Drachenhöhle held cave bear and cave lion fossils, open hearths and Paleolithic stone tools, unearthed when its sediments were mined for fertilizer."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the cave entrance is 20 m wide [S1]; cave bear fossils were found in the cave [S5]; cave lion fossils were found in the cave [S5]; remains of open hearths were found in the cave [S5]; Paleolithic stone tools were found in the cave [S5]; the cave''s sediments were mined for fertilizer [S3]; the finds were unearthed during the fertilizer mining of the sediments [S3, S4, S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Drachenhöhle is a cave near Mixnitz, Styria, Austria [SUPPORTED: https://en.wikipedia.org/wiki/Drachenh%C3%B6hle]; The cave has a 20 m wide entrance [SUPPORTED: https://de.wikipedia.org/wiki/Drachenh%C3%B6hle_bei_Mixnitz]; Cave bear fossils were found in the cave [SUPPORTED: https://en.wikipedia.org/wiki/Drachenh%C3%B6hle]; Cave lion fossils were found in the cave [SUPPORTED: https://en.wikipedia.org/wiki/Drachenh%C3%B6hle]; Remains of open hearths were found in the cave [SUPPORTED: https://en.wikipedia.org/wiki/Drachenh%C3%B6hle]; Paleolithic stone tools were found in the cave [SUPPORTED: https://en.wikipedia.org/wiki/Drachenh%C3%B6hle]; The cave''s sediments were mined for fertilizer [SUPPORTED: https://en.wikipedia.org/wiki/Drachenh%C3%B6hle]; The finds were unearthed during the fertilizer mining [SUPPORTED: https://en.wikipedia.org/wiki/Drachenh%C3%B6hle]"}]'::jsonb),
    ('ab699722-9c7e-464a-b507-74a21078411c'::uuid, 'card_description', 'Watling Temple is the name given to the remains of a temple within a Roman town next to the modern A2 road in Newington, near Sittingbourne in Kent.', 'A 2019 dig at Newington in Kent rediscovered a Roman town of iron furnaces and pottery kilns, the temple now called Watling Temple, and a 7 metres wide road older than Watling Street.', 'teaser-card-s019:ab699722-9c7e-464a-b507-74a21078411c:card_description', 'teaser-card-s019 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '834c2c0d19b402726171348edae86ed270ebe461186514324fc2ed68e7cb2b6b|6119f0ba9d52fcdd57d00c4ec05816ee00bd9b5fc84691e1d2da0f8a6ce536c3|6119f0ba9d52fcdd57d00c4ec05816ee00bd9b5fc84691e1d2da0f8a6ce536c3', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "A 2019 dig at Newington in Kent rediscovered a Roman town of iron furnaces and pottery kilns, the temple now called Watling Temple, and a 7 metres wide road older than Watling Street."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "a dig took place in 2019 [S2]; the dig was at Newington in Kent [S1, S2]; the dig rediscovered a Roman town [S1, S2]; the town included iron furnaces [S2]; the town included pottery kilns [S2]; the dig found a temple, now called Watling Temple [S1, S2]; the dig found a road 7 metres wide [S2]; the road is older than Watling Street [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Watling Temple is a temple, the remains of a temple within a Roman town at Newington, Kent, England (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Watling_Temple]; The dig took place at Newington in Kent [SUPPORTED: https://en.wikipedia.org/wiki/Newington,_Swale]; An archaeological dig took place in 2019 [SUPPORTED: https://en.wikipedia.org/wiki/Watling_Temple]; The dig rediscovered a Roman town [SUPPORTED: https://en.wikipedia.org/wiki/Newington,_Swale]; The town had iron furnaces [SUPPORTED: https://en.wikipedia.org/wiki/Watling_Temple]; The town had pottery kilns [SUPPORTED: https://en.wikipedia.org/wiki/Newington,_Swale]; The temple found there is the one now called Watling Temple [SUPPORTED: https://en.wikipedia.org/wiki/Newington,_Swale]; The dig found a Roman road 7 metres wide [SUPPORTED: https://en.wikipedia.org/wiki/Newington,_Swale]; The newly found road is older than Watling Street [SUPPORTED: https://en.wikipedia.org/wiki/Watling_Temple]"}]'::jsonb),
    ('ac65ea3f-e12e-4388-a41b-dca84b6abe8f'::uuid, 'card_description', 'London''s first Roman amphitheatre was built in AD 70 from wood, but was renovated in the early 2nd century with tiled entrances and rag-stone walls.', 'Beneath Guildhall Yard lie the remains of a Roman Amphitheatre, first built of wood in AD 70, where soldiers and the public watched gladiator games, animal fights and public executions.', 'teaser-card-s019:ac65ea3f-e12e-4388-a41b-dca84b6abe8f:card_description', 'teaser-card-s019 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'a13945169d0894b1d31f425ac44147f0fc519b5c6b74c8815a9e9e0ae1776ac8|00e1dc1521589e85314e7756e39a003cfdb67faec20a8e77043bd12c83d9fc84|00e1dc1521589e85314e7756e39a003cfdb67faec20a8e77043bd12c83d9fc84', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Beneath Guildhall Yard lie the remains of a Roman Amphitheatre, first built of wood in AD 70, where soldiers and the public watched gladiator games, animal fights and public executions."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "remains of the amphitheatre lie beneath Guildhall Yard [S1]; it is a Roman amphitheatre [S1, S3]; it was first built of wood [S3]; it was first built in AD 70 [S3]; soldiers and the public watched gladiator games there [S4]; soldiers and the public watched animal fights there [S4]; soldiers and the public watched public executions there [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The site is a Roman amphitheatre in London, whose remains lie beneath Guildhall Yard (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_(London)]; The amphitheatre was first built of wood [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_(London)]; The first amphitheatre was built in AD 70 [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_(London)]; Gladiator games were held there [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_(London)]; Soldiers and the public were entertained (watched) there [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_(London)]; Animal fights took place there [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_(London)]; Public executions took place there [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_(London)]"}]'::jsonb),
    ('ad16f637-fa0c-4920-bfae-7a53dee2593a'::uuid, 'card_description', NULL, 'Three Punic rock-cut tombs came to light at Tal-Barrani during the building of a milk depot. In May 1993, trenching uncovered a multi-chambered catacomb and a Late Roman chamber tomb.', 'teaser-card-s019:ad16f637-fa0c-4920-bfae-7a53dee2593a:card_description', 'teaser-card-s019 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '415062558379f69d5d0962d09195714615392f6eec856c7dc0c55ed6874c2eb4|7252c6d8a1edf53fb7e58f83c770c809de1edc77ab65b38807a5627939fbd2f3|7252c6d8a1edf53fb7e58f83c770c809de1edc77ab65b38807a5627939fbd2f3', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Three Punic rock-cut tombs came to light at Tal-Barrani during the building of a milk depot. In May 1993, trenching uncovered a multi-chambered catacomb and a Late Roman chamber tomb."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "three Punic rock-cut tombs came to light at Tal-Barrani [S3]; the tombs were uncovered during the building of a milk depot [S4]; in May 1993 trenching uncovered a burial site [S5]; the 1993 burial site holds a multi-chambered catacomb [S5, S6, S7]; the 1993 burial site holds a Late Roman chamber tomb [S5, S6, S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Tal-Barrani in Malta is a place with ancient tombs and catacombs, a burial site (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Barrani]; Tal-Barrani is in Malta [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Barrani]; Three tombs came to light at Tal-Barrani [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Barrani]; The three tombs are Punic [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Barrani]; The three tombs are rock-cut [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Barrani]; The three tombs came to light during the building of a milk depot [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Barrani]; In May 1993 trenching uncovered a burial site at Tal-Barrani [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Barrani]; The 1993 trenching found a multi-chambered catacomb [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Barrani]; The 1993 trenching found a Late Roman chamber tomb [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Barrani]"}]'::jsonb),
    ('ad346943-799d-4c32-8ee0-22593797f59f'::uuid, 'card_description', 'Djedefre''s pyramid was architecturally different from those of his immediate predecessors in that the chambers were beneath the pyramid instead of inside.', 'At Abu Rawash lie the ruins of the Pyramid of Djedefre, Egypt''s northernmost pyramid, its chambers set not inside but beneath it, in a pit 20 m deep dug into a natural mound.', 'teaser-card-s019:ad346943-799d-4c32-8ee0-22593797f59f:card_description', 'teaser-card-s019 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '7f8cf4e65d1a227223033d18433681926c833b1497f45d0e98f578569d86abc1|b440c9d64299788e61e5994b1943e9291d403867461c28ad2861e68e755d45a6|b440c9d64299788e61e5994b1943e9291d403867461c28ad2861e68e755d45a6', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "At Abu Rawash lie the ruins of the Pyramid of Djedefre, Egypt''s northernmost pyramid, its chambers set not inside but beneath it, in a pit 20 m deep dug into a natural mound."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is at Abu Rawash [S2]; the pyramid survives as ruins [S2]; it is Egypt''s northernmost pyramid [S1]; its chambers were set beneath the pyramid, not inside it [S4]; the chambers were built in a pit 20 m deep [S6, S7]; the pit was dug into a natural mound [S5, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Pyramid of Djedefre is a pyramid in Egypt (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Djedefre]; It lies at Abu Rawash [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Djedefre]; The pyramid is now in ruins [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Djedefre]; It is Egypt''s northernmost pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Abu_Rawash]; The chambers lie beneath the pyramid, not inside it [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Djedefre]; The chambers are in a pit 20 m deep [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Djedefre]; The pit was dug into a natural mound [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Djedefre]"}]'::jsonb),
    ('ad4c7749-8844-4926-bed4-04ec7dd33543'::uuid, 'card_description', 'Fourteen edicts of Emperor Ashoka carved into boulders in the 3rd century BC, written in Kharosthi script. They promote nonviolence — carved by a king who renounced war after its horrors.', 'On a rocky outcrop outside Mansehra, three boulders carry the Mansehra Rock Edicts: fourteen edicts of the Mauryan emperor Ashoka, cut in the Kharosthi script in the 3rd century BC.', 'teaser-card-s019:ad4c7749-8844-4926-bed4-04ec7dd33543:card_description', 'teaser-card-s019 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'ca55e3906937396d40b3cf870662b7e9d3b85d9831ade9db590f9bacf1070fd6|671b7d24b1c4c8ca7c47513bf0430768a3b946608037993fb99da8660387a123|671b7d24b1c4c8ca7c47513bf0430768a3b946608037993fb99da8660387a123', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a rocky outcrop outside Mansehra, three boulders carry the Mansehra Rock Edicts: fourteen edicts of the Mauryan emperor Ashoka, cut in the Kharosthi script in the 3rd century BC."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is on a rocky outcrop outside Mansehra [S4]; three boulders carry the edicts [S2]; there are fourteen edicts [S1]; the edicts are those of the Mauryan emperor Ashoka [S1]; the edicts are cut in the Kharosthi script [S6]; the edicts date to the 3rd century BC [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Mansehra Rock Edicts are rock-inscribed edicts (a rock inscription site) at Mansehra, Pakistan (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Mansehra_Rock_Edicts]; The edicts are on a rocky outcrop outside Mansehra [SUPPORTED: https://en.wikipedia.org/wiki/Mansehra_Rock_Edicts]; The edicts are carved on three boulders [SUPPORTED: https://en.wikipedia.org/wiki/Mansehra_Rock_Edicts]; There are fourteen edicts [SUPPORTED: https://en.wikipedia.org/wiki/Mansehra_Rock_Edicts]; The edicts are those of the Mauryan emperor Ashoka [SUPPORTED: https://en.wikipedia.org/wiki/Mansehra_Rock_Edicts]; The edicts are cut in the Kharosthi script [SUPPORTED: https://en.wikipedia.org/wiki/Mansehra_Rock_Edicts]; The edicts date to the 3rd century BC [SUPPORTED: https://en.wikipedia.org/wiki/Mansehra_Rock_Edicts]"}]'::jsonb),
    ('adc55f80-0185-4eae-a227-ccc3885007be'::uuid, 'card_description', NULL, 'On the summit of a mountain that shares its name, southwest of Vilcashuamán in the Ayacucho Region, the archaeological site of Pilluchu sits at a height of about 3,800 m.', 'teaser-card-s019:adc55f80-0185-4eae-a227-ccc3885007be:card_description', 'teaser-card-s019 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', '890c1b9a2158b444a7d9321661601355d8ed6bb11a12767a9f9aebafbc3b3cd4|ba6525c690d04f92386739e363ef104acd5103f76218f8b4ce85bf77bd6a69f9|ba6525c690d04f92386739e363ef104acd5103f76218f8b4ce85bf77bd6a69f9', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the summit of a mountain that shares its name, southwest of Vilcashuamán in the Ayacucho Region, the archaeological site of Pilluchu sits at a height of about 3,800 m."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is on the summit of a mountain of the same name [S1]; it lies southwest of Vilcashuamán [S2]; it is in the Ayacucho Region [S1]; it is an archaeological site [S1]; it sits at a height of about 3,800 m [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Pilluchu is an archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Pilluchu]; Pilluchu is in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Pilluchu]; Pilluchu is in the Ayacucho Region [SUPPORTED: https://en.wikipedia.org/wiki/Pilluchu]; Pilluchu is on top of a mountain of the same name (the mountain shares its name) [SUPPORTED: https://en.wikipedia.org/wiki/Pilluchu]; Pilluchu lies southwest of Vilca