    ('ae70d78a-1aa9-43b6-b311-369e1c314343'::uuid, 'card_description', NULL, 'Venta Belgarum, tribal capital of the Belgae and later Winchester, was apparently founded around AD 70 and by the latter half of the second century had eclipsed Silchester and Chichester.', 'teaser-card-s019:ae70d78a-1aa9-43b6-b311-369e1c314343:card_description', 'teaser-card-s019 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'fe9de5b34ec45c81589ebb2324d7a69b49c544c701a5580ddabf52a3d67a9307|43f93540f29edf69f50ceaec6c232d8c7f62dcd50b6274f8d6fc304246442b59|43f93540f29edf69f50ceaec6c232d8c7f62dcd50b6274f8d6fc304246442b59', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Venta Belgarum, tribal capital of the Belgae and later Winchester, was apparently founded around AD 70 and by the latter half of the second century had eclipsed Silchester and Chichester."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Venta Belgarum was the tribal capital of the Belgae [S1, S3]; it later became Winchester [S1]; it was apparently founded around AD 70 [S2]; by the latter half of the second century it had eclipsed Silchester [S4]; by the latter half of the second century it had eclipsed Chichester [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Venta Belgarum was a Roman town (civitas capital) of the Belgae [SUPPORTED: https://en.wikipedia.org/wiki/Venta_Belgarum]; Venta Belgarum later became the city of Winchester [SUPPORTED: https://en.wikipedia.org/wiki/Venta_Belgarum]; Venta Belgarum was the tribal capital of the Belgae [SUPPORTED: https://en.wikipedia.org/wiki/Venta_Belgarum]; Venta Belgarum was apparently founded around AD 70 [SUPPORTED: https://en.wikipedia.org/wiki/Venta_Belgarum]; Venta Belgarum had eclipsed Silchester and Chichester [SUPPORTED: https://en.wikipedia.org/wiki/Venta_Belgarum]; Venta eclipsed Silchester and Chichester by the latter half of the second century [SUPPORTED: https://en.wikipedia.org/wiki/Venta_Belgarum]"}]'::jsonb),
    ('aed60d2e-9dec-442b-a7bf-86647aca27b9'::uuid, 'card_description', 'In 2008, detectorists uncovered a 3rd-century battlefield where Roman forces clashed far beyond imperial reach. Coins suggest a date during Severus Alexander or Maximinus Thrax.', 'Near the Harzhorn hill, Germanic and Roman troops fought the Battle at the Harzhorn in the 2nd quarter of the 3rd century AD, a date given by coins of Caracalla and Severus Alexander.', 'teaser-card-s019:aed60d2e-9dec-442b-a7bf-86647aca27b9:card_description', 'teaser-card-s019 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'edf6b2dc2d071005e7f735933b2a59d18c9144587d5dad310f4d8f4366a13ff1|19d6853016c722ca23ad02085f9b95135fd77a8146d9fb0a1b9fbee23b83c4bc|19d6853016c722ca23ad02085f9b95135fd77a8146d9fb0a1b9fbee23b83c4bc', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near the Harzhorn hill, Germanic and Roman troops fought the Battle at the Harzhorn in the 2nd quarter of the 3rd century AD, a date given by coins of Caracalla and Severus Alexander."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the battle took place near the Harzhorn hill [S1]; Germanic and Roman troops fought in it [S1]; it took place in the 2nd quarter of the 3rd century AD [S2]; the date is given by coins of Caracalla and Severus Alexander [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The site is the battlefield of the Battle at the Harzhorn, a battle fought between Germanic and Roman troops [SUPPORTED: https://en.wikipedia.org/wiki/Battle_at_the_Harzhorn]; The battle took place near the Harzhorn hill [SUPPORTED: https://en.wikipedia.org/wiki/Battle_at_the_Harzhorn]; Germanic and Roman troops fought each other there [SUPPORTED: https://en.wikipedia.org/wiki/Battle_at_the_Harzhorn]; The battle took place in the 2nd quarter of the 3rd century AD [SUPPORTED: https://en.wikipedia.org/wiki/Battle_at_the_Harzhorn]; The date of the battle is given by coins found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Battle_at_the_Harzhorn]; The coins that give the date are of the emperors Caracalla and Severus Alexander [SUPPORTED: https://en.wikipedia.org/wiki/Battle_at_the_Harzhorn]"}]'::jsonb),
    ('af407cc1-1f93-4570-b93c-b38952a87fa0'::uuid, 'card_description', 'Founded by Phoenicians around 770 BC, making it nearly 2,800 years old. Its Roman theatre, Moorish fortress, and Renaissance cathedral sit within steps of each other.', 'Most scholars say Phoenicians from Tyre founded Málaga as Malaka about 770 BC. Its oldest architectural remains are the Phoenician walls; its Roman theatre was rediscovered in 1951.', 'teaser-card-s019:af407cc1-1f93-4570-b93c-b38952a87fa0:card_description', 'teaser-card-s019 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'd064d0db52b626fe9e3279e632df7c338a3eb894e44348152e25e796244aadc6|522de14af25543e89a2fb0860c33ab6474a1acb2908d2f048dbf99174a790ab8|522de14af25543e89a2fb0860c33ab6474a1acb2908d2f048dbf99174a790ab8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Most scholars say Phoenicians from Tyre founded Málaga as Malaka about 770 BC. Its oldest architectural remains are the Phoenician walls; its Roman theatre was rediscovered in 1951."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "most scholars say Málaga was founded by Phoenicians from Tyre [S2]; it was founded as Malaka [S2]; the founding was about 770 BC [S2]; its oldest architectural remains are the Phoenician walls [S6]; its Roman theatre was rediscovered in 1951 [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Málaga is an ancient city, founded as Malaka [SUPPORTED: https://en.wikipedia.org/wiki/M%C3%A1laga]; Málaga (Malaka) was founded by Phoenicians [SUPPORTED: https://en.wikipedia.org/wiki/M%C3%A1laga]; The Phoenicians who founded Málaga came from Tyre [SUPPORTED: https://en.wikipedia.org/wiki/M%C3%A1laga]; Málaga was founded about 770 BC [SUPPORTED: https://en.wikipedia.org/wiki/M%C3%A1laga]; Most scholars hold this founding account [SUPPORTED: https://en.wikipedia.org/wiki/M%C3%A1laga]; Málaga''s oldest architectural remains are the Phoenician walls [SUPPORTED: https://en.wikipedia.org/wiki/M%C3%A1laga]; Málaga''s Roman theatre was rediscovered in 1951 [SUPPORTED: https://en.wikipedia.org/wiki/M%C3%A1laga]"}]'::jsonb),
    ('b0526108-102b-4092-9666-ae9947e68cf7'::uuid, 'card_description', NULL, 'On the northern shore of Windermere lie the ruins of Ambleside Roman Fort. A tombstone found at Ambleside tells of one killed within the fort by the enemy, yet Roman control continued.', 'teaser-card-s019:b0526108-102b-4092-9666-ae9947e68cf7:card_description', 'teaser-card-s019 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '7c6ff503303074d67d6d45642e04b241a23e4b37ae359d955adbb4d3380153b9|c615c2785b28f386e25ae0e407e6129257d00cec2b591309ebb8881940d76f36|c615c2785b28f386e25ae0e407e6129257d00cec2b591309ebb8881940d76f36', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the northern shore of Windermere lie the ruins of Ambleside Roman Fort. A tombstone found at Ambleside tells of one killed within the fort by the enemy, yet Roman control continued."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the ruins lie on the northern shore of Windermere [S2]; the ruins are those of Ambleside Roman Fort [S1, S2]; a tombstone was found at Ambleside [S7]; the tombstone''s inscription tells of one killed within the fort by the enemy [S7]; Roman control continued [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ambleside Roman Fort is the modern name of the remains of a Roman fort of the province of Britannia [SUPPORTED: https://en.wikipedia.org/wiki/Ambleside_Roman_Fort]; The ruins lie on the northern shore of Windermere [SUPPORTED: https://en.wikipedia.org/wiki/Ambleside_Roman_Fort]; A tombstone found at Ambleside bears an inscription translating as killed within the fort by the enemy [SUPPORTED: https://en.wikipedia.org/wiki/Ambleside_Roman_Fort]; The fort was attacked at some point, by the enemy [SUPPORTED: https://en.wikipedia.org/wiki/Ambleside_Roman_Fort]; Roman control of the area continued [SUPPORTED: https://en.wikipedia.org/wiki/Ambleside_Roman_Fort]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s019', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s019'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s019'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s019'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s019' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
